local config = {
  ui_story_5080_50800100_1_dialog_content = "本次的作戰行動雖然大獲全勝。但恕我直言，您的計畫……連我也覺得冒險。",
  ui_story_5080_50800100_2_dialog_content = "哈，有時候就是得下點猛藥嘛。",
