  ui_story_5080_50800100_22_dialog_content = "希望那個辦法，能對她產生影響。",
  ui_story_5080_50800100_23_dialog_content = "但實際會如何呢？就看她還是否願意再接納新的「雛鳥」，再次展翅高飛了。",
  ui_story_5080_50800100_24_dialog_content = "卡蓮，小心妳的左腳！",
  ui_story_5080_50800100_25_dialog_content = "小心點，PlayerName，快低頭！",
  ui_story_5080_50800100_26_dialog_content = "薇絲！謝謝……妳後面！",
  ui_story_5080_50800100_27_dialog_content = "休想！",
  ui_story_5080_50800100_28_dialog_content = "怎麼回事？暗鬼居然這麼多……",
  ui_story_5080_50800100_29_dialog_content = "這畢竟是紅油沙漠的邊緣。這片沙漠至今還有許多區域尚未掃蕩。",
  ui_story_5080_50800100_30_dialog_content = "可是這未免也太多了……為什麼緋長官會說<color=#FFB400>前輩</color>就在這裡等我？這裡……根本沒辦法會面啊。",
  ui_story_5080_50800100_31_dialog_content = "薇絲，接下來我要說的，是大元帥個人直接指名的任務。",
