  ui_story_5080_50800100_37_dialog_content = "<color=#FFB400>蕾切爾。</color>",
  ui_story_5080_50800100_38_dialog_content = "不行，這樣下去沒完沒了。薇絲，妳確定是這條路線嗎？",
  ui_story_5080_50800100_39_dialog_content = "不會錯的。根據這份地圖，這已經是「最佳路線」了。",
  ui_story_5080_50800100_40_dialog_content = "那份地圖是這次的「隊長」提供的吧？我們都還沒見到對方，薇絲妳怎麼那麼肯定呢？",
  ui_story_5080_50800100_41_dialog_content = "薇絲，妳對這次的任務特別熱情。",
  ui_story_5080_50800100_42_dialog_content = "甚至可說是期待了。妳直到淩晨都還在準備任務事項。",
  ui_story_5080_50800100_43_dialog_content = "這是因為……那個人，是我們第三軍團的傳奇。",
  ui_story_5080_50800100_44_dialog_content = "還在學校的時候，我們就是聽著她的輝煌戰績長大的。",
  ui_story_5080_50800100_45_dialog_content = "在比我還小時，她就已經是獲得多枚勳章的隊長。",
  ui_story_5080_50800100_46_dialog_content = "第三軍團的……為什麼我們從來沒聽過這號人物？",
  ui_story_5080_50800100_47_dialog_content = "我也不知道，前輩她突然消失了一段時間，就好像再也找不到她了……",
  ui_story_5080_50800100_48_dialog_content = "嘎——",
  ui_story_5080_50800100_49_dialog_content = "暗鬼數量太多了！",
  ui_story_5080_50800100_50_dialog_content = "這個落地點太糟了……",
  ui_story_5080_50800100_51_dialog_content = "如果現在喊<color=#FFB400>臨空者號</color>來接應的話……不行，那樣只會引來更多暗鬼。",
  ui_story_5080_50800100_52_dialog_content = "就連那個還沒見到面的人，也會有危險！",
  ui_story_5080_50800100_53_dialog_content = "沒辦法了，卡蓮，我來幫妳控住暗鬼，妳找機會突襲高地！",
  ui_story_5080_50800100_54_dialog_content = "什麼？PlayerName，別分心！快回到我身後方向。",
  ui_story_5080_50800100_55_dialog_content = "嘎啊——！！！",
  ui_story_5080_50800100_56_dialog_content = "（從沙子底下突襲過來？！糟糕，我躲不開了！）",
  ui_story_5080_50800100_57_dialog_content = "PlayerName！",
  ui_story_5080_50800100_58_dialog_content = "與其擔心別人，不如先學會自保，<color=#FFB400>空裔一號</color>。",
  ui_story_5080_50800100_59_dialog_content = "只是一點小小的「測試」，這樣就沒輒了嗎？",
  ui_story_5080_50800100_60_dialog_content = "算了，這也是我的責任。這樣一來，我也瞭解你們的實力。",
  ui_story_5080_50800100_61_dialog_content = "PlayerName，你沒事吧？",
  ui_story_5080_50800100_62_dialog_content = "我、我沒事……那個人是……",
  ui_story_5080_50800100_63_dialog_content = "目光銳利，身旁圍繞著「鷹隼」……",
  ui_story_5080_50800100_64_dialog_content = "還有這身「精銳隊長」的衣服……",
  ui_story_5080_50800100_65_dialog_content = "您就是……！",
  ui_story_5080_50800100_66_dialog_content = "您就是<color=#FFB400>鷹眼小隊</color>的隊長對吧？！謝謝您救了PlayerName！",
  ui_story_5080_50800100_67_dialog_content = "<color=#FFB400>鷹眼</color>……客套話就免了。",
  ui_story_5080_50800100_68_dialog_content = "聽軍團長說，你們已經是合作已久的搭檔了，為什麼還會出現這樣的錯誤？",
  ui_story_5080_50800100_69_dialog_content = "空裔，你對自己的搭檔投入太多無謂的個人感情了。",
  ui_story_5080_50800100_70_dialog_content = "在我看來，你的槍兵護衛完全能勝任保護你的職責，她還能撐很久。",
  ui_story_5080_50800100_71_dialog_content = "你不該擅自離位，應該等薇絲去狙殺重要目標。",
  ui_story_5080_50800100_72_dialog_content = "還有妳。妳也是小隊長吧？",
  ui_story_5080_50800100_73_dialog_content = "是、是的。",
  ui_story_5080_50800100_74_dialog_content = "妳也是專精偵察，那就不應該……自顧自地逞強。",
  ui_story_5080_50800100_75_dialog_content = "（她這是……在關心薇絲？）",
  ui_story_5080_50800100_76_dialog_content = "像你們這樣的三人小組，在面對暗鬼潮時，應該以快速突圍為主，迅速行動。",
  ui_story_5080_50800100_77_dialog_content = "既然有狙擊手，完全可以把衝擊壓力都交給這名槍兵，其他人專心對付首要目標。",
  ui_story_5080_50800100_78_dialog_content = "但既然已經選擇防守……槍兵，為什麼總是分心去保護狙擊手？她比妳靈活，妳應該保護的是自己身後的目標。",
  ui_story_5080_50800100_79_dialog_content = "（好、好嚴肅。）",
  ui_story_5080_50800100_80_dialog_content = "總覺得會想到某個人……",
  ui_story_5080_50800100_81_dialog_content = "都看著我幹嘛？",
  ui_story_5080_50800100_82_dialog_content = "這位啟光的隊長，妳明明已經來到，卻以「測試」的理由袖手旁觀，妳的表現會讓我對妳產生「難以信任」的印象。",
  ui_story_5080_50800100_83_dialog_content = "……無所謂。我本來以為只會來兩個人，沒想到連白夜城的「公主」也在這裡。",
  ui_story_5080_50800100_84_dialog_content = "妳事先調查過我的身家？",
  ui_story_5080_50800100_85_dialog_content = "別訝異，這是一眼就能看出的情報。",
  ui_story_5080_50800100_86_dialog_content = "還有你，空之末裔……本來啟光的任務不准許帶外人，但既然這是長官的安排，我沒有意見。",
  ui_story_5080_50800100_87_dialog_content = "我該說謝謝嗎……",
  ui_story_5080_50800100_88_dialog_content = "我是蕾切爾，是你們本次任務的直屬長官。",
  ui_story_5080_50800100_89_dialog_content = "呃，妳好？我叫……",
  ui_story_5080_50800100_90_dialog_content = "在任務期間，我們是團隊。任務完成後，我們將就地解散。為了方便指揮，我將為各位提供行動代號。",
  ui_story_5080_50800100_91_dialog_content = "你是「空裔一號」。",
  ui_story_5080_50800100_92_dialog_content = "妳是「幼龍二號」。",
  ui_story_5080_50800100_93_dialog_content = "……",
  ui_story_5080_50800100_94_dialog_content = "還有妳，白夜城的公主。妳是完完全全的編外人員……但既然妳一同前來，表示妳也同意任務規約。",
  ui_story_5080_50800100_95_dialog_content = "從現在開始，我會稱妳為「白色槍兵」。",
  ui_story_5080_50800100_96_dialog_content = "該說我就知道嗎……不愧是啟光的士兵……",
  ui_story_5080_50800100_97_dialog_content = "這樣很不尊重人。",
  ui_story_5080_50800100_98_dialog_content = "這就是特種小隊的行事風格吧？卡蓮，我想隊長她沒有惡意。",
  ui_story_5080_50800100_99_dialog_content = "妳們也可以用「獵鷹零號」或「隊長」來稱呼我。",
  ui_story_5080_50800100_100_dialog_content = "……瞭解，啟……「獵鷹零號」。",
  ui_story_5080_50800100_101_dialog_content = "（明明剛剛的時候還說著關心的話，為什麼這時候卻……簡直是在刻意擺架子。）",
  ui_story_5080_50800100_102_dialog_content = "蕾……隊長！也許您還不認識我，我是您的後輩！雖然我們的專職不同，但我一直有在注意您的消息。",
  ui_story_5080_50800100_103_dialog_content = "我的……消息……？",
  ui_story_5080_50800100_104_dialog_content = "嗯嗯，還在上學時，我們就知道您率領鷹眼小隊大顯神威的事情。",
  ui_story_5080_50800100_105_dialog_content = "後來，每次您拿到英雄勳章，緋軍團長都會特地告速我們，要我們好好向您看齊。",
  ui_story_5080_50800100_106_dialog_content = "雖然後來因為發生很多事情，我和PlayerName開始結伴同行，沒怎麼回到啟光，但我還是很憧憬您。",
  ui_story_5080_50800100_107_dialog_content = "先前沒有了您的消息，大家都議論紛紛。現在看來，鷹眼小隊一定是去執行機密任務了吧？",
  ui_story_5080_50800100_108_dialog_content = "……",
  ui_story_5080_50800100_109_dialog_content = "這次任務既然是由您帶領，一定也會出色完成！我還要趁這個機會，好好向您學習呢。",
  ui_story_5080_50800100_110_dialog_content = "總之，閒聊的事情放一邊。跟我來，我介紹一下任務內容。",
  ui_story_5080_50800100_111_dialog_content = "（她好像……很不想聊到過去的事情？明明是傳奇人物……）",
  ui_story_5080_50800100_112_dialog_content = "這次任務，是由我帶隊進入紅油扳手盤踞的沙漠深處，調查一種特殊的暗鬼。",
  ui_story_5080_50800100_113_dialog_content = "這種暗鬼出沒於高溫環境，能夠利用岩漿的力量，牠們出沒的區域都會留下明顯痕跡。",
  ui_story_5080_50800100_114_dialog_content = "牠們是極度危險的存在，切記不要再逞強。",
  ui_story_5080_50800100_115_dialog_content = "你們應該完全在我的指揮下行動，以免發生不測。",
  ui_story_5080_50800100_116_dialog_content = "此外，我個人還有想要調查的事情，這些時候你們可以自由行動。",
  ui_story_5080_50800100_117_dialog_content = "是什麼事情？",
  ui_story_5080_50800100_118_dialog_content = "妳聽過<color=#FFB400>自由鳥</color>小隊嗎？",
  ui_story_5080_50800100_119_dialog_content = "好像沒有……抱歉。",
  ui_story_5080_50800100_120_dialog_content = "那就沒事了。這不包含在這次任務裡，你們不必配合我。但……如果碰到線索，可以告訴我。",
  ui_story_5080_50800100_121_dialog_content = "我們和紅油扳手的醒山大哥關係不錯，如果是要調查暗鬼的事情，我想直接去問他也可以。",
  ui_story_5080_50800100_122_dialog_content = "原來如此……這或許就是大元帥指名你們的原因。能用交情換取情報，很有效率。我批准了，你們去吧。",
  ui_story_5080_50800100_123_dialog_content = "咦？那隊長妳……",
  ui_story_5080_50800100_124_dialog_content = "我是啟光的隊長，和沙漠的遊匪沒有交情。一旦見面，我怕自己會忍不住逮捕那些通緝犯。",
  ui_story_5080_50800100_125_dialog_content = "你們去吧——不必管我，我會自己去做偵察任務。",
  ui_story_5080_50800100_126_dialog_content = "一個人怎麼行？這裡這麼危險……不如我們兩兩分隊？",
  ui_story_5080_50800100_127_dialog_content = "比起和剛剛見面的我組隊，還是已經有默契的你們比較有戰鬥力。",
  ui_story_5080_50800100_128_dialog_content = "原地解散，你們自己去紅油扳手收集情報——這是命令。",
  ui_story_5080_50800100_129_dialog_content = "之後我會自己來找你們。",
  ui_story_5080_50800100_130_dialog_content = "這樣就走了？好乾脆。",
  ui_story_5080_50800100_131_dialog_content = "雖然無禮，但確實是個不錯的士兵。",
  ui_story_5080_50800100_132_dialog_content = "……薇絲，我有點在意蕾切爾說的那支小隊。",
  ui_story_5080_50800100_133_dialog_content = "「自由鳥」，然後還有「鷹眼」……是我多心了嗎？總覺得其中有什麼關聯。",
  ui_story_5080_50800100_134_dialog_content = "可能因為這就是我們啟光的命名方式——咦？「自由鳥」是啟光的小隊……",
  ui_story_5080_50800100_135_dialog_content = "本次任務明明是調查暗鬼，為什麼那位隊長會打聽一支啟光小隊的情報？",
  ui_story_5080_50800100_136_dialog_content = "明明看似毫無關係……但我覺得，像她那樣的人，一定不會做沒意義的事情。",
  ui_story_5080_50800100_137_dialog_content = "被你們這麼一說，搞得我也在意起來了啦……不管了，只要問問菲莉詩情報長，一定會有答案。",
  ui_story_5080_50800100_138_dialog_content = "呵啊——小薇絲怎麼突然傳通訊給我？遇上難題了嗎喵？",
  ui_story_5080_50800100_139_dialog_content = "菲莉詩長官，我想詢問一下，您有聽過「自由鳥」小隊，或是這支小隊的相關情報嗎？",
  ui_story_5080_50800100_140_dialog_content = "嗯……聽起來是我們啟光的小隊喵，但這已經是早期的命名方式了。不過在檔案裡查一下，應該會有相關情報。",
  ui_story_5080_50800100_141_dialog_content = "拜託了，菲莉詩長官，我真的很好奇這個，下次回去一定請您吃小魚干。",
  ui_story_5080_50800100_142_dialog_content = "如果不是機密資訊，告訴你們也沒關係——記得要帶小魚干給我喔喵。",
  ui_story_5080_50800100_143_dialog_content = "久等了喵——近四十年前，這支隊伍完美執行過幾十次極危任務，是不折不扣的精銳特種小隊喵。",
  ui_story_5080_50800100_144_dialog_content = "但是，「自由鳥」的最後一次任務記錄，是在紅油沙漠中尋找某種東西……失敗了喵。",
  ui_story_5080_50800100_145_dialog_content = "在這之後的檔案內容被高度加密，是連我也沒辦法私自查閱的級別喵。",
  ui_story_5080_50800100_146_dialog_content = "怎麼回事？居然有連菲莉詩情報長也無法自由查閱的資料？",
  ui_story_5080_50800100_147_dialog_content = "連小隊長也完全查不到喵——這種級別的加密，還持續這麼多年，恐怕是叛逃人員喵。",
  ui_story_5080_50800100_148_dialog_content = "這可真不得了了呀，小薇絲，妳是從哪聽到這個名字的喵？",
  ui_story_5080_50800201_1_dialog_content = "好慢啊，醒山怎麼還沒有來？",
  ui_story_5080_50800201_2_dialog_content = "他們都在遠處忙得不行，在做什麼工程嗎？",
  ui_story_5080_50800201_3_dialog_content = "……",
  ui_story_5080_50800201_4_dialog_content = "薇絲，妳怎麼一副心事重重的樣子，沒事吧？",
  ui_story_5080_50800201_5_dialog_content = "嗯？我沒事……我只是在想，隊長為什麼會問起從前的小隊。",
  ui_story_5080_50800201_6_dialog_content = "而且還是涉嫌隊長叛逃的隊伍。",
  ui_story_5080_50800201_7_dialog_content = "從她的樣子看來，她應該是負責偵察任務的特種兵吧？",
  ui_story_5080_50800201_8_dialog_content = "會不會，她是在調查叛逃者？",
  ui_story_5080_50800201_9_dialog_content = "但那已經是多年前的往事了，事到如今還要繼續追查，很奇怪吧？",
  ui_story_5080_50800201_10_dialog_content = "也許是因為，叛逃的隊伍和蕾切爾有關係？",
  ui_story_5080_50800201_11_dialog_content = "「自由鳥」……還有「鷹眼」……",
  ui_story_5080_50800201_12_dialog_content = "喲！你們幾個，怎麼都愁眉苦臉的？",
  ui_story_5080_50800201_13_dialog_content = "醒山！",
  ui_story_5080_50800201_14_dialog_content = "好久不見了，你看起來結實不少嘛。怎麼樣，考不考慮來我們這裡工作？",
  ui_story_5080_50800201_15_dialog_content = "那個我想還是……",
  ui_story_5080_50800201_16_dialog_content = "哈哈哈哈哈！沒關係，到時候你想再說吧！所以呢？你們今天特地來找我有什麼事？",
  ui_story_5080_50800201_17_dialog_content = "其實，我們是因為接到一項特殊任務……你在沙漠裡，有見過特別的暗鬼嗎？",
  ui_story_5080_50800201_18_dialog_content = "蛤？像是什麼？",
  ui_story_5080_50800201_19_dialog_content = "呃，我想想……可能是看起來很熱的暗鬼，喜歡火山？",
  ui_story_5080_50800201_20_dialog_content = "你在說什麼啊，我們這火山地帶的暗鬼多得要命。",
  ui_story_5080_50800201_21_dialog_content = "一種親近火山，能夠利用岩漿的暗鬼。",
  ui_story_5080_50800201_22_dialog_content = "牠們異常強大，走過的地方都會留下明顯痕跡。",
  ui_story_5080_50800201_23_dialog_content = "請問，你對這種暗鬼有什麼印象嗎？",
  ui_story_5080_50800201_24_dialog_content = "「岩漿的暗鬼」……不可能，那種暗鬼已經十幾年沒有……",
  ui_story_5080_50800201_25_dialog_content = "你知道？",
  ui_story_5080_50800201_26_dialog_content = "請多說一些，我們正需要牠的情報。",
  ui_story_5080_50800201_27_dialog_content = "本來這都是些老掉牙的事情了，而且還牽扯到我們家的過去……",
  ui_story_5080_50800201_28_dialog_content = "沒辦法，既然你們想知道，告訴你們也無妨。",
  ui_story_5080_50800201_29_dialog_content = "我確實知道那樣的暗鬼。不……應該說我們<color=#FFB400>紅油扳手</color>的老成員，都和牠有血海深仇。",
  ui_story_5080_50800201_30_dialog_content = "這話怎麼說？",
  ui_story_5080_50800201_31_dialog_content = "那是十多年前<color=#FFB400>暗潮危機</color>時的事了。那時我還是當家的手下，當個跑腿的小鬼頭。",
  ui_story_5080_50800201_32_dialog_content = "突然有一天，暗鬼像沙塵暴一樣席捲過來，我們被逼著逃離當時的老家。",
  ui_story_5080_50800201_33_dialog_content = "為了掩護我們這些小年輕撤退，當家的帶著人力墊後去了。",
  ui_story_5080_50800201_34_dialog_content = "我還記得……其中有隻強到令人心生恐懼的暗鬼，連地上的沙子都被岩漿燒成玻璃……",
  ui_story_5080_50800201_35_dialog_content = "嗯？",
  ui_story_5080_50800201_36_dialog_content = "妳沒有聽清楚嗎？我說……",
  ui_story_5080_50800201_37_dialog_content = "嗯？！",
  ui_story_5080_50800201_38_dialog_content = "嗚哇——！",
  ui_story_5080_50800201_39_dialog_content = "對不起！<color=#FFB400>受詛咒的狂戰士</color>，快來幫忙！",
  ui_story_5080_50800201_40_dialog_content = "危險，PlayerName！",
  ui_story_5080_50800201_41_dialog_content = "啊啊啊——給我停下來！",
  ui_story_5080_50800201_42_dialog_content = "嗚哇啊啊——",
  ui_story_5080_50800201_43_dialog_content = "摯愛的甜心，歌聲不會停～",
  ui_story_5080_50800201_44_dialog_content = "不愧是<color=#FFB400>受詛咒的狂戰士</color>！真是驚人的怪力！",
  ui_story_5080_50800201_45_dialog_content = "澤塔？！還有芭芭拉和小不點？妳們這是在做什麼？",
  ui_story_5080_50800201_46_dialog_content = "居然把卡車撞到營地裡來，未免也太胡……",
  ui_story_5080_50800201_47_dialog_content = "沒時間解釋了，快上車！",
  ui_story_5080_50800201_48_dialog_content = "蛤啊？！",
  ui_story_5080_50800201_49_dialog_content = "<color=#FFB400>受詛咒的狂戰士</color>呀！你難道沒聽到嗎？那來自遠方的腳步聲——",
  ui_story_5080_50800201_50_dialog_content = "看，她來了，那個「精銳沙漠獵手」！",
  ui_story_5080_50800201_51_dialog_content = "你們看，那是——",
  ui_story_5080_50800201_52_dialog_content = "<size=45>蕾切爾！！！</size>",
  ui_story_5080_50800201_53_dialog_content = "那又是什麼傢伙？澤塔，給我好好說清楚，妳們到底惹了什麼事啊？",
  ui_story_5080_50800201_54_dialog_content = "糟了糟了……",
  ui_story_5080_50800201_55_dialog_content = "嗚哇，安全氣囊把我卡住了，我下不來！",
  ui_story_5080_50800201_56_dialog_content = "小事，妳等一下，我把車門拆了。",
  ui_story_5080_50800201_57_dialog_content = "不行，必須遠離那個傢伙才行，她可是「魔王的爪牙」！",
  ui_story_5080_50800201_58_dialog_content = "「紅油的遊匪」，把偷走的東西還給我！",
  ui_story_5080_50800201_59_dialog_content = "哼，口氣還真囂張啊。",
  ui_story_5080_50800201_60_dialog_content = "仔細一看，這不是啟光的士兵嗎？",
  ui_story_5080_50800201_61_dialog_content = "蕾切爾、醒山，你們聽我說……",
  ui_story_5080_50800201_62_dialog_content = "閉嘴！",
  ui_story_5080_50800201_63_dialog_content = "不僅是啟光的傢伙，還追著我家的小鬼，一路把車子逼到我們基地裡……",
  ui_story_5080_50800201_64_dialog_content = "不僅在沙漠為非作歹，還膽大妄為偷走我的「戰友」，不可原諒……",
  ui_story_5080_50800201_65_dialog_content = "噢？要打一架嗎？我很久沒有和你們交手了。",
  ui_story_5080_50800201_66_dialog_content = "放馬過來。",
  ui_story_5080_50800201_67_dialog_content = "情況不對，薇絲、卡蓮，我們得快點阻止他們。",
  ui_story_5080_50800201_68_dialog_content = "聽我指揮，一起上。",
  ui_story_5080_50800202_1_dialog_content = "飛來飛去的煩人小東西——給我全部飛走吧！",
  ui_story_5080_50800202_2_dialog_content = "這樣妳就沒轍了吧？",
  ui_story_5080_50800202_3_dialog_content = "別動，如果你不想被炸上天的話——",
  ui_story_5080_50800202_4_dialog_content = "喔？居然趁機在我手上黏了炸彈，妳動作很快嘛。",
  ui_story_5080_50800202_5_dialog_content = "這個距離引爆，你我都無法倖存。",
  ui_story_5080_50800202_6_dialog_content = "是個不怕死的傢伙呢……有趣，那就讓我們試試吧！",
  ui_story_5080_50800202_7_dialog_content = "目標是「紅油寇首」，用我的命來換也值得……",
  ui_story_5080_50800202_8_dialog_content = "別別別，你們兩個，千萬別衝動！",
  ui_story_5080_50800202_9_dialog_content = "是啊，隊長，我們還有任務在身！想想任務！",
  ui_story_5080_50800202_10_dialog_content = "醒山，要是你有個三長兩短，其他人怎麼辦？",
  ui_story_5080_50800202_11_dialog_content = "這裡還有其他的「孩子」。",
  ui_story_5080_50800202_12_dialog_content = "「孩子」？",
  ui_story_5080_50800202_13_dialog_content = "嗚——",
  ui_story_5080_50800202_14_dialog_content = "到底發生了什麼事情，我們好好談，事情都可以解決，好嗎？",
  ui_story_5080_50800202_15_dialog_content = "是我們招惹到「魔王爪牙」，我會獨自承擔！放過我的夥伴們！",
  ui_story_5080_50800202_16_dialog_content = "……",
  ui_story_5080_50800202_17_dialog_content = "澤塔，到底怎麼回事？",
  ui_story_5080_50800202_18_dialog_content = "事情還要從「勇者澤塔」的傳說開始——",
  ui_story_5080_50800202_19_dialog_content = "勇者澤塔苦心鑽研、修煉的車技，仍然不敵那個「賽車上的魔女」。",
  ui_story_5080_50800202_20_dialog_content = "一定是因為魔女找到「空之末裔」這樣強大的幫手吧！勇者澤塔這麼想著，踏上了尋找夥伴的道路。",
  ui_story_5080_50800202_21_dialog_content = "正在這時，傳說中的<color=#FFB400>吟遊詩人新星</color>芭芭拉！然後還有蕾吉娜，兩人正在為了吟遊詩人的比賽而爭執。",
  ui_story_5080_50800202_22_dialog_content = "「呐，勇者澤塔，用妳的力量幫幫我吧。」",
  ui_story_5080_50800202_23_dialog_content = "「只要有妳在，我一定能在蕾吉娜之前拉攏到更多觀眾，而觀眾就是我的力量來源！」",
  ui_story_5080_50800202_24_dialog_content = "「不錯不錯！但可別忘了，還有我！勇者澤塔最忠實的<color=#FFB400>武器大師</color>。」",
  ui_story_5080_50800202_25_dialog_content = "啊！難道說，這就是勇者的光輝所吸引來的夥伴嗎？",
  ui_story_5080_50800202_26_dialog_content = "於是，勇者的小隊踏上征途——為了在蕾吉娜之前，從狂暴之路的巡演中爭取到更多觀眾！",
  ui_story_5080_50800202_27_dialog_content = "就用這輛最新最潮的<color=#FFB400>紅油超級偶像舞台</color>戰車，決戰於——",
  ui_story_5080_50800202_28_dialog_content = "停停停！什麼跟什麼啊，妳快點說重點啦。",
  ui_story_5080_50800202_29_dialog_content = "……哎。",
  ui_story_5080_50800202_30_dialog_content = "就在勇者的小隊闖蕩險惡沙漠，把希望的歌聲傳遞出去時，勇者澤塔發現了！",
  ui_story_5080_50800202_31_dialog_content = "一隻落單的、不屈的孤鷹。",
  ui_story_5080_50800202_32_dialog_content = "那傢伙，很適合用來幫舞台打光或改裝成音響設備呢。",
  ui_story_5080_50800202_33_dialog_content = "武器大師那麼說著——可是，澤塔發現了它高貴的精神。",
  ui_story_5080_50800202_34_dialog_content = "所以澤塔決定，把這隻孤鷹也收為夥伴！",
  ui_story_5080_50800202_35_dialog_content = "可是，追逐孤鷹的邪惡爪牙卻找上門來！不僅一直緊追不捨，還攻擊我們！",
  ui_story_5080_50800202_36_dialog_content = "她的子彈太嚇人了，勇者澤塔不敢……不、不對，勇者澤塔為了夥伴的安全，絕不能輕易停車！",
  ui_story_5080_50800202_37_dialog_content = "所以就加速撞到家裡來？",
  ui_story_5080_50800202_38_dialog_content = "澤塔相信，狂戰士你一定能停住卡車！",
  ui_story_5080_50800202_39_dialog_content = "你啊……",
  ui_story_5080_50800202_40_dialog_content = "……胡鬧。",
  ui_story_5080_50800202_41_dialog_content = "把<color=#FFB400>獵鷹三號</color>還給我。",
  ui_story_5080_50800301_1_dialog_content = "原來它叫<color=#FFB400>獵鷹三號</color>？這個名字……也好酷！",
  ui_story_5080_50800301_2_dialog_content = "好吧……既然<color=#FFB400>獵鷹三號</color>不是無主的孤鷹……澤塔這就還給妳，不要再打了……",
  ui_story_5080_50800301_3_dialog_content = "喂喂，想來就來，想走就走嗎？",
  ui_story_5080_50800301_4_dialog_content = "啟光的傢伙，大搖大擺地破壞我們營地、傷害我們家的小鬼，還想一走了之？",
  ui_story_5080_50800301_5_dialog_content = "隨你怎麼說，是她們搶走<color=#FFB400>獵鷹三號</color>在先。",
  ui_story_5080_50800301_6_dialog_content = "妳沒聽過嗎？紅油的遊匪啊，就是「幫親不幫理」！",
  ui_story_5080_50800301_7_dialog_content = "還想要打？",
  ui_story_5080_50800301_8_dialog_content = "好了啦，你們兩個！",
  ui_story_5080_50800301_9_dialog_content = "發生了什麼事？外面一團亂，這裡也好像很緊張的樣子呢。",
  ui_story_5080_50800301_10_dialog_content = "耶利亞？！",
  ui_story_5080_50800301_11_dialog_content = "什麼風連妳都吹過來了？",
  ui_story_5080_50800301_12_dialog_content = "我也不想出門……不過醒山，你有聽到火山在「咆哮」嗎？",
  ui_story_5080_50800301_13_dialog_content = "「怒嘯火山」醒了，就像<color=#FFB400>十五年前</color>的那次那樣。",
  ui_story_5080_50800301_14_dialog_content = "什麼？",
  ui_story_5080_50800301_15_dialog_content = "老大，這邊沒事吧！",
  ui_story_5080_50800301_16_dialog_content = "總算是把外面的障礙都處理完了，大夥沒事吧？",
  ui_story_5080_50800301_17_dialog_content = "喂——小不點、芭芭拉，還有小澤塔，妳們在哪裡啊？",
  ui_story_5080_50800301_18_dialog_content = "你們這些傢伙，不要隨便衝進來！",
  ui_story_5080_50800301_19_dialog_content = "我們還在談正經事，喂，給我站住！這些笨蛋——！！！",
  ui_story_5080_50800301_20_dialog_content = "外面在說「怒嘯火山」甦醒了，是真的假的啊？",
  ui_story_5080_50800301_21_dialog_content = "小澤塔，快回答大叔，妳沒事吧？",
  ui_story_5080_50800301_22_dialog_content = "我沒事喔！「心地善良的公主殿下」！",
  ui_story_5080_50800301_23_dialog_content = "我都聽到「怒嘯火山」裡的動靜了，一直嗚嗚在叫，一定是醒了沒錯。",
  ui_story_5080_50800301_24_dialog_content = "明明自從<color=#FFB400>暗潮危機</color>期間噴發過後，就一直沉眠至今，到底發生——",
  ui_story_5080_50800301_25_dialog_content = "<size=45>都給我閉嘴！！！</size>",
  ui_story_5080_50800301_26_dialog_content = "可惡，啟光的那傢伙呢？",
  ui_story_5080_50800301_27_dialog_content = "嗯？什麼啟光的傢伙？我嗎？",
  ui_story_5080_50800301_28_dialog_content = "呼——呼——",
  ui_story_5080_50800301_29_dialog_content = "呼——跑到這裡來……呼——應該就沒、沒事了吧。",
  ui_story_5080_50800301_30_dialog_content = "先、先別說話，先整理呼吸。",
  ui_story_5080_50800301_31_dialog_content = "剛剛真是危險，就算我們和醒山有交情，應該也不好收場。",
  ui_story_5080_50800301_32_dialog_content = "幸好你抓住機會，讓我們逃了出來。",
  ui_story_5080_50800301_33_dialog_content = "……我早就料到了，那些傢伙不會講道理。",
  ui_story_5080_50800301_34_dialog_content = "畢竟那是一群逃兵組成的遊匪。",
  ui_story_5080_50800301_35_dialog_content = "沒有那種事！",
  ui_story_5080_50800301_36_dialog_content = "紅油扳手的人，才沒有那麼不堪……要是和醒山好好說，他還是會講道理的。",
  ui_story_5080_50800301_37_dialog_content = "他們在紅油沙漠待了這麼久，說不定也會有「自由鳥」的情報……",
  ui_story_5080_50800301_38_dialog_content = "爭辯逃兵的可信度毫無意義，話題就此打住吧。",
  ui_story_5080_50800301_39_dialog_content = "在你們去那些傢伙營地的時候，我也偵察到本次任務調查對象的蹤跡，跟我來。",
  ui_story_5080_50800301_40_dialog_content = "聽人說話啊……",
  ui_story_5080_50800301_41_dialog_content = "看，被高溫燒灼過的沙子，然後還有這種火山灰的痕跡……",
  ui_story_5080_50800301_42_dialog_content = "不會錯的，就在前面。",
  ui_story_5080_50800301_43_dialog_content = "但是……這些痕跡不只一道。",
  ui_story_5080_50800301_44_dialog_content = "目標很可能已經「增殖」，你們要小心。",
  ui_story_5080_50800301_45_dialog_content = "我看到牠們了，隊長！",
  ui_story_5080_50800301_X45_dialog_content = "吼……嗚——",
  ui_story_5080_50800301_46_dialog_content = "這是……岩漿……不，暗鬼？",
  ui_story_5080_50800301_47_dialog_content = "和以前見過的暗鬼都不一樣，牠們看起來簡直就是行走的岩漿……",
  ui_story_5080_50800301_48_dialog_content = "這些暗鬼樣子好詭異，弱點也很難看出來。",
  ui_story_5080_50800301_49_dialog_content = "有那樣高溫的能量保護，遠程攻擊多半也成效不彰。",
  ui_story_5080_50800301_50_dialog_content = "準備戰鬥。",
  ui_story_5080_50800301_51_dialog_content = "可是……",
  ui_story_5080_50800301_52_dialog_content = "白色槍兵，妳的能力和牠們相剋，而且擅長正面衝突，妳來打頭陣。",
  ui_story_5080_50800301_53_dialog_content = "啟光的隊長，妳還無權指揮我。",
  ui_story_5080_50800301_54_dialog_content = "妳能呼喚那種「天馬的力量」吧？在正面戰中，妳要借助牠突然飛起，居高臨下打個出其不意。",
  ui_story_5080_50800301_55_dialog_content = "從牠們的構造看起來，這些怪物很難把防禦完全覆蓋全身。一旦出現破綻，妳這招就能成為殺招。",
  ui_story_5080_50800301_56_dialog_content = "……",
  ui_story_5080_50800301_57_dialog_content = "幼龍二號，妳可以發揮自身的機動性，在白色槍兵交戰時，發動「速射感應」攻擊那些暗鬼。",
  ui_story_5080_50800301_58_dialog_content = "不管是怎麼樣的暗鬼，在攻擊時一定會暴露弱點，那時候就是妳發揮的瞬間。",
  ui_story_5080_50800301_59_dialog_content = "一旦命中弱點，就能讓牠們失衡。白色槍兵，妳斬殺牠們的機會就會到來。",
  ui_story_5080_50800301_60_dialog_content = "是！",
  ui_story_5080_50800301_61_dialog_content = "我和獵鷹一二三號也會負責火力壓制，把牠們逼向白色槍兵。",
  ui_story_5080_50800301_62_dialog_content = "持續用火力騷擾能有效阻止牠們集合，讓我們可以一一斬殺這些怪物。",
  ui_story_5080_50800301_63_dialog_content = "這個戰術……就照妳說的做。",
  ui_story_5080_50800301_64_dialog_content = "（只見過一次，就把卡蓮和薇絲的能力摸得一清二楚，還量身制訂了戰術……）",
  ui_story_5080_50800301_65_dialog_content = "空裔一號。",
  ui_story_5080_50800301_66_dialog_content = "有！",
  ui_story_5080_50800301_67_dialog_content = "戰鬥中的指揮就交給你了。",
  ui_story_5080_50800301_68_dialog_content = "欸？",
  ui_story_5080_50800301_69_dialog_content = "無論戰前的準備多充足，戰場上總是瞬息萬變。",
  ui_story_5080_50800301_70_dialog_content = "你能看到我們所無法目睹的「光」，我相信你在戰鬥中的指揮會比我更清晰。",
  ui_story_5080_50800301_71_dialog_content = "……而且，你們已經是成熟的組合了。",
  ui_story_5080_50800301_72_dialog_content = "尤其是……比起我，你更適合當她們的「搭檔」。",
  ui_story_5080_50800301_73_dialog_content = "蕾切爾，妳……",
  ui_story_5080_50800301_74_dialog_content = "是隊長。",
  ui_story_5080_50800301_75_dialog_content = "準備上了，空裔一號！",
  ui_story_5080_50800302_1_dialog_content = "隊長，小心！",
  ui_story_5080_50800302_2_dialog_content = "唔……白色槍兵，就是現在！",
  ui_story_5080_50800302_3_dialog_content = "「超越靈魂之刺」！",
  ui_story_5080_50800302_4_dialog_content = "糟糕，隊長受傷了，得趕快……",
  ui_story_5080_50800302_5_dialog_content = "幼龍二號，妳在發什麼呆，還有一隻往妳那去了！",
  ui_story_5080_50800302_6_dialog_content = "獵鷹一號，獵鷹二號，快阻止牠！",
  ui_story_5080_50800302_7_dialog_content = "嘎嗚——！",
  ui_story_5080_50800302_8_dialog_content = "……趕上了。",
  ui_story_5080_50800302_9_dialog_content = "全部解決了……真是好險。",
  ui_story_5080_50800302_10_dialog_content = "幼龍二號，妳在做什麼？",
  ui_story_5080_50800302_11_dialog_content = "我……",
  ui_story_5080_50800302_12_dialog_content = "身為一名士兵，妳放太多個人情感了。",
  ui_story_5080_50800302_13_dialog_content = "就算我受傷了，妳也不應該在第一時間救援我，任務才是重點。",
  ui_story_5080_50800302_14_dialog_content = "我們剿滅了一個中隊的暗鬼，這點傷害已經是效率最高、代價最低的成果了。",
  ui_story_5080_50800302_15_dialog_content = "妳……是和他們相處太久了，忘記自己是啟光的士兵嗎？",
  ui_story_5080_50800302_16_dialog_content = "不……不是那樣的。",
  ui_story_5080_50800302_17_dialog_content = "妳說得太過分了，薇絲也只是關心妳的安危而已。",
  ui_story_5080_50800302_18_dialog_content = "……在戰鬥時分心，就會產生意想不到的代價，要是她剛剛受傷了怎麼辦？",
  ui_story_5080_50800302_19_dialog_content = "聽從我的安排，即使任務失敗，責任也都在我。",
  ui_story_5080_50800302_20_dialog_content = "我會對我的部下負責……只要你們相信我。",
  ui_story_5080_50800302_21_dialog_content = "確實，如妳所言，妳是非常成熟老練的隊長。",
  ui_story_5080_50800302_22_dialog_content = "我明白妳的想法了。",
  ui_story_5080_50800302_23_dialog_content = "卡蓮？",
  ui_story_5080_50800302_24_dialog_content = "真是的……薇絲，妳還好嗎？",
  ui_story_5080_50800302_25_dialog_content = "嗯……",
  ui_story_5080_50800302_26_dialog_content = "這些暗鬼……這種屍體的「模樣」……",
  ui_story_5080_50800302_27_dialog_content = "隊長，妳還在流血……",
  ui_story_5080_50800302_28_dialog_content = "讓她去吧，她是不會聽妳的。",
  ui_story_5080_50800302_29_dialog_content = "那個人，身上背負著我們有所不知的「重擔」。",
  ui_story_5080_50800302_30_dialog_content = "那種眼神，我無比清楚。原來啟光的士兵，也會和白夜城的人那麼相似……",
  ui_story_5080_50800302_31_dialog_content = "我在前線服役已久，見過的暗鬼數不勝數。",
  ui_story_5080_50800302_32_dialog_content = "但這些暗鬼，我還是第一次看到。",
  ui_story_5080_50800302_33_dialog_content = "從牠們頭部的結構來看，這些暗鬼已經脫離「暗面」很久了。",
  ui_story_5080_50800302_34_dialog_content = "而且，牠們的生理結構，和那些戰鬥特化的暗鬼不太一樣。",
  ui_story_5080_50800302_35_dialog_content = "牠們皮膚能夠耐熱，身體有儲備能量的結構……這些暗鬼是順應環境演化成這樣的。",
  ui_story_5080_50800302_36_dialog_content = "真奇怪，牠們的屍體殘留時間更長……",
  ui_story_5080_50800302_37_dialog_content = "……還有一點，牠們太像了。",
  ui_story_5080_50800302_38_dialog_content = "妳注意到了？真是敏銳……除了感情之外，妳是非常棒的偵察隊長。",
  ui_story_5080_50800302_39_dialog_content = "不好意思，「太像」是什麼意思？我覺得很多暗鬼都很像啊。",
  ui_story_5080_50800302_40_dialog_content = "其他的暗鬼與其說是「像」，不如說是「一模一樣」。",
  ui_story_5080_50800302_41_dialog_content = "很多士兵甚至推測，暗鬼根本不是「繁衍」出來的。",
  ui_story_5080_50800302_42_dialog_content = "但這些一定是「後代」……牠們很像，卻又不完全一樣。",
  ui_story_5080_50800302_43_dialog_content = "牠們有著相似的「遺傳性」，就像是代代繁衍出來的一般。",
  ui_story_5080_50800302_44_dialog_content = "檔案裡提到，上次調查到這種暗鬼，是在三十多年前。",
  ui_story_5080_50800302_45_dialog_content = "這些暗鬼的個頭比當時的報告更小，力量更弱，恐怕是以某種方式「繁衍」下來的後代……",
  ui_story_5080_50800302_46_dialog_content = "不錯。",
  ui_story_5080_50800302_47_dialog_content = "<color=#FFB400>暗潮危機</color>時，紅油扳手裡也有人見過這種暗鬼。和當時相比，你們打敗的這些更加弱小。",
  ui_story_5080_50800302_48_dialog_content = "耶利亞？！妳怎麼也變得神出鬼沒了？！",
  ui_story_5080_50800302_49_dialog_content = "再怎麼說，這片沙漠都是我的管轄區。",
  ui_story_5080_50800302_50_dialog_content = "妳……居然能繞開獵鷹三號的探測？",
  ui_story_5080_50800302_51_dialog_content = "喔？那架無人機是叫這個名字嗎？它似乎有點故障了。",
  ui_story_5080_50800302_52_dialog_content = "什麼？獵鷹三號，快回來！",
  ui_story_5080_50800302_53_dialog_content = "沒想到，十五年過去，火山再次咆哮時，這些傢伙又出現了……",
  ui_story_5080_50800302_54_dialog_content = "妳知道些什麼嗎？耶利亞。",
  ui_story_5080_50800302_55_dialog_content = "呵呵，我也只是追尋著<color=#FFB400>答案</color>而來。",
  ui_story_5080_50800302_56_dialog_content = "獵鷹三號的「傳導模組」壞了，上面還被裝了奇怪的零件……",
  ui_story_5080_50800302_57_dialog_content = "喂喂，聽得到嗎？妳們好——",
  ui_story_5080_50800302_58_dialog_content = "這個聲音是……",
  ui_story_5080_50800302_59_dialog_content = "澤塔？",
  ui_story_5080_50800302_60_dialog_content = "託<color=#FFB400>武器大師</color>的福，事先在孤鷹上留下了這個……叫什麼來著？",
  ui_story_5080_50800302_61_dialog_content = "喔！「後門」……好奇怪的名字啊！不管了，反正我們在這隻孤鷹上留了聯絡方式。",
  ui_story_5080_50800302_62_dialog_content = "如果妳想<color=#FFB400>治好它</color>，就來「仙女長老」耶利亞的家吧。",
  ui_story_5080_50800302_63_dialog_content = "……別看我呀，這是什麼人設？",
  ui_story_5080_50800302_64_dialog_content = "獵鷹三號被敵人動了手腳，我得馬上修好它才行——",
  ui_story_5080_50800302_65_dialog_content = "！！！",
  ui_story_5080_50800302_66_dialog_content = "工具袋……什麼時候被燒壞了？",
  ui_story_5080_50800302_67_dialog_content = "妳太專注於任務了，戰鬥中也不顧自身安危，這袋子早在剛剛的攻勢中就壞了。",
  ui_story_5080_50800302_68_dialog_content = "她們在妳家——這件事與妳有關嗎？信使？",
  ui_story_5080_50800302_69_dialog_content = "我只為了過去的某個答案而來，沒有任何其他想法。",
  ui_story_5080_50800302_70_dialog_content = "不過在妳身上，我看到了很熟悉的影子。",
  ui_story_5080_50800302_71_dialog_content = "或許妳們應該跟上來，到時候我們都能找到自己想要的東西也說不定。",
  ui_story_5080_50800302_72_dialog_content = "……",
  ui_story_5080_50800302_73_dialog_content = "耶利亞是信使公會的長老，我們可以信任她。",
  ui_story_5080_50800302_74_dialog_content = "走吧。",
  ui_story_5080_50800401_1_dialog_content = "真是不好意思，還麻煩妳載我們。",
  ui_story_5080_50800401_2_dialog_content = "也不是第一次載你了，坐好吧。",
  ui_story_5080_50800401_3_dialog_content = "唔……",
  ui_story_5080_50800401_4_dialog_content = "啊！前面就是紅油扳手的營地，快趴下！",
  ui_story_5080_50800401_5_dialog_content = "別擔心，他們正忙著。",
  ui_story_5080_50800401_6_dialog_content = "修不過來，根本修不過來！！！可惡，澤塔跑哪去了，要是讓我找到她，我一定饒不了她！！！",
  ui_story_5080_50800401_7_dialog_content = "這不是耶利亞的車嗎？耶利亞！他們飯都煮好了，要不要留下來一起吃？",
  ui_story_5080_50800401_8_dialog_content = "下次吧。",
  ui_story_5080_50800401_9_dialog_content = "那我就去找青瞳，改天再約吧。",
  ui_story_5080_50800401_10_dialog_content = "耶利亞小姐，開慢點，那邊有陷阱。",
  ui_story_5080_50800401_11_dialog_content = "多謝提醒。",
  ui_story_5080_50800401_12_dialog_content = "哇！耶利亞，妳看，這本書根本不是《成為紅油老大指南》吧？他們是不是騙我不認識字啊？",
  ui_story_5080_50800401_13_dialog_content = "根本就沒有那種書，不騙你騙誰？",
  ui_story_5080_50800401_14_dialog_content = "耶利亞，上次送工具過來辛苦了，這週有時間我就去幫妳改車。",
  ui_story_5080_50800401_15_dialog_content = "行。",
  ui_story_5080_50800401_16_dialog_content = "耶利亞，妳……妳像有點變了呢。",
  ui_story_5080_50800401_17_dialog_content = "明明以前還住在很難找到的地方，現在卻和紅油扳手的大家都很熟。",
  ui_story_5080_50800401_18_dialog_content = "呵呵，PlayerName老哥還真是敏銳。",
  ui_story_5080_50800401_19_dialog_content = "人總是會變的。",
  ui_story_5080_50800401_20_dialog_content = "多虧妳，我說不定也開始想和人產生聯繫了。",
  ui_story_5080_50800401_21_dialog_content = "……有、有點擠，薇絲。這個後座沒那麼大——",
  ui_story_5080_50800401_22_dialog_content = "音樂就該就該就該放聲高歌自在逍遙！！！",
  ui_story_5080_50800401_23_dialog_content = "啊～傻瓜總是吵吵鬧鬧～",
  ui_story_5080_50800401_24_dialog_content = "失敗、挫折、恐懼讓你開始偷跑！",
  ui_story_5080_50800401_25_dialog_content = "偷跑的行為招惹煩惱！",
  ui_story_5080_50800401_26_dialog_content = "小澤塔的車開得不夠好～但朋友會說沒什麼大不了～",
  ui_story_5080_50800401_27_dialog_content = "薇絲，妳臉色不太好，怎麼了嗎？",
  ui_story_5080_50800401_28_dialog_content = "沒、沒什麼……隊長，車子這麼顛簸，您還是不要自己包紮吧。",
  ui_story_5080_50800401_29_dialog_content = "等我們到了，我再替您包紮。",
  ui_story_5080_50800401_30_dialog_content = "沒關係，我已經習慣一個人了。",
  ui_story_5080_50800401_31_dialog_content = "這種環境也沒什麼……還有，不用說敬語。我也沒大妳幾歲。",
  ui_story_5080_50800401_32_dialog_content = "妳的年紀比我小一歲，卻已經是獨當一面的隊長了，我沒什麼值得妳尊敬的。",
  ui_story_5080_50800401_33_dialog_content = "妳是啟光的偵察兵對吧？看那身衣服，妳恐怕還是個精銳。",
  ui_story_5080_50800401_34_dialog_content = "我看得出來，妳和其他的小鳥不同，是不折不扣的猛禽。",
  ui_story_5080_50800401_35_dialog_content = "什麼樣的任務需要出動妳呢？",
  ui_story_5080_50800401_36_dialog_content = "這是啟光的機密，與妳無關。",
  ui_story_5080_50800401_37_dialog_content = "這可不好說，命運無常啊。",
  ui_story_5080_50800401_38_dialog_content = "像妳這樣的猛禽會被指引來此，一定有著更深的含義。",
  ui_story_5080_50800401_39_dialog_content = "小醒山，你看，就是這樣的<color=#FFB400>痕跡</color>。",
  ui_story_5080_50800401_40_dialog_content = "和卡夫卡說的一樣，這就是耶利亞之前提過的<color=#FFB400>痕跡</color>。",
  ui_story_5080_50800401_41_dialog_content = "不要那樣叫我啦……這種痕跡，不就是岩漿嗎？",
  ui_story_5080_50800401_42_dialog_content = "好端端的，怎麼會有岩漿出現在這邊？",
  ui_story_5080_50800401_43_dialog_content = "再往前走看看，也許會有別的發現。",
  ui_story_5080_50800401_44_dialog_content = "喂，羅伊！這些是暗鬼對吧？雖然破破爛爛的，這毫無疑問就是暗鬼的殘骸吧？",
  ui_story_5080_50800401_45_dialog_content = "有人消滅了牠們……好奇怪啊，大叔我從來沒見過消逝程度這麼慢的暗鬼。",
  ui_story_5080_50800401_46_dialog_content = "羅伊，你看清楚，這是不是你「當初」看到的<color=#FFB400>那種暗鬼</color>？",
  ui_story_5080_50800401_47_dialog_content = "十五年前，我們逃走的時候……<color=#FFB400>當家的</color>替我們墊後，被<color=#FFB400>那種暗鬼</color>給……",
  ui_story_5080_50800401_48_dialog_content = "只有你能分辨出牠們了。",
  ui_story_5080_50800401_49_dialog_content = "很像，但和<color=#FFB400>當初那一隻</color>還是不一樣。看來，這些應該是<color=#FFB400>牠的子嗣</color>。",
  ui_story_5080_50800401_50_dialog_content = "可惡的傢伙，十幾年過去，竟然還生幼崽了嗎？",
  ui_story_5080_50800401_51_dialog_content = "繼續追！跟著這些傢伙的痕跡，我們去掀了<color=#FFB400>那傢伙</color>的老巢！",
  ui_story_5080_50800401_52_dialog_content = "這已經是火山邊緣了——氣溫變得好熱。看來小耶利亞說得沒錯，牠真的醒了。",
  ui_story_5080_50800401_53_dialog_content = "怎麼痕跡到這裡就沒了？",
  ui_story_5080_50800401_54_dialog_content = "這是其他暗鬼的腳印……也許是牠們破壞了痕跡。",
  ui_story_5080_50800401_55_dialog_content = "「怒嘯火山」是深埋地底的火山，這下面也許隱藏著諸多道路。",
  ui_story_5080_50800401_56_dialog_content = "沒有準確的目標，盲目探地底太危險了。",
  ui_story_5080_50800401_57_dialog_content = "嘖，別給我躲著！全都放馬過來吧！",
  ui_story_5080_50800401_58_dialog_content = "我已經不是十幾歲的小鬼頭了，出來跟我算總帳！！！",
  ui_story_5080_50800401_59_dialog_content = "可惡！！！",
  ui_story_5080_50800401_60_dialog_content = "別再攻擊牆壁了，這裡的結構很脆弱啊——嗚哇啊啊啊啊——",
  ui_story_5080_50800401_61_dialog_content = "<color=#e8d9bb>牆壁在拳頭下震動，引起洞窟深處的迴響。窸窸窣窣的，無數暗鬼的聲音從暗處傳來。</color>",
  ui_story_5080_50800401_62_dialog_content = "這裡馬上要塌了！不過看起來主人終於來迎客了。",
  ui_story_5080_50800401_63_dialog_content = "看，羅伊！是那些傢伙沒錯吧？",
  ui_story_5080_50800401_64_dialog_content = "終於忍不住了嗎？看來牠們的巢穴就在這附近。",
  ui_story_5080_50800401_65_dialog_content = "小醒山，小心點……還有，速戰速決。",
  ui_story_5080_50800401_66_dialog_content = "哼，我的扳手可不是吃素的——上了，羅伊！",
  ui_story_5080_50800402_1_dialog_content = "請進，各位隨意吧，反正我這裡也不會有人——",
  ui_story_5080_50800402_2_dialog_content = "看！勇者澤塔無敵的畫技！",
  ui_story_5080_50800402_3_dialog_content = "唔喔噢——栩栩如生！",
  ui_story_5080_50800402_4_dialog_content = "這也只是勇者澤塔微不足道的小特技！",
  ui_story_5080_50800402_5_dialog_content = "你們又偷闖進來亂塗鴉了嗎？",
  ui_story_5080_50800402_6_dialog_content = "「仙女長老」的家太古板了！這可是救世主的親筆，高興地收下吧！",
  ui_story_5080_50800402_7_dialog_content = "……算了，不要弄壞東西就好。",
  ui_story_5080_50800402_8_dialog_content = "而且我不是什麼「仙女長老」，納努塞爾長老才適合這稱呼。",
  ui_story_5080_50800402_9_dialog_content = "澤塔沒見過她，不過名字聽起來很棒呢——啊對了，我們幫妳把信件歸納好啦。",
  ui_story_5080_50800402_10_dialog_content = "亂糟糟的郵寄品都整理過了，垃圾我們也都清掉了。",
  ui_story_5080_50800402_11_dialog_content = "是嗎？真了不起。",
  ui_story_5080_50800402_12_dialog_content = "嘿嘿，一直以來多虧了「仙女長老」的任務獎勵，勇者澤塔可不會白拿！",
  ui_story_5080_50800402_13_dialog_content = "知道了，別把顏料弄到信件上——還有你們幾個也別站著，坐吧。",
  ui_story_5080_50800402_14_dialog_content = "妳真的變了很多，耶利亞……妳與他人有了更多羈絆，而且看起來更開心了。",
  ui_story_5080_50800402_15_dialog_content = "這真是太好了。",
  ui_story_5080_50800402_16_dialog_content = "是這樣嗎？不過有了這些小鬼頭，日子確實沒那麼無聊。",
  ui_story_5080_50800402_17_dialog_content = "這架仿生無人機「獵鷹三號」能偵查亦能攻擊，是啟光前沿技術的結晶……你們真的知道怎麼修理嗎？",
  ui_story_5080_50800402_18_dialog_content = "武器大師，交給妳了！",
  ui_story_5080_50800402_19_dialog_content = "手指捕捉測試開始，左、右、左……「傳導模組」壞了，恐怕是撞擊導致的。",
  ui_story_5080_50800402_20_dialog_content = "哼，包在我們最令人驕傲的武器大師身上吧，她無所不能！",
  ui_story_5080_50800402_21_dialog_content = "武器大師，妳一定會幫我吧？",
  ui_story_5080_50800402_22_dialog_content = "我盡量。",
  ui_story_5080_50800402_23_dialog_content = "把工具給我，我幫妳一起修。",
  ui_story_5080_50800402_24_dialog_content = "這些東西是我的戰友……不能隨隨便便交給別人。",
  ui_story_5080_50800402_25_dialog_content = "別著急，「中立的英雄：飛鷹射手」！",
  ui_story_5080_50800402_26_dialog_content = "……",
  ui_story_5080_50800402_27_dialog_content = "澤塔就是這樣，不用太放在心上。",
  ui_story_5080_50800402_28_dialog_content = "既然孤鷹是妳的部下，勇者澤塔我就不會再對妳的夥伴出手。",
  ui_story_5080_50800402_29_dialog_content = "傷害了孤鷹是我的責任，勇者澤塔會替牠療傷！",
  ui_story_5080_50800402_30_dialog_content = "可是妳不是都交給小不點去弄嗎……",
  ui_story_5080_50800402_31_dialog_content = "空之末裔！沒想到再次宿命般的相遇，竟然又讓你找到這麼強力的幫手！",
  ui_story_5080_50800402_32_dialog_content = "給我好好說話。",
  ui_story_5080_50800402_33_dialog_content = "不過勇者澤塔永不言棄！",
  ui_story_5080_50800402_34_dialog_content = "妳是中立的英雄也好，既然可以跟空之末裔組隊，就一定也能和勇者澤塔同行！",
  ui_story_5080_50800402_35_dialog_content = "就算妳險些墮入魔道也沒關係，我不介意接受像妳這樣強大的部下！",
  ui_story_5080_50800402_36_dialog_content = "我……",
  ui_story_5080_50800402_37_dialog_content = "妳不用說，勇者澤塔都知道！",
  ui_story_5080_50800402_38_dialog_content = "像妳這樣驕傲的人，一定會非常不服氣吧。",
  ui_story_5080_50800402_39_dialog_content = "沒關係，勇者澤塔會跟妳公平競爭，所以我才會讓武器大師在那之前先治好孤鷹。",
  ui_story_5080_50800402_40_dialog_content = "一定會讓妳輸得心服口服……哼哼，有了像「飛鷹射手」這樣強大的部下，那個「魔女」將不再是我的對手。",
  ui_story_5080_50800402_41_dialog_content = "妳的發言聽起來比較像反派吧。",
  ui_story_5080_50800402_42_dialog_content = "隊長，妳別跟她一般見識。澤塔只是……說話比較有趣。",
  ui_story_5080_50800402_43_dialog_content = "是、是啊，隊長，等她們修好獵鷹三號， 我們就走。",
  ui_story_5080_50800402_44_dialog_content = "沒關係。",
  ui_story_5080_50800402_45_dialog_content = "聽到沒，澤塔？還不快點道歉……咦？",
  ui_story_5080_50800402_46_dialog_content = "雖然妳是紅油的遊匪……那個……",
  ui_story_5080_50800402_47_dialog_content = "既然妳事前不知道，這次就算了。",
  ui_story_5080_50800402_48_dialog_content = "妳還很年輕，不要像那些人一樣成為沙漠的惡霸了。",
  ui_story_5080_50800402_49_dialog_content = "哼哼，妳根本不明白！澤塔的夢想是成為傳說中的英雄，沙漠的救世主！",
  ui_story_5080_50800402_50_dialog_content = "那就好。先前我突然襲擊你們，沒傷到人吧？",
  ui_story_5080_50800402_51_dialog_content = "咦？沒有沒有！勇者澤塔怎麼會因為這點事情就受傷呢？也沒有害怕，絕對沒有嚇得哭出來喔！",
  ui_story_5080_50800402_52_dialog_content = "很好，妳很勇敢。",
  ui_story_5080_50800402_53_dialog_content = "我沒看錯吧……？",
  ui_story_5080_50800402_54_dialog_content = "澤塔被治得服服貼貼的。",
  ui_story_5080_50800402_55_dialog_content = "隊長她……還有這樣的一面嗎？",
  ui_story_5080_50800402_56_dialog_content = "也許正是卡蓮說的那樣，她是非常成熟的隊長，所以其實她很擅長照顧後輩。",
  ui_story_5080_50800402_57_dialog_content = "可是……",
  ui_story_5080_50800402_58_dialog_content = "（那樣子才是真正的她嗎？為什麼對我們卻那麼冷淡？）",
  ui_story_5080_50800402_59_dialog_content = "（她是為了任務而撇開感情嗎？還是……藏了更深的苦衷呢？）",
  ui_story_5080_50800402_60_dialog_content = "真有趣，沙漠裡候鳥總是來來去去，但我還是頭一回看到會收起爪子的猛禽。",
  ui_story_5080_50800402_61_dialog_content = "澤塔，這架無人機外殼裂縫裡進了沙子，有些線路因此燒毀了。",
  ui_story_5080_50800402_62_dialog_content = "修起來很麻煩，我不太擅長這麼精密的工作。",
  ui_story_5080_50800402_63_dialog_content = "什、什麼？",
  ui_story_5080_50800402_64_dialog_content = "妳要是搞不定，把工具給我，我可以自己修。",
  ui_story_5080_50800402_65_dialog_content = "不不不不不等一下！妳給我等一下！",
  ui_story_5080_50800402_66_dialog_content = "勇者澤塔可是說好要擔起責任，表現出高手對決的氣度了啊！",
  ui_story_5080_50800402_67_dialog_content = "正準備起步的時候，怎麼可以突然熄火……武器大師，妳要放棄嗎？",
  ui_story_5080_50800402_68_dialog_content = "想想那位「機械怪客」歐緹！她就很擅長精密工作！妳要輸給她嗎？",
  ui_story_5080_50800402_69_dialog_content = "妳說……什麼？",
  ui_story_5080_50800402_70_dialog_content = "給我等著瞧！這點小事難不倒我！",
  ui_story_5080_50800402_71_dialog_content = "什麼歐緹，根本就不能和我相提並論！我馬上就修好給你們看！",
  ui_story_5080_50800402_72_dialog_content = "我好像開始明白，為什麼小不點老是被澤塔「牽著走」了。",
  ui_story_5080_50800402_73_dialog_content = "看來這不是一時能解決的事情。天色不早了，諸位不如留下來吧。",
  ui_story_5080_50800402_74_dialog_content = "這樣會不會太打擾妳了？",
  ui_story_5080_50800402_75_dialog_content = "我也差不多習慣被打擾了。",
  ui_story_5080_50800402_76_dialog_content = "而且……「猛禽」小姐，我想我們一定有很多話可以聊。",
  ui_story_5080_50800500_1_dialog_content = "<color=#e8d9bb>夜漸深，沙漠的氣溫逐漸下降。看似空無一人的沙堆下暗流湧動，傳來聲響。</color>",
  ui_story_5080_50800500_2_dialog_content = "<color=#e8d9bb>黑影鼓動著，從地心衝出！</color>",
  ui_story_5080_50800500_3_dialog_content = "啊——呸！",
  ui_story_5080_50800500_4_dialog_content = "呸呸呸呸呸呸！",
  ui_story_5080_50800500_5_dialog_content = "呸、咳咳咳……呸！羅、羅伊，你沒事吧？",
  ui_story_5080_50800500_6_dialog_content = "小醒山，下次要把洞窟弄塌先說一聲——大叔這把老骨頭，經不起這樣折騰啊。",
  ui_story_5080_50800500_7_dialog_content = "哈、哈——真是的，好久沒這麼痛快了！",
  ui_story_5080_50800500_8_dialog_content = "痛快是痛快啦，但洞窟塌了，要怎麼找牠們的巢穴……而且這數量，看起來真是個麻煩。",
  ui_story_5080_50800500_9_dialog_content = "不管了，回去後你什麼也不用說，就說我們搞定那種暗鬼的巢穴了。",
  ui_story_5080_50800500_10_dialog_content = "這樣說真的行嗎？我們殺掉的那些暗鬼顯然不是全部。",
  ui_story_5080_50800500_11_dialog_content = "下面的地道四通八達，看牠們的樣子，搞不好真正的大本營是在火山裡……",
  ui_story_5080_50800500_12_dialog_content = "那我們就殺進火山裡！",
  ui_story_5080_50800500_13_dialog_content = "這樣做真的好嗎？",
  ui_story_5080_50800500_14_dialog_content = "那裡很可能會有前首領也搞不定的那種暗鬼，比我們見到的更大更強。",
  ui_story_5080_50800500_15_dialog_content = "我們得快點通報大夥們，要大家團結起來迎敵才行。",
  ui_story_5080_50800500_16_dialog_content = "危險來臨，我當然會說。但事情要是和<color=#FFB400>那隻傢伙</color>有關，我絕對不能讓小鬼頭們上。",
  ui_story_5080_50800500_17_dialog_content = "有什麼不一樣？當初小醒山你不也是小鬼頭的年紀，照樣當上老大了。",
  ui_story_5080_50800500_18_dialog_content = "我就是明白那種感覺，才不可能告訴每個人！我們和<color=#FFB400>那隻傢伙</color>的恩怨，跟家裡的小鬼頭無關！",
  ui_story_5080_50800500_19_dialog_content = "現在握著扳手的人是我，我才是繼承位置的老大。我會幫當家的報仇，了結以前兄弟的遺憾，所以……",
  ui_story_5080_50800500_20_dialog_content = "先什麼也別說，羅伊。",
  ui_story_5080_50800500_21_dialog_content = "「我會幫小鬼頭解決一切」……是嗎？前首領說過這樣的話，就跟你一樣。",
  ui_story_5080_50800500_22_dialog_content = "結果是我們倖存下來，心裡卻都留下無盡的悔恨。",
  ui_story_5080_50800500_23_dialog_content = "要是讓小鬼頭們也對上<color=#FFB400>那隻傢伙</color>，讓她們也跟當初的我們一樣無能為力，她們不也會一樣……",
  ui_story_5080_50800500_24_dialog_content = "不一樣，小醒山。經歷了這麼多，你還沒學會認清孩子們的成長嗎？",
  ui_story_5080_50800500_25_dialog_content = "雖然有的孩子沒經歷過，或是不記得當初的事情，但她們如今早就比我們倆更加出色了。",
  ui_story_5080_50800500_26_dialog_content = "澤塔的父母犧牲時，她才不到两歲。以前還沒有輪胎高的她，現在已經可以獨立穿越這片沙漠。",
  ui_story_5080_50800500_27_dialog_content = "你要讓她白白錯過面對過往的機會嗎？",
  ui_story_5080_50800500_28_dialog_content = "我沒那個意思，你很清楚，羅伊。",
  ui_story_5080_50800500_29_dialog_content = "我知道，你還沒習慣放開孩子們的手。你就是太霸道了，小醒山。",
  ui_story_5080_50800500_30_dialog_content = "你還記得前首領以前常說的吧？她尊重部下的每個選擇，相信每個人都有自由的權力。",
  ui_story_5080_50800500_31_dialog_content = "正視已經長大的孩子們吧，我們這些大叔也該學會適時放手了。",
  ui_story_5080_50800500_32_dialog_content = "如果風暴來臨，我倆會陪她們一起面對，但不能只是擋在她們身前。",
  ui_story_5080_50800500_33_dialog_content = "風暴……嗎？",
  ui_story_5080_50800500_34_dialog_content = "哥哥！羅伊！",
  ui_story_5080_50800500_35_dialog_content = "伊芙？怎麼回事，說人人就到？",
  ui_story_5080_50800500_36_dialog_content = "伊芙太擔心你們了，所以出來找你們。",
  ui_story_5080_50800500_37_dialog_content = "一起回去吧！哥哥！",
  ui_story_5080_50800500_38_dialog_content = "那個時候……羅伊。風暴來襲時，我不願意放開伊芙……其實是我太害怕失去她……",
  ui_story_5080_50800500_39_dialog_content = "但到最後，反而是她救了自己、救了我……",
  ui_story_5080_50800500_40_dialog_content = "我絕對不會放開家人的手。但是……或許你說得對，她們比我們想像中更有能力了。",
  ui_story_5080_50800500_41_dialog_content = "不過話雖這麼說，不代表我要讓她們一起下去啊，留在家裡防守也是幫忙了。",
  ui_story_5080_50800500_42_dialog_content = "總之，分工的事情回去再慢慢商量……喂，你這是什麼反應，哪來的手帕？",
  ui_story_5080_50800500_43_dialog_content = "小醒山，大叔我真的好感動……十五年過去，你確實越來越成熟了。",
  ui_story_5080_50800500_44_dialog_content = "笨蛋，我好歹當了這麼多年的首領，你不要把我也當成小鬼頭啊！",
  ui_story_5080_50800500_45_dialog_content = "好慢啊你們，到底去哪了？不說了，吃飯時間到了，別攔著我。菈比，等等我！",
  ui_story_5080_50800500_46_dialog_content = "發生什麼事了？你們倆看起來還真是灰頭土臉。",
  ui_story_5080_50800500_47_dialog_content = "沒有啦，我們去勘察了一下火山附近而已。",
  ui_story_5080_50800500_48_dialog_content = "哇——聽說青瞳最近會回來，大叔要是再出門，記得帶點酒回來給我們。",
  ui_story_5080_50800500_49_dialog_content = "開飯開飯開飯！好險，差點就要餓死了。",
  ui_story_5080_50800500_50_dialog_content = "咦？澤塔和小不點呢？",
  ui_story_5080_50800500_51_dialog_content = "不知道，這蜥蜴乾真好吃——也許是闖了什麼禍，鑽地道逃走了？！",
  ui_story_5080_50800500_52_dialog_content = "這個時間還不回來，大叔我有點擔心。",
  ui_story_5080_50800500_53_dialog_content = "喂，芭芭拉，妳和她們一起惹的事，她們上哪去了？",
  ui_story_5080_50800500_54_dialog_content = "嗯……當時亂糟糟的，不過她們好像是跟耶利亞一起出去了。",
  ui_story_5080_50800500_55_dialog_content = "說什麼要去招攬「救世主澤塔的新隊友」，難道是去找那個女人了？",
  ui_story_5080_50800500_56_dialog_content = "跟著耶利亞出去了嗎……如果是去找那個啟光的小丫頭，就由著她們吧。",
  ui_story_5080_50800500_57_dialog_content = "各位，我們對那個陌生人一點瞭解也沒有，何況火山快要爆發，讓小澤塔兩個人在外面還是太危險了……",
  ui_story_5080_50800500_58_dialog_content = "我們吃得快，我去找！",
  ui_story_5080_50800500_59_dialog_content = "我比較會開車，我去找！",
  ui_story_5080_50800500_60_dialog_content = "我建議，讓……",
  ui_story_5080_50800500_61_dialog_content = "你跑夜路只會翻車，你行嗎你？",
  ui_story_5080_50800500_62_dialog_content = "大叔來，大叔可以先不吃飯！",
  ui_story_5080_50800500_63_dialog_content = "還是讓……",
  ui_story_5080_50800500_64_dialog_content = "我去！讓我激昂的歌聲，成為迷失者的燈塔！",
  ui_story_5080_50800500_65_dialog_content = "那是因為噪音太刺耳了吧。",
  ui_story_5080_50800500_66_dialog_content = "妳說什麼？！",
  ui_story_5080_50800500_67_dialog_content = "別鬧了！",
  ui_story_5080_50800500_68_dialog_content = "一群笨蛋，你們還是好好吃飯吧，我去！",
  ui_story_5080_50800500_69_dialog_content = "開飯囉——咦？菜都上齊了，怎麼不吃呀？",
  ui_story_5080_50800500_70_dialog_content = "恕我無禮，但是這樣的東西，真的是食物嗎……嗯？！！！",
  ui_story_5080_50800500_71_dialog_content = "哇，這個烤蟲的口感，比以前還要脆。",
  ui_story_5080_50800500_72_dialog_content = "炭烤蛇尾的肉質也很鮮美呢！",
  ui_story_5080_50800500_73_dialog_content = "卡蓮，妳怎麼一口也不吃？別擔心，我以前也和妳一樣抗拒，但這個真的很好吃！",
  ui_story_5080_50800500_74_dialog_content = "PlayerName……恕我拒絕你的好意……拿著那種串燒的時候，可以離我遠一點嗎？",
  ui_story_5080_50800500_75_dialog_content = "這個味道……！！！",
  ui_story_5080_50800500_76_dialog_content = "居然比我們啟光的一等罐頭還要好吃。",
  ui_story_5080_50800500_77_dialog_content = "啟光對待士兵也未免太殘酷了……",
  ui_story_5080_50800500_78_dialog_content = "沒想到隊長也會喜歡吃紅油的食物。",
  ui_story_5080_50800500_79_dialog_content = "我不追求口腹之慾。",
  ui_story_5080_50800500_80_dialog_content = "吃飽啦！我要繼續去修東西，妳們別吵我！",
  ui_story_5080_50800500_81_dialog_content = "和澤塔一樣喜歡蜜烤沙鼠，果然懂吃！",
  ui_story_5080_50800500_82_dialog_content = "哼哼，看來就算是啟光的邪惡幹部，也還是能理解正義的美食！",
  ui_story_5080_50800500_83_dialog_content = "就算有一方是邪惡，那也是紅油扳手。居然和你們有相似之處……我無法接受。",
  ui_story_5080_50800500_84_dialog_content = "（這種時候又變得那麼毒舌了。）",
  ui_story_5080_50800500_85_dialog_content = "怎麼會呢？澤塔就很好接受！放心吧，總有一天救世主澤塔會救妳出組織的。",
  ui_story_5080_50800500_86_dialog_content = "儘管來我澤塔的車上沒關係，一定會留一個妳的位置！",
  ui_story_5080_50800500_87_dialog_content = "怎麼樣，超帥的吧？我一直都想這麼說！",
  ui_story_5080_50800500_88_dialog_content = "紅油扳手……明明是從啟光逃走的墮落士兵。",
  ui_story_5080_50800500_89_dialog_content = "不僅忘記了出身和榮耀，甚至變成遊匪，把槍口對準昔日同袍還有平民。",
  ui_story_5080_50800500_90_dialog_content = "連你這樣的……小孩子，也對這些不以為然。",
  ui_story_5080_50800500_91_dialog_content = "澤塔不是小孩，而且我們才不是妳說的那樣！搞錯的人是妳才對吧！",
  ui_story_5080_50800500_92_dialog_content = "讓妳這樣的孩子被紅油遊匪撫養長大，不明是非，這也是我們啟光的責任……我們一定會盡力解決。",
  ui_story_5080_50800500_93_dialog_content = "解決的辦法，就是靠<color=#FFB400>處決者</color>來處決逃兵嗎？",
  ui_story_5080_50800500_94_dialog_content = "什麼？！那種事情，我怎麼都沒聽過……",
  ui_story_5080_50800500_95_dialog_content = "在這片沙漠還沒有名字，甚至<color=#FFB400>紅油扳手</color>都還不存在的時候，啟光就一直有人出逃來到這裡。",
  ui_story_5080_50800500_96_dialog_content = "為了逃離啟光追捕，也為了尋找自由，他們才不得已深入杳無人煙的沙漠。",
  ui_story_5080_50800500_97_dialog_content = "到頭來，啟光的<color=#FFB400>處決者</color>還是追入沙漠，將逃兵們就地正法。",
  ui_story_5080_50800500_98_dialog_content = "怎麼會……",
  ui_story_5080_50800500_99_dialog_content = "為什麼沙漠最初的遊民會拿起武器？為什麼在無人區裡還得彼此警惕？這都是多虧啟光。",
  ui_story_5080_50800500_100_dialog_content = "……那都是過去式了。現在的大元帥不同意這些手段，主張推動新的制度。",
  ui_story_5080_50800500_101_dialog_content = "不會再有逃兵被追殺了！只要紅油遊匪願意放下武器回歸，啟光會既往不咎——",
  ui_story_5080_50800500_102_dialog_content = "暗潮危機的時候，醒山還帶著人支援過迦南城……可惜他也沒有得到好的回報。",
  ui_story_5080_50800500_103_dialog_content = "這其中一定有什麼誤會。只要坐下來好好談，或許能找到雙方都滿意的辦法。",
  ui_story_5080_50800500_104_dialog_content = "可以的話……我也不希望傷害到你們。但你們畢竟是外人，不會理解逃兵的意義。",
  ui_story_5080_50800500_105_dialog_content = "一個人的決定，會傷害到多少相關的人……連家族的榮耀，都會一朝敗盡。",
  ui_story_5080_50800500_106_dialog_content = "（奇怪？好強烈的感情，她……在回憶什麼東西。）",
  ui_story_5080_50800500_107_dialog_content = "是這樣嗎？鳥兒出生在啟光，翅膀就注定受到束縛，沒有權力自由選擇嗎？",
  ui_story_5080_50800500_108_dialog_content = "我出生在紅油扳手，雖然不太能融入，但我也非常清楚，這是一群自由自在的笨蛋。",
  ui_story_5080_50800500_109_dialog_content = "我可以選擇離開他們，獨自築巢，他們也都有各自的選擇。",
  ui_story_5080_50800500_110_dialog_content = "要他們回到啟光，像妳一樣受到統一的管束，磨平每個人的特性……真是無法想像。",
  ui_story_5080_50800500_111_dialog_content = "別那麼說，我一點都不覺得那樣不好！",
  ui_story_5080_50800500_112_dialog_content = "進了啟光，什麼也不能做嗎？飆車呢？飆車可以嗎？",
  ui_story_5080_50800500_113_dialog_content = "呃，地下城的設施非常昂貴，所以一般……不可以。",
  ui_story_5080_50800500_114_dialog_content = "可怕，不想去。",
  ui_story_5080_50800500_115_dialog_content = "不不不，沒那麼糟糕！我們也會有各種比賽，妳也可以申請當運輸兵呀！",
  ui_story_5080_50800500_116_dialog_content = "啟光的宗旨是保護所有光靈。就算某些個體必須犧牲，也在所難免。",
  ui_story_5080_50800500_117_dialog_content = "呵呵，猛禽小姐，能培養出像妳一樣堅定的人，啟光恐怕也下了不少功夫。",
  ui_story_5080_50800500_118_dialog_content = "不需要這樣酸人。我的家族世世代代都是英雄，我們對啟光的信念，妳根本無從想像。",
  ui_story_5080_50800500_119_dialog_content = "為了啟明之光，付出犧牲又有什麼？人活在世上，唯有榮光高於生命！",
  ui_story_5080_50800500_120_dialog_content = "要是每個人都犧牲了，誰去銘記英雄？",
  ui_story_5080_50800500_121_dialog_content = "猛禽小姐，妳出身英雄世家，妳你記得自己祖父的祖父做過什麼、喜歡什麼嗎？",
  ui_story_5080_50800500_122_dialog_content = "妳一定從小聽著他們的榮耀成長吧……但是，妳對他們有任何自己的認知嗎？",
  ui_story_5080_50800500_123_dialog_content = "這……",
  ui_story_5080_50800500_124_dialog_content = "……也許，英雄的事蹟會被時光埋沒，但英雄的成就終將長存。",
  ui_story_5080_50800500_125_dialog_content = "世上還充斥著暗鬼，我等卻仍得誕生、成長、傳承……這其中一定有無數英雄捨生取義、負重前行。",
  ui_story_5080_50800500_126_dialog_content = "哪怕我等並不認識每一位犧牲的英雄，但他們的功業仍伴隨我們，隨艾斯特拉長存。",
  ui_story_5080_50800500_127_dialog_content = "而我也是因為英雄們的影響，才會跨過千萬道歧路堅定地走至此處……我，絕不後悔！",
  ui_story_5080_50800500_128_dialog_content = "英雄的功績和佳話永不消亡！那些意義會永遠流傳，以各種方式影響後人！",
  ui_story_5080_50800500_129_dialog_content = "卡蓮……",
  ui_story_5080_50800500_130_dialog_content = "白夜城的小公主，還真是說了不得了的話呢。",
  ui_story_5080_50800500_131_dialog_content = "白色槍兵，妳……說得對。",
  ui_story_5080_50800500_132_dialog_content = "老大，你偷聽好久了，還不進去嗎？",
  ui_story_5080_50800500_133_dialog_content = "噓！小聲點，我……再聽一下。",
  ui_story_5080_50800500_134_dialog_content = "不錯，白色槍兵說得對！我也……曾經有過一群捨生取義的戰友，受過她們的恩惠，並引以為傲。",
  ui_story_5080_50800500_135_dialog_content = "她們值得每一個人效仿。",
  ui_story_5080_50800500_136_dialog_content = "對……這一定是值得的……否則的話，我……",
  ui_story_5080_50800500_137_dialog_content = "隊長？妳要去哪——",
  ui_story_5080_50800500_138_dialog_content = "讓她靜靜吧。",
  ui_story_5080_50800500_139_dialog_content = "哼……回去了，澤塔、小不點。",
  ui_story_5080_50800500_140_dialog_content = "紅油的首領？什麼時候……",
  ui_story_5080_50800500_141_dialog_content = "我修好了！我修好了！我要去告訴歐緹，我修好她沒修過的東西了！！！",
  ui_story_5080_50800500_142_dialog_content = "<color=#FFB400>狂戰士</color>，澤塔還想留下來……唔……",
  ui_story_5080_50800500_143_dialog_content = "……妳也已經長大了，我不管了。耶利亞，就拜託妳看好我家的小鬼頭了。",
  ui_story_5080_50800500_144_dialog_content = "等等！你……你知道那種暗鬼，對吧？",
  ui_story_5080_50800500_145_dialog_content = "紅油扳手在沙漠經營這麼多年，你們一定曉得。可以告訴我牠的巢穴在哪裡嗎？",
  ui_story_5080_50800500_146_dialog_content = "妳不是第一個來這裡找「祕境」的啟光士兵。這種人我見過太多了，可惜他們每一個都再也沒有回來。",
  ui_story_5080_50800500_147_dialog_content = "和他們相比，妳也沒有什麼特別之處。放棄吧，別為了啟光的任務把命也搭上。",
  ui_story_5080_50800500_148_dialog_content = "真是的，這麼多年了，他們怎麼還一直派人來送死？",
  ui_story_5080_50800500_149_dialog_content = "你不明白，這是士兵的使命！探索祕境的收穫遠比你想像還大，哪怕犧牲也是光榮的！",
  ui_story_5080_50800500_150_dialog_content = "好吧！既然妳一直把犧牲掛在嘴邊。那我問妳，妳懂得「犧牲」的真正涵義嗎？",
  ui_story_5080_50800500_151_dialog_content = "對妳而言，「犧牲」代表什麼？",
  ui_story_5080_50800500_152_dialog_content = "犧牲是為了大義，為了啟明之光，不惜放棄生命的高貴行為！",
  ui_story_5080_50800500_153_dialog_content = "是……是放棄生命也要完成任務的覺悟！",
  ui_story_5080_50800500_154_dialog_content = "哈哈哈哈哈——",
  ui_story_5080_50800500_155_dialog_content = "你笑什麼？你這是什麼意思！",
  ui_story_5080_50800500_156_dialog_content = "果然，妳和那些人沒什麼不同。回去吧，小姑娘，這片沙漠已經吞噬過太多生命了。",
  ui_story_5080_50800500_157_dialog_content = "我們走，小不點。",
  ui_story_5080_50800500_158_dialog_content = "根本不一樣……你根本不懂……我到底背著怎樣的「覺悟」來到這裡……",
  ui_story_5080_50800500_159_dialog_content = "我不能再讓家族蒙羞了……我一定……會洗清那些恥辱……",
  ui_story_5080_50800601_1_dialog_content = "薇絲，妳還不休息嗎？",
  ui_story_5080_50800601_2_dialog_content = "我還有今天的任務結報要寫，沒事的……呵啊……你先睡吧。",
  ui_story_5080_50800601_3_dialog_content = "妳明明已經很累了，不是嗎？",
  ui_story_5080_50800601_4_dialog_content = "好不容易和前輩合作……這可是不可多得的經歷……",
  ui_story_5080_50800601_5_dialog_content = "馬上就要……寫完……",
  ui_story_5080_50800601_6_dialog_content = "過去一點，我來幫妳寫吧。",
  ui_story_5080_50800601_7_dialog_content = "呼……這怎麼可以……呼……",
  ui_story_5080_50800601_8_dialog_content = "看來只剩最後一點點了，我來幫忙補上吧。",
  ui_story_5080_50800601_9_dialog_content = "呵，跟薇絲相處久了，連PlayerName都已經習慣做這樣的事情了。",
  ui_story_5080_50800601_10_dialog_content = "也可能是被薇絲管教多了，不知不覺培養的……沒事，妳早點休息。",
  ui_story_5080_50800601_11_dialog_content = "你看起來還有點困擾……不過你既然那麼說，晚安。",
  ui_story_5080_50800601_12_dialog_content = "（剩下最後的部分，馬上就寫完了。）",
  ui_story_5080_50800601_13_dialog_content = "還有還有……這個部分絕對精彩！",
  ui_story_5080_50800601_14_dialog_content = "（這是……澤塔的聲音？居然能傳進房間，未免太激動了。）",
  ui_story_5080_50800601_15_dialog_content = "是救世主澤塔和邪惡魔女的賽車！",
  ui_story_5080_50800601_16_dialog_content = "（她在和誰說話……寫都寫完了，出去看看吧。）",
  ui_story_5080_50800601_17_dialog_content = "澤塔的車子咻咻咻，一下子就從邪龍的爪子裡開出去，緊接著啪嗒！砰砰！",
  ui_story_5080_50800601_18_dialog_content = "澤塔大人就這樣輕而易舉撞倒邪龍，連魔女都對我崇拜得不得了！",
  ui_story_5080_50800601_19_dialog_content = "（未免吹噓得太過分了吧——她是……在纏著放哨的蕾切爾？）",
  ui_story_5080_50800601_20_dialog_content = "還有還有，妳一定不曉得，車子轟轟響的時候，沙子裡往往會爬出很多蜥蜴。",
  ui_story_5080_50800601_21_dialog_content = "那個啊，超好吃的！比今天桌子上的還要嫩。",
  ui_story_5080_50800601_22_dialog_content = "我們都很擅長做在地美食，妳一定會有興趣。",
  ui_story_5080_50800601_23_dialog_content = "……妳想吃看看我的壓縮軍糧嗎？",
  ui_story_5080_50800601_24_dialog_content = "不要，一看就很難吃。",
  ui_story_5080_50800601_25_dialog_content = "對了對了，澤塔有沒有跟你說過？我跑拉力賽都是自己上喔！",
  ui_story_5080_50800601_26_dialog_content = "就連那個邪惡的魔女，都會拉上傳說中的空之末裔當領航員！",
  ui_story_5080_50800601_27_dialog_content = "但是澤塔從來都是一個人踏上偉大的沙漠征服之旅！",
  ui_story_5080_50800601_28_dialog_content = "很厲害，從妳的外表根本看不出來。",
  ui_story_5080_50800601_29_dialog_content = "哼哼，開始崇拜勇者澤塔了吧？怎麼樣，是不是有點動搖了？脫離邪惡組織跟隨我吧！",
  ui_story_5080_50800601_30_dialog_content = "第一次來就可以穿行沙漠的妳，當拉力賽的領航員一定也很厲害。",
  ui_story_5080_50800601_31_dialog_content = "加入澤塔我的車隊，下次冠軍獎盃就有妳一份榮耀。",
  ui_story_5080_50800601_32_dialog_content = "榮耀……我比較擅長機械方面，這樣行嗎？",
  ui_story_5080_50800601_33_dialog_content = "入門的事情儘管包在澤塔身上，一定能手把手教妳成為傳奇車手的搭檔！",
  ui_story_5080_50800601_34_dialog_content = "那個叫什麼來著……指引迷路之人的寶典，那個……路書！我會教妳怎麼製作的！",
  ui_story_5080_50800601_35_dialog_content = "聽起來好像很有趣。",
  ui_story_5080_50800601_36_dialog_content = "（真的假的，兩人居然真的聊起來了……）",
  ui_story_5080_50800601_37_dialog_content = "是吧是吧！沙漠裡還有很多有趣的事情！明天開始，澤塔就勉為其難地教妳吧！",
  ui_story_5080_50800601_38_dialog_content = "有了我一手培養的你，澤塔一定能戰勝……戰勝那個魔女……",
  ui_story_5080_50800601_39_dialog_content = "睡覺的時間到了，澤塔要馬上入睡……晚安……",
  ui_story_5080_50800601_40_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5080_50800601_41_dialog_content = "……真是的，都不會痛嗎？",
  ui_story_5080_50800601_42_dialog_content = "好好睡……晚安。",
  ui_story_5080_50800601_43_dialog_content = "（時而溫柔，時而又那麼冷漠……哪個才是真正的妳？）",
  ui_story_5080_50800601_44_dialog_content = "（現在正是找她聊聊的好機會……嗯？這是……又來了，強烈的情感……）",
  ui_story_5080_50800601_45_option_content = "感應蕾切爾",
  ui_story_5080_50800601_46_dialog_content = "目標到手，任務完成——隊長，我們成功了。",
  ui_story_5080_50800601_47_dialog_content = "幹得好……別鬆懈，遺跡裡還有很多暗鬼，馬上離開。",
  ui_story_5080_50800601_48_dialog_content = "青梟、紅隼，「資料核心」到手了，按原潛入路線撤退。",
  ui_story_5080_50800601_49_dialog_content = "隊長，這東西很重，還是讓我來背吧。",
  ui_story_5080_50800601_50_dialog_content = "沒關係，妳看好四周，我們馬上回出口和她們會合。",
  ui_story_5080_50800601_51_dialog_content = "隊長，暗鬼好像開始騷動了。",
  ui_story_5080_50800601_52_dialog_content = "牠們的動向變了……這些傢伙聚在一起是想幹嘛？",
  ui_story_5080_50800601_53_dialog_content = "不對，牠們好像朝我們這邊衝過來了。",
  ui_story_5080_50800601_54_dialog_content = "快走！",
  ui_story_5080_50800601_55_dialog_content = "青梟、紅隼，立即回答！出口怎麼樣了？",
  ui_story_5080_50800601_56_dialog_content = "暗鬼的行動路線變了，好像朝著某個共同目標……糟糕，隊長，牠們是衝著妳過去了！",
  ui_story_5080_50800601_57_dialog_content = "別慌，按照原訂計劃確保大門沒有封閉，我們馬上就來。",
  ui_story_5080_50800601_58_dialog_content = "白雁，別管那些暗鬼了，快走！",
  ui_story_5080_50800601_59_dialog_content = "灰翼，先掩護隊長離開！我去引開牠們。",
  ui_story_5080_50800601_60_dialog_content = "說什麼蠢話，要走就一起走！隊長，快把那「核心」扔掉吧！背著那東西，我們一定跑不過暗鬼。",
  ui_story_5080_50800601_61_dialog_content = "為什麼那些傢伙會知道我們的位置？簡直就像是「核心」的守衛……",
  ui_story_5080_50800601_62_dialog_content = "白雁，跟上來，不許擅自行動。",
  ui_story_5080_50800601_63_dialog_content = "可是，隊長……這樣下去，我們來不及……",
  ui_story_5080_50800601_64_dialog_content = "<color=#e8d9bb>砰砰砰——</color>",
  ui_story_5080_50800601_65_dialog_content = "這邊，隊長！",
  ui_story_5080_50800601_66_dialog_content = "是青梟和紅隼！",
  ui_story_5080_50800601_67_dialog_content = "笨蛋，為什麼違抗我的命令！妳們跑過來的話，大門的通道怎麼辦？",
  ui_story_5080_50800601_68_dialog_content = "我們再不過來，妳們就走不了了。",
  ui_story_5080_50800601_69_dialog_content = "要罵要罰出去再說，現在我們得帶隊長先走！",
  ui_story_5080_50800601_70_dialog_content = "笨蛋……",
  ui_story_5080_50800601_71_dialog_content = "我就說妳們動作怎麼那麼慢，原來隊長居然背著這麼重的東西！？",
  ui_story_5080_50800601_72_dialog_content = "這就是「核心」？隊長，這東西根本不適合隨身攜帶，我們……",
  ui_story_5080_50800601_73_dialog_content = "不行！任務大於一切！那裡面的「資料」足以改變啟光……「鷹眼小隊」絕不能因為貪生怕死就放棄任務！",
  ui_story_5080_50800601_74_dialog_content = "而且如果放棄任務，我們就成了逃兵……我不能連累你們……讓家族蒙上恥辱。",
  ui_story_5080_50800601_75_dialog_content = "大門就在前面，你們快走，把「核心」帶回啟光！我來墊後！",
  ui_story_5080_50800601_76_dialog_content = "我不同意！",
  ui_story_5080_50800601_77_dialog_content = "灰翼，你想違抗命令？",
  ui_story_5080_50800601_78_dialog_content = "根據啟光任務手記法令第六章三十一條，副隊長只要爭取到所有隊員同意，即可投票升為小隊最高指令！",
  ui_story_5080_50800601_79_dialog_content = "隊長，我們之中沒有比妳更好的偵察兵。就算越過大門，也不一定能回到地面。",
  ui_story_5080_50800601_80_dialog_content = "我，灰翼在此以副隊長身分發起投票，請求所有隊員支援獵鷹隊長，掩護隊長撤回地面。",
  ui_story_5080_50800601_81_dialog_content = "我同意！",
  ui_story_5080_50800601_82_dialog_content = "我們也沒有意見。",
  ui_story_5080_50800601_83_dialog_content = "你們……",
  ui_story_5080_50800601_84_dialog_content = "「任務高於一切」……獵鷹，現在妳的任務改變了。",
  ui_story_5080_50800601_85_dialog_content = "帶著「核心」回到啟光吧。妳的家人還在等妳，不是嗎？",
  ui_story_5080_50800601_86_dialog_content = "我們會趕上妳的，別擔心。",
  ui_story_5080_50800601_87_dialog_content = "快走，獵鷹隊長！",
  ui_story_5080_50800601_88_dialog_content = "你、你們……",
  ui_story_5080_50800601_89_dialog_content = "等著我！我一回到地面，就馬上呼叫支援。",
  ui_story_5080_50800601_90_dialog_content = "暗鬼來了，兄弟姐妹們，害怕嗎？",
  ui_story_5080_50800601_91_dialog_content = "隊長都已經安全越過大門了，我們還有什麼好怕的！",
  ui_story_5080_50800601_92_dialog_content = "引爆大門，不能讓牠們越過這條線。",
  ui_story_5080_50800601_93_dialog_content = "什麼？！灰翼！不要——！",
  ui_story_5080_50800601_94_dialog_content = "隊長肩上總是扛著那麼重的責任……真對不起啊……又得讓妳多背一筆了。",
  ui_story_5080_50800601_95_dialog_content = "引爆！！！",
  ui_story_5080_50800602_1_dialog_content = "（那是蕾切爾……是因為經歷了這些，她才會孤身一人嗎？所以要找我們組隊……）",
  ui_story_5080_50800602_2_dialog_content = "（也是因為那些事，她才會那麼冷漠，不想對我們付出感情……害怕再次失去嗎？）",
  ui_story_5080_50800602_3_dialog_content = "（又看到了別人痛苦的過去……我真的該繼續和她談這些嗎？）",
  ui_story_5080_50800602_4_dialog_content = "灰翼、白雁、青梟、紅隼……夥伴……你們還在注視我嗎？",
  ui_story_5080_50800602_5_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5080_50800602_6_dialog_content = "誰？竟然敢偷看——",
  ui_story_5080_50800602_7_dialog_content = "喵！",
  ui_story_5080_50800602_8_dialog_content = "貓？",
  ui_story_5080_50800602_9_dialog_content = "……過來，小貓咪。",
  ui_story_5080_50800602_10_dialog_content = "想要小魚乾嗎？",
  ui_story_5080_50800602_11_dialog_content = "好乖好乖，你是信使養大的嗎？",
  ui_story_5080_50800602_12_dialog_content = "毛毛好柔順，真可愛。",
  ui_story_5080_50800602_13_dialog_content = "是被軍牌的聲音給吸引過來的嗎？你也想和他們說說話嗎？",
  ui_story_5080_50800602_14_dialog_content = "那隻貓是羅伊撿到的。一直養在紅油扳手營地裡，性子都養野了。",
  ui_story_5080_50800602_15_dialog_content = "咕！",
  ui_story_5080_50800602_16_dialog_content = "喵——！",
  ui_story_5080_50800602_17_dialog_content = "妳、妳什麼時候……妳都看到了？",
  ui_story_5080_50800602_18_dialog_content = "別在意，我曾踏遍大陸許多地方，見過形形色色的人，不會對妳的愛好有意見。",
  ui_story_5080_50800602_19_dialog_content = "而且我早就知道了，妳並非鐵石心腸的人。",
  ui_story_5080_50800602_20_dialog_content = "不過恕我多嘴，猛禽小姐，妳總是擺出一副冷漠的樣子，會讓你的夥伴很傷心的。",
  ui_story_5080_50800602_21_dialog_content = "……妳不也是一樣，抗拒著紅油扳手的人嗎。",
  ui_story_5080_50800602_22_dialog_content = "抗拒嗎？不，我只是徬徨在那些熱鬧的傢伙之外罷了。",
  ui_story_5080_50800602_23_dialog_content = "果然，妳和<color=#FFB400>那個人</color>很像，讓我感到非常、非常的熟悉。",
  ui_story_5080_50800602_24_dialog_content = "「那個人」？",
  ui_story_5080_50800602_25_dialog_content = "紅油扳手裡有許多啟光的士兵，但只有她最特別。",
  ui_story_5080_50800602_26_dialog_content = "她和妳一樣，都是執行特種任務的精銳士兵，也都年紀輕輕就能帶隊深入沙漠。",
  ui_story_5080_50800602_27_dialog_content = "她……竟然成功從探索祕境的任務中倖存？",
  ui_story_5080_50800602_28_dialog_content = "你還記得她，或是她小隊的名字嗎？也許我認識。",
  ui_story_5080_50800602_29_dialog_content = "名字……嗎？我認識她時，她早已告別自己的過去。她的名字究竟是不是真名，我也無從得知。",
  ui_story_5080_50800602_30_dialog_content = "不過她所率領的小隊名字我還記得——「自由鳥」。正是這名字，讓我羡慕起自由自在的旅鳥。",
  ui_story_5080_50800602_31_dialog_content = "「自由鳥」？！",
  ui_story_5080_50800602_32_dialog_content = "（那不正是蕾切爾想要找的小隊嗎？）",
  ui_story_5080_50800602_33_dialog_content = "那個人……果然逃到了沙漠嗎？她變節了，墮為紅油扳手的一員——",
  ui_story_5080_50800602_34_dialog_content = "你搞錯了，我跟那個人一點也不像！她是可恥的逃兵，我才不是！",
  ui_story_5080_50800602_35_dialog_content = "抱歉，猛禽小姐，不過，搞錯的人恐怕是妳。",
  ui_story_5080_50800602_36_dialog_content = "我所認識的那個人不僅不是逃兵，而且直到最後，她都挺起胸膛擋在所有人面前。",
  ui_story_5080_50800602_37_dialog_content = "那個人的熱血比手上的扳手更紅，所以那把扳手傳到醒山手上也毫不褪色。",
  ui_story_5080_50800602_38_dialog_content = "那樣的話……我有個故事，可以說給妳聽。",
  ui_story_5080_50800602_39_dialog_content = "那是身為「自由鳥」隊員的<color=#FFB400>我姑姑</color>所講述的故事——",
  ui_story_5080_50800602_40_dialog_content = "三十多年前，啟光專案成立了一支特種小隊，名叫「自由鳥」。",
  ui_story_5080_50800602_41_dialog_content = "小隊成員全是從各地遴選的精銳，專門執行那些不可能的任務。",
  ui_story_5080_50800602_42_dialog_content = "面對無比困難的任務，自由鳥仍保持百分百的完成率，讓所有人都以加入這支小隊為榮。",
  ui_story_5080_50800602_43_dialog_content = "如果「自由鳥」還存在，妳簡直就像是為它而生。",
  ui_story_5080_50800602_44_dialog_content = "它的最後一次任務，是事關重大的機密任務，我的姑姑和隊友全都賭上性命……",
  ui_story_5080_50800602_45_dialog_content = "隊員們付出巨大犧牲，但那隊長卻背叛了她們。那個人擅自中止任務成為<color=#FFB400>逃兵</color>，帶倖存者回到啟光。",
  ui_story_5080_50800602_46_dialog_content = "不久之後，她更是叛逃離開啟光，害我的姑姑就這樣被那個人拖入深淵！",
  ui_story_5080_50800602_47_dialog_content = "她害我姑姑被判逃兵，被質疑為叛變分子。不僅失去榮譽，受盡人們白眼，還無數次遭貶！",
  ui_story_5080_50800602_48_dialog_content = "為了不拖累家族，姑姑她連家也不敢回，和我父親的關係也一落千丈——",
  ui_story_5080_50800602_49_dialog_content = "可是，就算姑姑犧牲了那麼多，家族的名聲還是……",
  ui_story_5080_50800602_50_dialog_content = "（蕾切爾……）",
  ui_story_5080_50800602_51_option_content = "感應蕾切爾的記憶",
  ui_story_5080_50800602_52_dialog_content = "看，那個逃兵的孩子過來了。",
  ui_story_5080_50800602_53_dialog_content = "不會是要假惺惺地去博物館吧？那裡是紀念英雄的，不是給逃兵去的地方！",
  ui_story_5080_50800602_54_dialog_content = "長輩是逃兵，那她的家教也很難讓人信任啊。",
  ui_story_5080_50800602_55_dialog_content = "長官，我們真的能把後背託負給一個逃兵的後代嗎？",
  ui_story_5080_50800602_56_dialog_content = "蕾切爾嗎？那種瘦巴巴的小姑娘，想必意志也薄弱得很……",
  ui_story_5080_50800602_57_dialog_content = "薄弱、薄弱、薄弱——",
  ui_story_5080_50800602_58_dialog_content = "我才不是那樣的人！我……我一定會證明給你們所有人看！",
  ui_story_5080_50800602_59_dialog_content = "沒錯，我們蕾切爾是最棒的孩子。她不需要證明給誰看，她已經是很厲害的戰士了。",
  ui_story_5080_50800602_60_dialog_content = "姑姑……我、我剛剛的話不是那個意思……我不是說不想像姑姑……",
  ui_story_5080_50800602_61_dialog_content = "沒事的，蕾切爾。姑姑不在意別人怎麼說，妳也不要被別人的話給打倒了。",
  ui_story_5080_50800602_62_dialog_content = "妳就盡情拿出剛剛的氣勢來，告訴那些人，妳不像姑姑一樣沒用。",
  ui_story_5080_50800602_63_dialog_content = "姑姑……對不起……",
  ui_story_5080_50800602_64_dialog_content = "蕾切爾，站好，看著姑姑。姑姑沒有在怪妳。",
  ui_story_5080_50800602_65_dialog_content = "是姑姑不好，給小蕾切爾帶來了很多麻煩。以後蕾切爾一定、一定還要面對很多指責。",
  ui_story_5080_50800602_66_dialog_content = "但是妳不能倒下，不能向那些人屈服。妳絕不能同意他們說的話，要大聲反擊，就像剛剛一樣。",
  ui_story_5080_50800602_67_dialog_content = "姑姑知道，蕾切爾比姑姑更厲害。",
  ui_story_5080_50800602_68_dialog_content = "要相信自己喔，蕾切爾。不管做出什麼選擇，妳都要堅持到底——不要聽任何人的廢話！",
  ui_story_5080_50800602_69_dialog_content = "姑姑孤身一人在外面安家，將我視如己出……我無法原諒……那個人帶給姑姑的痛苦。",
  ui_story_5080_50800602_70_dialog_content = "所以我決心要努力超越極限，為了超過那些桎梏……我要，阻止悲劇再次發生。",
  ui_story_5080_50800602_71_dialog_content = "反正那傢伙有著逃兵的傳統，一定很快就堅持不下去了吧？",
  ui_story_5080_50800602_72_dialog_content = "不會啊，我覺得她超酷的。很多人都覺得她很有毅力，你還是不要背後說人壞話了。",
  ui_story_5080_50800602_73_dialog_content = "緋，這一期的後輩裡，有哪個讓妳特別滿意嗎？",
  ui_story_5080_50800602_74_dialog_content = "那些人都跟不上我的訓練，程度還差得遠。",
  ui_story_5080_50800602_75_dialog_content = "是妳太嚴格了……對了，<color=#FFB400>她</color>呢？總不會連<color=#FFB400>她</color>也不行吧。",
  ui_story_5080_50800602_76_dialog_content = "<color=#FFB400>她</color>……她對自己的要求太高了。她的身體條件弱於同期，這樣勉強自己不是辦法。",
  ui_story_5080_50800602_77_dialog_content = "為了避免造成永久性的傷害，我想把她刷掉。但她的任性太強了，不管我怎麼提升強度，她也沒有落下。",
  ui_story_5080_50800602_78_dialog_content = "在我看來，她的身體素質並不突出。但最後她是唯一一個跟上我的人。",
  ui_story_5080_50800602_79_dialog_content = "學校裡關於她的流言蜚語很多，但慢慢的，那些人就會不自覺地開始敬佩她。",
  ui_story_5080_50800602_80_dialog_content = "我不知道，自己該不該讚揚她。",
  ui_story_5080_50800602_81_dialog_content = "一個士兵被擊倒，她重新站起來。再次被擊倒時，她仍站起來，一次又一次……緋，我認為這就是英雄。",
  ui_story_5080_50800602_82_dialog_content = "認同她的精神，並給予她關心吧。妳無法否定她的。",
  ui_story_5080_50800602_83_dialog_content = "她已經不可能被刷下去了。",
  ui_story_5080_50800602_84_dialog_content = "軍校生蕾切爾！第三軍團緋軍團長認同妳的優異成績，還有那出類拔萃的精神。現准允妳加入第三軍團！",
  ui_story_5080_50800602_85_dialog_content = "（那就是蕾切爾……她就是這樣一路走來……成為人們眼中的菁英隊長。）",
  ui_story_5080_50800602_86_dialog_content = "這樣啊……為了成為猛禽，妳吃了很多苦呢。",
  ui_story_5080_50800602_87_dialog_content = "呵呵，就當她真的是「逃走」了吧。畢竟她只留給我那麼點話語，就從我們的生命中消失了。",
  ui_story_5080_50800602_88_dialog_content = "她那麼狡猾，我也希望她當年順利逃走了……那樣的話，或許能告訴我答案。",
  ui_story_5080_50800602_89_dialog_content = "答案？",
  ui_story_5080_50800602_90_dialog_content = "這片沙漠很遼闊吧？就算妳想放哨，面對這樣無邊無際的夜晚，妳又如何去守望。",
  ui_story_5080_50800602_91_dialog_content = "這裡太過廣袤，所以也非常空虛。",
  ui_story_5080_50800602_92_dialog_content = "空虛……這就是妳無法接受那些人的理由嗎？",
  ui_story_5080_50800602_93_dialog_content = "妳說自己踏遍大陸許多地方，但妳始終找不到安身之處吧？所以妳才回到這裡……",
  ui_story_5080_50800602_94_dialog_content = "妳說得沒錯。我從小就對這片沙漠抱著奇妙的陌生感，也無法理解那些熱血的人們。",
  ui_story_5080_50800602_95_dialog_content = "他們每天都過得很熱鬧，但他們真的追尋過生命的意義嗎？",
  ui_story_5080_50800602_96_dialog_content = "就這樣吵吵鬧鬧地虛度人生，一旦哪天清醒過來，一定會非常恐慌。",
  ui_story_5080_50800602_97_dialog_content = "聚會終有結局，人與人的相遇注定分離。再熱鬧的生命，未來也會歸於虛無的自我詰問，這難道不可怕嗎？",
  ui_story_5080_50800602_98_dialog_content = "所以妳盤旋在沙漠上，這裡既不是妳的家，也不是妳旅行的地方。",
  ui_story_5080_50800602_99_dialog_content = "妳也只是這片沙漠裡孤獨的飛鳥。",
  ui_story_5080_50800602_100_dialog_content = "其實妳很懂他人的想法嘛，真的沒人誇妳是個好隊長嗎？",
  ui_story_5080_50800602_101_dialog_content = "（要是薇絲還醒著就好了，明天有機會也悄悄告訴她吧。）",
  ui_story_5080_50800602_102_dialog_content = "那個人還活著的時候，我還只是個小孩。她教會我很多知識，告訴我世界到底有多大。",
  ui_story_5080_50800602_103_dialog_content = "因為她的話，我努力尋找自由的生活，我想尋找自己生命的意義，撲向廣袤的未來。",
  ui_story_5080_50800602_104_dialog_content = "可是那個人說死就死了，就連那樣高大的背影，最後也在我們的記憶中開始模糊。",
  ui_story_5080_50800602_105_dialog_content = "脫離了父母和紅油扳手的我，又算得了什麼呢？這個世界上，沒有我的容身之處。",
  ui_story_5080_50800602_106_dialog_content = "哎，沒心沒肺的笨蛋都還在嘻嘻哈哈，我卻陷入這片廣袤的空虛中……真不知道該怎麼辦才好。",
  ui_story_5080_50800602_107_dialog_content = "為什麼妳會對我說這些？",
  ui_story_5080_50800602_108_dialog_content = "如果不是妳，可能我也找不到人說。",
  ui_story_5080_50800602_109_dialog_content = "不過也是呢，我為什麼會對妳說這麼多？是因為妳真的很像她，還是因為妳……很像我？",
  ui_story_5080_50800602_110_dialog_content = "猛禽小姐，妳又何嘗不是……誤入這片沙漠的迷途之鳥？",
  ui_story_5080_50800602_111_dialog_content = "真希望妳是來抓捕逃兵的。要是能把消失無蹤的那個人揪出來，好好教訓一頓就好了。",
  ui_story_5080_50800602_112_dialog_content = "如果不是她，也許我也不會這麼苦惱。明明因為她，紅油扳手都從沒品的笨蛋變成沒心沒肺的笨蛋了……",
  ui_story_5080_50800602_113_dialog_content = "我為什麼就不行呢？",
  ui_story_5080_50800602_114_dialog_content = "信使長老，妳……",
  ui_story_5080_50800602_115_dialog_content = "小澤塔我就抱走啦，妳也下樓睡覺吧。",
  ui_story_5080_50800602_116_dialog_content = "妳說一切都會歸於虛無……但妳還是抱起她，妳在關心她。",
  ui_story_5080_50800602_117_dialog_content = "沒辦法，誰叫這些孩子的塗鴉，存在感還是太強了。",
  ui_story_5080_50800602_118_dialog_content = "晚上的沙漠很冷，我會派言靈代妳放哨，安心吧。",
  ui_story_5080_50800602_119_dialog_content = "而且……妳要是再不走，樓下的空裔也要變成冰棒了喲。",
  ui_story_5080_50800602_120_dialog_content = "（被發現了！）",
  ui_story_5080_50800602_121_dialog_content = "（快跑……哎喲！）",
  ui_story_5080_50800602_122_dialog_content = "怎麼會有個水桶在這裡——！！！",
  ui_story_5080_50800701_1_dialog_content = "醒醒，任務還要繼續。",
  ui_story_5080_50800701_2_dialog_content = "隊長……早安。",
  ui_story_5080_50800701_3_dialog_content = "……早安。去洗把臉，讓自己清醒一點！",
  ui_story_5080_50800701_4_dialog_content = "是！",
  ui_story_5080_50800701_5_dialog_content = "我們今天要繼續偵查任務，全部醒醒，十分鐘後集合！",
  ui_story_5080_50800701_6_dialog_content = "讓我也加入吧。",
  ui_story_5080_50800701_7_dialog_content = "如果你們想找那種特殊的暗鬼，那我也知道相關情報。",
  ui_story_5080_50800701_8_dialog_content = "為什麼？現在妳還會有好奇心嗎？",
  ui_story_5080_50800701_9_dialog_content = "就算一切都會回歸虛無，但這次我想看到結局。",
  ui_story_5080_50800701_10_dialog_content = "猛禽小姐、空裔弟弟，你們不會拒絕我吧？",
  ui_story_5080_50800701_11_dialog_content = "況且，我也想看到「那個人」的埋骨之地。",
  ui_story_5080_50800701_12_dialog_content = "……盥洗完畢了嗎？準備出發！",
  ui_story_5080_50800701_13_dialog_content = "澤塔還在呼呼大睡呢。",
  ui_story_5080_50800701_14_dialog_content = "讓那孩子繼續睡，我們走。",
  ui_story_5080_50800701_15_dialog_content = "紅油的信使長老，這份是我調查的地圖。",
  ui_story_5080_50800701_16_dialog_content = "從昨天的探索看，牠們的洞穴很可能通往附近的火山地脈。",
  ui_story_5080_50800701_17_dialog_content = "我在這些地脈上做了標記，請妳幫我們排除錯誤的答案。",
  ui_story_5080_50800701_18_dialog_content = "可惜猛禽小姐的努力了，但這上面，並沒有真正的答案。",
  ui_story_5080_50800701_19_dialog_content = "沙漠地底還有一座沉眠的火山，這件事從來沒有外來者知道。",
  ui_story_5080_50800701_20_dialog_content = "沉眠的火山？",
  ui_story_5080_50800701_21_dialog_content = "呵，現在這樣說也不對。因為就在昨天，我證實那座火山醒過來了。",
  ui_story_5080_50800701_22_dialog_content = "那種暗鬼雖然透過地脈在沙漠各處出現，但說到大本營，我想大概只有那個地方。",
  ui_story_5080_50800701_23_dialog_content = "畢竟除了那裡以外，其他地方多半都被紅油扳手踏遍了。",
  ui_story_5080_50800701_24_dialog_content = "到底什麼意思？",
  ui_story_5080_50800701_25_dialog_content = "那是座地底火山，只在暗潮危機時爆發過一次。當年，許多暗鬼從爆發的裂隙中湧出，襲擊了紅油扳手。",
  ui_story_5080_50800701_26_dialog_content = "紅油扳手當時的首領，還有澤塔的父母他們就是在那場危機中喪生。",
  ui_story_5080_50800701_27_dialog_content = "這麼多年來，紅油扳手的人雖然在沙漠中四處安家，卻都有意無意避開那個位置。",
  ui_story_5080_50800701_28_dialog_content = "可是，明明已經知道暗鬼從那裡出現，為什麼這麼多年沒想過召集人手去調查？",
  ui_story_5080_50800701_29_dialog_content = "調查過喔，只是一無所獲。",
  ui_story_5080_50800701_30_dialog_content = "那座火山爆發後數年就徹底沉寂，裡頭被普通的暗鬼盤據。",
  ui_story_5080_50800701_31_dialog_content = "紅油扳手好幾度去掃蕩過，但也沒什麼用，更找不到那種暗鬼。",
  ui_story_5080_50800701_32_dialog_content = "我們都以為，那種暗鬼只有一隻，在當年就和前首領她們同歸於盡了。",
  ui_story_5080_50800701_33_dialog_content = "經過幾次掃蕩後，那裡就連普通暗鬼都變少了。",
  ui_story_5080_50800701_34_dialog_content = "人總是會努力避開傷心的回憶，慢慢的，就不再有人去那裡了。",
  ui_story_5080_50800701_35_dialog_content = "不論如何，那都是過去的家……怎麼可以拋棄呢？",
  ui_story_5080_50800701_36_dialog_content = "PlayerName，別忽然消沉啊！我們已經把空谷整理得漂漂亮亮，只要找到妳的族人就行了。",
  ui_story_5080_50800701_37_dialog_content = "呵呵，薇絲小姐說得很對。也許空裔一族也會有人想化為旅鳥，享受自由。",
  ui_story_5080_50800701_38_dialog_content = "或許有一天……旅鳥終究會飛回故鄉的枝枒。",
  ui_story_5080_50800701_39_dialog_content = "……",
  ui_story_5080_50800701_40_dialog_content = "嗯，不管怎麼說，現在也只有我還偶爾會去看看那處故居了。",
  ui_story_5080_50800701_41_dialog_content = "我多次探索地底，雖然沒什麼收穫，起碼還知道不少捷徑。",
  ui_story_5080_50800701_42_dialog_content = "那地圖就麻煩妳了，紅油的信使長老。",
  ui_story_5080_50800701_43_dialog_content = "好了，我們出發吧。",
  ui_story_5080_50800701_44_dialog_content = "震、震起來了！",
  ui_story_5080_50800701_45_dialog_content = "你們看，火山噴發了！",
  ui_story_5080_50800701_46_dialog_content = "不用太驚訝，還是快點趕路吧。",
  ui_story_5080_50800701_47_dialog_content = "紅油沙漠的地脈很不穩定，多年來不時就會火山爆發，那裡不是我們要找的地方。",
  ui_story_5080_50800701_48_dialog_content = "那座火山沉眠許久，即使我曾去到火山口邊緣，也沒見它有甦醒的跡象。",
  ui_story_5080_50800701_49_dialog_content = "但是……它現在又開始發出陣陣咆哮了。那是裡頭暗鬼的聲音。",
  ui_story_5080_50800701_50_dialog_content = "我想一定是發生了某種異常，那種暗鬼才會回到火山地脈。",
  ui_story_5080_50800701_51_dialog_content = "快一點！",
  ui_story_5080_50800701_52_dialog_content = "在這邊，從這裡下來就是地脈深處、通往火山口的洞窟了。",
  ui_story_5080_50800701_53_dialog_content = "果然……出現了好多岩漿燃燒的痕跡。",
  ui_story_5080_50800701_54_dialog_content = "這是那種暗鬼嗎？還是火山的岩漿透過地脈在流淌？",
  ui_story_5080_50800701_55_dialog_content = "我不清楚……昨天調查得太匆忙，我還來不及深入。",
  ui_story_5080_50800701_56_dialog_content = "可以肯定的是，這座火山正在甦醒。",
  ui_story_5080_50800701_57_dialog_content = "等等，我們全部下去會很危險。",
  ui_story_5080_50800701_58_dialog_content = "卡蓮，可以拜託妳在這裡看守車輛和入口嗎？",
  ui_story_5080_50800701_59_dialog_content = "沒問題，交給我吧。",
  ui_story_5080_50800701_60_dialog_content = "地面在隱隱顫動，這下面有著磅礴的力量。",
  ui_story_5080_50800701_61_dialog_content = "它不像是死火山。",
  ui_story_5080_50800701_62_dialog_content = "地上這些雜亂的足跡，這是……暗鬼的蹤跡？",
  ui_story_5080_50800701_63_dialog_content = "這是牠們前往深處的腳印，快追。",
  ui_story_5080_50800701_64_dialog_content = "等等，蕾切爾！",
  ui_story_5080_50800701_65_dialog_content = "這、這是？！",
  ui_story_5080_50800701_66_dialog_content = "四周的挖痕很新，這是剛剛打通的地底迴廊。",
  ui_story_5080_50800701_67_dialog_content = "你們看！火山口就在前面！",
  ui_story_5080_50800701_68_dialog_content = "為什麼剛打通的迴廊會有這麼大的空間？而且還這麼接近火山口……",
  ui_story_5080_50800701_69_dialog_content = "空裔弟弟，你看那面牆。",
  ui_story_5080_50800701_70_dialog_content = "抓痕？而且還這麼深，這麼大……",
  ui_story_5080_50800701_71_dialog_content = "不會錯，這是當年邪龍留下的痕跡。",
  ui_story_5080_50800701_72_dialog_content = "看來這個地方曾是牠的巢穴，或是狩獵場。",
  ui_story_5080_50800701_73_dialog_content = "怪不得那位青瞳小姐一直都沒找到牠。",
  ui_story_5080_50800701_74_dialog_content = "因為牠不止有一個巢穴，還曾藏身在紅油扳手最不想去的地方……",
  ui_story_5080_50800701_75_dialog_content = "耶利亞……妳為什麼會知道青瞳在找牠？",
  ui_story_5080_50800701_76_dialog_content = "呵呵，我說過，畢竟這裡也是我的管轄區嘛。",
  ui_story_5080_50800701_77_dialog_content = "（那是謊言……其實妳……一直在注視著紅油的大家。）",
  ui_story_5080_50800701_78_dialog_content = "哎呀，這麼一說，邪龍的幾次出現都和火山爆發有關呢。",
  ui_story_5080_50800701_79_dialog_content = "會不會，牠是為了躲避火山爆發，才會被迫離開巢穴，出現在人們面前？",
  ui_story_5080_50800701_80_dialog_content = "既然害怕岩漿，為什麼還硬要把巢築在火山邊緣？",
  ui_story_5080_50800701_81_dialog_content = "這根本說不通。",
  ui_story_5080_50800701_82_dialog_content = "因為牠在躲避某個人。",
  ui_story_5080_50800701_83_dialog_content = "那時候，那個人正跑遍沙漠，尋找任何威脅加以清除。那條龍為了躲避她，不得不藏身火山……",
  ui_story_5080_50800701_84_dialog_content = "是地震，又來了！",
  ui_story_5080_50800701_85_dialog_content = "不對，這個震源好像就在下面！這個趨勢……火山是不是快要噴發了？",
  ui_story_5080_50800701_86_dialog_content = "隊長，調查任務遇上不可抗力因素，我們還是先離開吧。",
  ui_story_5080_50800701_87_dialog_content = "……你們先走，我還要留下來繼續任務。",
  ui_story_5080_50800701_88_dialog_content = "可是隊長……這樣太危險了。",
  ui_story_5080_50800701_89_dialog_content = "任務高於一切。",
  ui_story_5080_50800701_90_dialog_content = "狩獵總是這樣拼命，還真是猛禽的風格。",
  ui_story_5080_50800701_91_dialog_content = "但是猛禽小姐，為了虛幻的東西付出生命，讓我完全不明白。妳到底是徬徨著，還是太過熱情？",
  ui_story_5080_50800701_92_dialog_content = "隊長，我們沒必要在這種情況拼命，下次再來吧！",
  ui_story_5080_50800701_93_dialog_content = "不行，要是火山爆發了，這裡全都會淹沒。等岩漿冷卻，一切都會……",
  ui_story_5080_50800701_94_dialog_content = "你們快走！",
  ui_story_5080_50800701_95_dialog_content = "要走就一起走！",
  ui_story_5080_50800701_96_dialog_content = "幼龍二號，妳……為什麼又是這樣的話……",
  ui_story_5080_50800701_97_dialog_content = "又是？",
  ui_story_5080_50800701_98_dialog_content = "（是那時候……蕾切爾的隊友說過的話……）",
  ui_story_5080_50800701_99_dialog_content = "我不能……我不能逃……",
  ui_story_5080_50800701_100_dialog_content = "小心！我感應到有暗鬼在接近。",
  ui_story_5080_50800701_101_dialog_content = "跑不跑待會再說，大家，快準備迎敵！",
  ui_story_5080_50800702_1_dialog_content = "結、結束了。",
  ui_story_5080_50800702_2_dialog_content = "震動也結束了……火山平息了？",
  ui_story_5080_50800702_3_dialog_content = "為什麼暗鬼會變得這麼強？這裡我調查過好幾次，根本沒見過這些特殊種。",
  ui_story_5080_50800702_4_dialog_content = "這種構造……是異變嗎？",
  ui_story_5080_50800702_5_dialog_content = "又開始了！",
  ui_story_5080_50800702_6_dialog_content = "這裡實在太危險了，隊長，至少我們先回到先前的通道去吧？",
  ui_story_5080_50800702_7_dialog_content = "這裡離火山口太近了。",
  ui_story_5080_50800702_8_dialog_content = "嗯……就按幼龍二號說的那樣，我們找另一條路——",
  ui_story_5080_50800702_9_dialog_content = "這是什麼？這種震感……不是火山。",
  ui_story_5080_50800702_10_dialog_content = "大家小心，通道要塌了——！！！",
  ui_story_5080_50800702_11_dialog_content = "紅油扳手們，一直以來都很熱鬧。",
  ui_story_5080_50800702_12_dialog_content = "喂，耶利亞——過來一起拼車吧，今天我們一定能把車子拼好！",
  ui_story_5080_50800702_13_dialog_content = "沒錯喲！待會我們還要一起去抓沙蜴喔！",
  ui_story_5080_50800702_14_dialog_content = "我就不了。",
  ui_story_5080_50800702_15_dialog_content = "什麼嘛，耶利亞又不來。",
  ui_story_5080_50800702_16_dialog_content = "明天我們再來找妳玩。",
  ui_story_5080_50800702_17_dialog_content = "就算拒絕，也沒有用。可是我，並不適應那樣的人群。",
  ui_story_5080_50800702_18_dialog_content = "又讓我找到妳了。",
  ui_story_5080_50800702_19_dialog_content = "我沒有在跟妳玩捉迷藏。",
  ui_story_5080_50800702_20_dialog_content = "那耶利亞就是在等我了，對吧？",
  ui_story_5080_50800702_21_dialog_content = "抓到妳臉紅囉。",
  ui_story_5080_50800702_22_dialog_content = "才沒有。",
  ui_story_5080_50800702_23_dialog_content = "給妳，好不容易才弄來的。這是啟光的教材。",
  ui_story_5080_50800702_24_dialog_content = "妳……又外出了嗎？",
  ui_story_5080_50800702_25_dialog_content = "嗯。我去了趟影鎮，和黑市商人做了點交易。",
  ui_story_5080_50800702_26_dialog_content = "妳知道嗎？影鎮外有一座很酷的地底遺跡，裡頭全是古代建築，材料卻超乎我們認知。",
  ui_story_5080_50800702_27_dialog_content = "現在裡頭擠滿黑幫和商人，把那個地方改造得像個迴廊迷宮。",
  ui_story_5080_50800702_28_dialog_content = "一個個都在尋找那裡頭值錢的東西，但他們不知道，最值錢的就是遺跡本身。",
  ui_story_5080_50800702_29_dialog_content = "遺跡本身……有什麼價值嗎？都已經成古董了，留下來除了欣賞還有什麼用？",
  ui_story_5080_50800702_30_dialog_content = "那還用問？當然有了！",
  ui_story_5080_50800702_31_dialog_content = "遺跡所用的材料是什麼？是在什麼情況下建成的？由什麼人創造？",
  ui_story_5080_50800702_32_dialog_content = "遺跡內有科技品嗎？那些科技能為我們帶來什麼突破？",
  ui_story_5080_50800702_33_dialog_content = "古代的文明究竟如何？他們創造過什麼樣的世界，又是為什麼消失——",
  ui_story_5080_50800702_34_dialog_content = "這些全都要靠遺跡來「告訴」我們。",
  ui_story_5080_50800702_35_dialog_content = "那個迴廊，能夠告訴妳這些嗎？",
  ui_story_5080_50800702_36_dialog_content = "嗯，只要花點時間，我就能從它身上找到答案。",
  ui_story_5080_50800702_37_dialog_content = "就像……妳以前跟我說的那次一樣？",
  ui_story_5080_50800702_38_dialog_content = "哪次？",
  ui_story_5080_50800702_39_dialog_content = "在北境附近的祕境偵察的事。",
  ui_story_5080_50800702_40_dialog_content = "喔，就是我教妳放風箏那一次啊。",
  ui_story_5080_50800702_41_dialog_content = "沒錯，那裡面的遺跡提到一種「飛行器」；深入調查後，我們啟光也開始推展研究。",
  ui_story_5080_50800702_42_dialog_content = "不過我個人能為妳做的，就只有風箏了。",
  ui_story_5080_50800702_43_dialog_content = "迴廊裡會有什麼呢？",
  ui_story_5080_50800702_44_dialog_content = "裡面藏著的傢伙太多了，我還沒辦法好好研究。",
  ui_story_5080_50800702_45_dialog_content = "有機會的話，我再去那裡找找看。",
  ui_story_5080_50800702_46_dialog_content = "也許還能帶點什麼回來給耶利亞。",
  ui_story_5080_50800702_47_dialog_content = "……我能問妳一個問題嗎？",
  ui_story_5080_50800702_48_dialog_content = "喔？問吧。",
  ui_story_5080_50800702_49_dialog_content = "妳已經見識過這個艾斯特拉了，為什麼還充滿熱情？",
  ui_story_5080_50800702_50_dialog_content = "這個世界對妳來說一點也不陌生，應該變得非常無聊了……",
  ui_story_5080_50800702_51_dialog_content = "我帶回來的書，耶利亞都看完了嗎？",
  ui_story_5080_50800702_52_dialog_content = "嗯，五千六百八十三本，每一本都看了。",
  ui_story_5080_50800702_53_dialog_content = "但這五千六百八十三本，還遠遠講不完艾斯特拉的故事。",
  ui_story_5080_50800702_54_dialog_content = "而且，在這艾斯特拉之外，會不會還有別的大陸呢？那些地方是什麼模樣？有著什麼樣的人？",
  ui_story_5080_50800702_55_dialog_content = "我從來都不知道，也一直好奇。",
  ui_story_5080_50800702_56_dialog_content = "我已經走過艾斯特拉大部分地方了，但我還沒把每一條路熟記在心。",
  ui_story_5080_50800702_57_dialog_content = "耶利亞，可能妳自己也沒發現，但妳對這個世界充滿探索慾。",
  ui_story_5080_50800702_58_dialog_content = "和我這樣匆匆掠過風景的「旅鳥」不一樣，妳一定能仔細去認知這個世界。",
  ui_story_5080_50800702_59_dialog_content = "不要揉我的頭……",
  ui_story_5080_50800702_60_dialog_content = "好，我來回答妳的問題吧。答案是，我見過的風景太多，留下的回憶卻很少。",
  ui_story_5080_50800702_61_dialog_content = "晚上在面對廣袤的沙漠時，我發現自己能銘記的美好太少了。",
  ui_story_5080_50800702_62_dialog_content = "那是因為……啟光的人只讓妳一直出任務吧。",
  ui_story_5080_50800702_63_dialog_content = "是那樣也說不定，哈哈。",
  ui_story_5080_50800702_64_dialog_content = "耶利亞，妳很聰明。也許想問的太多，就會讓得不到答案的自己感到徬徨吧。",
  ui_story_5080_50800702_65_dialog_content = "但是沒辦法，因為耶利亞還是個孩子啊。",
  ui_story_5080_50800702_66_dialog_content = "努力長大吧，耶利亞。未來的妳，一定可以去細細探究所有謎題。",
  ui_story_5080_50800702_67_dialog_content = "不要像我這樣匆匆度過生命，只知道盲目地掠過旅途。",
  ui_story_5080_50800702_68_dialog_content = "妳一定能在名為「人生」的旅途裡尋得意義，然後留下無數回憶。",
  ui_story_5080_50800702_69_dialog_content = "妳要自由地活，痛快地展翅，那樣的話，妳一定……一定能找到現在苦惱的答案。",
  ui_story_5080_50800702_70_dialog_content = "我搞不懂。",
  ui_story_5080_50800702_71_dialog_content = "<color=#FFB400>她</color>和我應該是同類，我們都無法選擇，出生在不適應的環境。",
  ui_story_5080_50800702_72_dialog_content = "我想離開沙漠，在世界各地留下自己的腳印。但她脫離了束縛自己的啟光，卻留駐在這裡。",
  ui_story_5080_50800702_73_dialog_content = "為什麼……為什麼妳要留下來？",
  ui_story_5080_50800702_74_dialog_content = "耶利亞還記得我說過的，<color=#FFB400>那個故事</color>嗎？",
  ui_story_5080_50800702_75_dialog_content = "嗯。",
  ui_story_5080_50800702_76_dialog_content = "而故事的後續是，孤身一人的妳在沙漠中得到了<color=#FFB400>這把扳手</color>，還有了一群依賴妳的人。",
  ui_story_5080_50800702_77_dialog_content = "為了他們，妳聯合所有遊民，所以才有「紅油扳手」。",
  ui_story_5080_50800702_78_dialog_content = "妳對他們沒有責任，為什麼要為了他們留下來……妳不想……",
  ui_story_5080_50800702_79_dialog_content = "我可是這片沙漠出生的孩子呀，回到故鄉又有什麼不對？況且，我想讓他們獲得自由。",
  ui_story_5080_50800702_80_dialog_content = "生而不自知，那和暗鬼有什麼差別呢？我要解放他們靈魂的枷鎖，讓他們能夠選擇。",
  ui_story_5080_50800702_81_dialog_content = "我已經虛度過人生了。",
  ui_story_5080_50800702_82_dialog_content = "所以，我希望他們能夠想清楚自己的旅途，過上自由的人生。",
  ui_story_5080_50800702_83_dialog_content = "變成活在當下、歡樂胡鬧的人，那就是「自由」嗎？",
  ui_story_5080_50800702_84_dialog_content = "我不明白……",
  ui_story_5080_50800702_85_dialog_content = "我是因為妳的那些故事，才知道還有那麼多的東西等著我去發現。",
  ui_story_5080_50800702_86_dialog_content = "那時候，我一度沉迷在探索這個世界之中。",
  ui_story_5080_50800702_87_dialog_content = "噢？那可真是了不起，耶利亞。",
  ui_story_5080_50800702_88_dialog_content = "但這個世界沒有妳說得那麼好。妳騙了我。",
  ui_story_5080_50800702_89_dialog_content = "白夜城貴族驕傲自大，啟光仍然那麼無趣，北境的人則困在自己的童話之中。",
  ui_story_5080_50800702_90_dialog_content = "影鎮的低語迴廊，變成了伊斯塔萬的寶庫。那些所謂充滿故事的遺跡，不過是他漠不關心的牢籠。",
  ui_story_5080_50800702_91_dialog_content = "一切都是那麼空虛……",
  ui_story_5080_50800702_92_dialog_content = "就連創造過那麼多奇蹟的空之一族，最終也淪為無人提及的回憶。",
  ui_story_5080_50800702_93_dialog_content = "暗鬼襲擊人類、人類反擊暗鬼；這個世上的生命，都困在苦苦求生的螺旋之中。",
  ui_story_5080_50800702_94_dialog_content = "一切都會化為虛無。",
  ui_story_5080_50800702_95_dialog_content = "小耶利亞終於長大成人了呢。不過，妳的煩惱未免也太多了。",
  ui_story_5080_50800702_96_dialog_content = "我不明白……我該停止追問嗎？",
  ui_story_5080_50800702_97_dialog_content = "如果聰明將繼續伴隨孤獨的空虛，我該選擇加入那些熱鬧的笨蛋嗎？",
  ui_story_5080_50800702_98_dialog_content = "可是耶利亞，妳不是見到了「空之末裔」嗎？",
  ui_story_5080_50800702_99_dialog_content = "妳應該清楚，從他出現開始，空之山谷就不會成為被遺忘的過去。那些回憶有了繼承者，故事就此開始了。",
  ui_story_5080_50800702_100_dialog_content = "世上的風景，難道總是一成不變嗎？",
  ui_story_5080_50800702_101_dialog_content = "命運的無常，不會只帶給妳無趣或是痛苦的體驗。",
  ui_story_5080_50800702_102_dialog_content = "那些聯繫，就像線一般拉住妳這隻「風箏」……",
  ui_story_5080_50800702_103_dialog_content = "等等！妳要去哪？別走！",
  ui_story_5080_50800702_104_dialog_content = "妳應該已經感受到了。他們在「呼喚」妳。",
  ui_story_5080_50800702_105_dialog_content = "對妳來說，我一定不是好的老師。但對我來說，耶利亞……我很高興能與妳相遇。",
  ui_story_5080_50800702_106_dialog_content = "等等！回來，別走！別走——<color=#FFB400>阿塔爾</color>——！",
  ui_story_5080_50800702_107_dialog_content = "耶利亞！",
  ui_story_5080_50800702_108_dialog_content = "……？",
  ui_story_5080_50800702_109_dialog_content = "太好了，妳醒過來了。",
  ui_story_5080_50800702_110_dialog_content = "這小子擔心得要命，在妳旁邊施展了半天「特技」呢。",
  ui_story_5080_50800702_111_dialog_content = "醒山……？",
  ui_story_5080_50800702_112_dialog_content = "還有我們呢。",
  ui_story_5080_50800702_113_dialog_content = "……為什麼紅油扳手的人都來了？",
  ui_story_5080_50800702_114_dialog_content = "「仙女長老」，妳終於醒過來了！太好了，沒有受傷吧？",
  ui_story_5080_50800702_115_dialog_content = "為什麼要拋下勇者澤塔！勇者澤塔聽到妳的車聲就馬上醒來了！",
  ui_story_5080_50800702_116_dialog_content = "我正在和暗鬼交戰時，她急急忙忙地開車追過來，正好替我們解圍。",
  ui_story_5080_50800702_117_dialog_content = "可是她太著急了，完全不聽我的話，我只能帶她過來找你們……",
  ui_story_5080_50800702_118_dialog_content = "結果洞窟突然就崩塌了，聽起來是不是很有探險作品主角的感覺？",
  ui_story_5080_50800702_119_dialog_content = "說到洞窟崩塌，當時我就覺得不像火山的震感……",
  ui_story_5080_50800702_120_dialog_content = "都怪醒山，用那怪力揮著扳手砸來砸去的，我早就說那洞穴很不牢啊。",
  ui_story_5080_50800702_121_dialog_content = "我也沒要你跟過來啊。",
  ui_story_5080_50800702_122_dialog_content = "這就是關鍵，為什麼你叫了那麼多人卻沒叫我，排擠我喔？",
  ui_story_5080_50800702_123_dialog_content = "哎，不要指責小醒山，我們也只是想找幫手。",
  ui_story_5080_50800702_124_dialog_content = "咦？比起我，約娜更好吧？",
  ui_story_5080_50800702_125_dialog_content = "外面也很危險，約娜要留下來看家才行。",
  ui_story_5080_50800702_126_dialog_content = "放心，青瞳回來，約娜就會來。",
  ui_story_5080_50800702_127_dialog_content = "多恩的感知敏銳，可以追蹤暗鬼。而你……不要妄自菲薄，大叔我看好你。",
  ui_story_5080_50800702_128_dialog_content = "不對，我們分工明確，誰那麼大嘴巴到處說！為什麼伊芙和你都來了！",
  ui_story_5080_50800702_129_dialog_content = "對不起……哥哥，是我發現你和多恩不見了，所以才會去問大家……",
  ui_story_5080_50800702_130_dialog_content = "啊啊啊——！那些傢伙面對小伊芙就連保密都不會嗎？",
  ui_story_5080_50800702_131_dialog_content = "想拋下我和伊芙，這種事情絕不能答應！我可是拼了畢生所學追上來的！",
  ui_story_5080_50800702_132_dialog_content = "黑潮還是帶著伊芙回去吧，這裡太危險了。",
  ui_story_5080_50800702_133_dialog_content = "路都塌了，現在找其他路回去太危險了。我提議讓他們留下來。",
  ui_story_5080_50800702_134_dialog_content = "別吵了！哎，事情怎麼會變成這樣……",
  ui_story_5080_50800702_135_dialog_content = "既然都這樣了，伊芙、黑潮，你們兩個就留下來。伊芙，要好好跟緊哥哥！",
  ui_story_5080_50800702_136_dialog_content = "好的！",
  ui_story_5080_50800702_137_dialog_content = "讓我們團結一致，勇敢面對未知。",
  ui_story_5080_50800702_138_dialog_content = "我可是安排了慶功宴，你們誰也別想缺席啊。",
  ui_story_5080_50800702_139_dialog_content = "給我記住，遇上什麼都不要逞強！有事就躲我後面——PlayerName，你們幾個也是。",
  ui_story_5080_50800702_140_dialog_content = "紅油扳手……事已至此，算了。",
  ui_story_5080_50800702_141_dialog_content = "「棒棒糖少女」，妳可以跟在我後面，我……",
  ui_story_5080_50800702_142_dialog_content = "我會保護妳。",
  ui_story_5080_50800802_1_dialog_content = "既然現在結伴同行，有些事我就不瞞著你們了。",
  ui_story_5080_50800802_2_dialog_content = "羅伊，我要跟他們說了。這裡地勢越來越低，搞不好我們會遇上「大獎」。",
  ui_story_5080_50800802_3_dialog_content = "大叔我沒有意見。你看到的部分，我也會幫忙補充。",
  ui_story_5080_50800802_4_dialog_content = "突然變得好正式的感覺……",
  ui_story_5080_50800802_5_dialog_content = "那是十五年前的故事了。那時候艾斯特拉已經爆發暗潮危機，我們也拼命抵抗了一段時間。",
  ui_story_5080_50800802_6_dialog_content = "誰也沒想到，營地底下還藏著一座火山。火山忽然間爆發，搞出一道大裂縫，裂縫裡湧出許多暗鬼。",
  ui_story_5080_50800802_7_dialog_content = "我們被打個措手不及，只好邊打邊撤離營地。",
  ui_story_5080_50800802_8_dialog_content = "那時候我才十六歲，被當家的命令撤離。我還不夠強，只能保護著伊芙和其他人一起逃。",
  ui_story_5080_50800802_9_dialog_content = "那時候大叔我倒是跟在首領身旁，一起墊後……但她們最後還是要我先跑。",
  ui_story_5080_50800802_10_dialog_content = "首領她們，就犧牲在最後的戰鬥中。",
  ui_story_5080_50800802_11_dialog_content = "那隻邪龍當時也在，一開始的時候，首領還算遊刃有餘，可是——",
  ui_story_5080_50800802_12_dialog_content = "火山爆發得越來越激烈，一隻沐浴岩漿的暗鬼從裡頭爬了出來。",
  ui_story_5080_50800802_13_dialog_content = "「沐浴岩漿的暗鬼」……不會錯，那才是我們的目標。",
  ui_story_5080_50800802_14_dialog_content = "首領似乎和牠有什麼瓜葛，在看到牠時又驚訝，又……害怕。",
  ui_story_5080_50800802_15_dialog_content = "她說自己知道那傢伙有多強，所以要我們都先跑。",
  ui_story_5080_50800802_16_dialog_content = "那是非常嚴肅的命令，大叔我只能逃跑。最後的最後，首領帶著幾個年長的兄弟姐妹們衝了上去。",
  ui_story_5080_50800802_17_dialog_content = "唔……",
  ui_story_5080_50800802_18_dialog_content = "（強烈的感情波動傳過來了……那是……蕾切爾？）",
  ui_story_5080_50800802_19_option_content = "（她動搖了嗎？）",
  ui_story_5080_50800802_20_dialog_content = "（對喔……對她來說，那位首領是害了她姑姑的逃兵。）",
  ui_story_5080_50800802_21_option_content = "（她不願意相信嗎？）",
  ui_story_5080_50800802_22_dialog_content = "（要讓她相信當年的首領擁有犧牲的高貴覺悟，一定很難吧……）",
  ui_story_5080_50800802_23_dialog_content = "（在她心中，那位首領一直是怕死的逃兵，但對於紅油的大家來說，那人無疑是個英雄！）",
  ui_story_5080_50800802_24_dialog_content = "後來的事情就沒什麼好說了。",
  ui_story_5080_50800802_25_dialog_content = "多虧了小醒山，雖然年輕，指揮卻非常清晰。更重要的是，他擁有當家的魄力。",
  ui_story_5080_50800802_26_dialog_content = "在他帶領下，我們開始遊擊，最終找到陸行者號。",
  ui_story_5080_50800802_27_dialog_content = "不但重振旗鼓，還拯救許多沙漠遊民，人數反而越來越多。",
  ui_story_5080_50800802_28_dialog_content = "當家的死了，危機還沒解除。其他人都顧著哭哭啼啼，我只能想辦法讓他們振作起來。",
  ui_story_5080_50800802_29_dialog_content = "我和伊芙是外來的，受了當家的許多恩惠，也受大家幫過不少忙。",
  ui_story_5080_50800802_30_dialog_content = "沒人當惡人說狠話的，就由我來！當家的都死了，我們不能再讓任何人喪命。",
  ui_story_5080_50800802_31_dialog_content = "罵我粗暴也好，不講理也行，反正只要大家活下來，我就對得起當家的了。",
  ui_story_5080_50800802_32_dialog_content = "別的事情，我當時沒有多想。",
  ui_story_5080_50800802_33_dialog_content = "別害羞嘛，都這麼大個人了。",
  ui_story_5080_50800802_34_dialog_content = "囉嗦，這都是題外話吧！",
  ui_story_5080_50800802_35_dialog_content = "火山恢復平靜後，地面的暗鬼也被我們逐漸掃蕩乾淨。",
  ui_story_5080_50800802_36_dialog_content = "岩漿冷卻後，我們在面目全非的營地裡，只發現了那把扳手。",
  ui_story_5080_50800802_37_dialog_content = "不管是邪龍，還是當家的，還有那隻暗鬼，我們都找不到蹤跡了。",
  ui_story_5080_50800802_38_dialog_content = "雖然誰也沒說出口，但大家都默認，當家的一定和牠們同歸於盡，死在岩漿裡了。",
  ui_story_5080_50800802_39_dialog_content = "直到邪龍再次出現……",
  ui_story_5080_50800802_40_dialog_content = "結果那種暗鬼現在也出現了，以前當家的會不會是被吃掉了而已？",
  ui_story_5080_50800802_41_dialog_content = "怎麼可能？！她那麼厲害！！！",
  ui_story_5080_50800802_42_dialog_content = "算了，反正我們總算能報仇了。一直沒有發現的這裡，原來隱藏著這樣的道路……",
  ui_story_5080_50800802_43_dialog_content = "過去，這座火山時不時就會有咆哮響起。",
  ui_story_5080_50800802_44_dialog_content = "雖然都知道是暗鬼的聲音，但不管怎麼殺也殺不乾淨，我們一直覺得是有沒發現的通道。",
  ui_story_5080_50800802_45_dialog_content = "哼，終於讓我們找到了。不過，居然還是來了這個不想再來的地方。",
  ui_story_5080_50800802_46_dialog_content = "我……小時候很喜歡跟著她。",
  ui_story_5080_50800802_47_dialog_content = "我見識過她的力量，那是不輸給醒山的誇張實力，不應該會輸給那條龍。",
  ui_story_5080_50800802_48_dialog_content = "而且，我能感覺到她在忍耐著什麼。",
  ui_story_5080_50800802_49_dialog_content = "她在拼命隱藏著某個祕密，壓抑著自己。",
  ui_story_5080_50800802_50_dialog_content = "妳這麼一說，確實呢……我和首領都出身啟光，早已久仰她的大名。",
  ui_story_5080_50800802_51_dialog_content = "但我真正和她見面的時候，總覺得和想像中不一樣。",
  ui_story_5080_50800802_52_dialog_content = "但大叔我一直有種感覺，她在隱藏著自己的「真面目」。不管是什麼戰鬥，她給我的感覺都太隱忍了。",
  ui_story_5080_50800802_53_dialog_content = "直到最後的最後，她才似乎解開自己「封印」，我第一次看到那樣熱血又狂暴的首領……",
  ui_story_5080_50800802_54_dialog_content = "那樣子，比發飆的醒山還兇。",
  ui_story_5080_50800802_55_dialog_content = "這種比喻聽起來好奇怪。",
  ui_story_5080_50800802_56_dialog_content = "連她也是被<color=#FFB400>那種暗鬼</color>殺死的，我們贏得了嗎？",
  ui_story_5080_50800802_57_dialog_content = "怒嘯火山看來即將爆發，暗潮或許會再次來襲。現在的紅油扳手擋得住嗎？",
  ui_story_5080_50800802_58_dialog_content = "那還用說？",
  ui_story_5080_50800802_59_dialog_content = "放馬過來吧！",
  ui_story_5080_50800802_60_dialog_content = "不管是怎樣的暗鬼，本大爺都會用這把扳手把牠狠狠敲飛！",
  ui_story_5080_50800802_61_dialog_content = "那種暗鬼要是膽敢出現在我面前就太好了，我絕對不會再讓牠囂張，絕對！",
  ui_story_5080_50800802_62_dialog_content = "空裔一號、幼龍二號，你們聽好。",
  ui_story_5080_50800802_63_dialog_content = "怎麼了，忽然說悄悄話？",
  ui_story_5080_50800802_64_dialog_content = "我們的任務是……盡量活捉那隻暗鬼。",
  ui_story_5080_50800802_65_dialog_content = "必要的時候，阻止醒山殺死牠。",
  ui_story_5080_50800901_1_dialog_content = "又是新的小路，這下面到底是怎麼回事？",
  ui_story_5080_50800901_2_dialog_content = "空間開闊起來了，這是一條真正的道路。",
  ui_story_5080_50800901_3_dialog_content = "沙漠的地底往往很複雜，從結構來看，這裡會不會本來是地脈迴廊的牆？",
  ui_story_5080_50800901_4_dialog_content = "火山爆發，牆體被岩漿燒出孔洞；暗鬼挖穿這些孔洞，才變成路。",
  ui_story_5080_50800901_5_dialog_content = "從岩壁來看，這裡確實是被挖出來的，但用的是工具。",
  ui_story_5080_50800901_6_dialog_content = "意思是，這不是暗鬼的手筆？",
  ui_story_5080_50800901_7_dialog_content = "沙漠從很久以前就有光靈生活，大概是從前的人開拓了地脈迴廊。",
  ui_story_5080_50800901_8_dialog_content = "這是……看地面，強烈的震動，讓地層開裂了。",
  ui_story_5080_50800901_9_dialog_content = "這下面是切割過的石料……這是地板。這裡曾經是人造建築。",
  ui_story_5080_50800901_10_dialog_content = "什麼？但這是地底火山口邊啊！",
  ui_story_5080_50800901_11_dialog_content = "原來如此，所以岩壁才會有工具的痕跡，他們不是無端開拓地脈，而是在興建。",
  ui_story_5080_50800901_12_dialog_content = "啊，外來的啟光兵，妳在做什麼？這個時候挖土玩嗎？",
  ui_story_5080_50800901_13_dialog_content = "別急著鬧，她是在用匕首挖出建材縫隙深層的殘留物，它們會告訴她故事。",
  ui_story_5080_50800901_14_dialog_content = "這塊石料上有明顯的三點凹槽，縫隙內還留有燒灼過的灰燼。",
  ui_story_5080_50800901_15_dialog_content = "不會錯，很久以前，有人在這裡架鍋生火。",
  ui_story_5080_50800901_16_dialog_content = "從這裡到剛剛的入口，正是一個房間的大小。這是個地下避難所。",
  ui_story_5080_50800901_17_dialog_content = "在很久以前，這裡很可能沒有暗鬼，而是某些人的避難所。",
  ui_story_5080_50800901_18_dialog_content = "他們曾經躲在這裡，直到火山爆發將一切掩埋。",
  ui_story_5080_50800901_19_dialog_content = "不愧是猛禽小姐，這麼快就挖出埋在這裡的古老故事。",
  ui_story_5080_50800901_20_dialog_content = "大叔我也是第一次看到，怪不得妳這麼年輕就是偵察隊長。",
  ui_story_5080_50800901_21_dialog_content = "醒山，你們從沒聽過生活在地底的人嗎？",
  ui_story_5080_50800901_22_dialog_content = "我和伊芙也算是外來人，哪懂什麼歷史故事。",
  ui_story_5080_50800901_23_dialog_content = "我和羅伊大叔都是啟光來的，雖然羅伊大叔是老資歷，恐怕也不懂這些吧。",
  ui_story_5080_50800901_24_dialog_content = "看我做什麼？大爺我還年輕得很，再說醒山都不知道，我怎麼會知道！",
  ui_story_5080_50800901_25_dialog_content = "如果那些人曾經在這裡生活，為什麼你們卻從來都沒聽過？",
  ui_story_5080_50800901_26_dialog_content = "勇者澤塔也沒有聽過，難道這是什麼超遠古遺跡？會不會埋著某種強大力量，光的巨人？",
  ui_story_5080_50800901_27_dialog_content = "抱歉喔，都怪大叔沒有好好督促孩子們學習，大家對歷史完全不感興趣。",
  ui_story_5080_50800901_28_dialog_content = "你要我每個月整理書單送過來，結果都沒看呢。",
  ui_story_5080_50800901_29_dialog_content = "對不起，耶利亞。",
  ui_story_5080_50800901_30_dialog_content = "那些不是我們要優先考慮的東西！",
  ui_story_5080_50800901_31_dialog_content = "就是說呀，勇者澤塔哪有時間管這些都過去的事情。",
  ui_story_5080_50800901_32_dialog_content = "哎呀，我也早就料到了，但聽到你們這樣說還真是……無奈呢。",
  ui_story_5080_50800901_33_dialog_content = "大家就真的只顧眼前，連腳下的土地、前人的託付代表什麼也不去探究。",
  ui_story_5080_50800901_34_dialog_content = "耶利亞小姐，妳一定知道的對吧？請妳告訴我們吧。",
  ui_story_5080_50800901_35_dialog_content = "我對沙漠的研究不算深刻，但要是說避難所，我倒是剛好知道相關的傳說故事。",
  ui_story_5080_50800901_36_dialog_content = "那也是「紅油扳手」的起源。",
  ui_story_5080_50800901_37_dialog_content = "不是前當家的收服遊匪，才有我們「紅油扳手」嗎？",
  ui_story_5080_50800901_38_dialog_content = "許久以前，沙漠中生活著不成體系的遊民，其中也有罪犯。",
  ui_story_5080_50800901_39_dialog_content = "那些人或許是害怕外界，或許是厭倦了外界，寧願生活在環境惡劣的沙漠裡。",
  ui_story_5080_50800901_40_dialog_content = "他們相信這裡是「自由」的。",
  ui_story_5080_50800901_41_dialog_content = "自由……",
  ui_story_5080_50800901_42_dialog_content = "某天，一個家族受到迫害的白夜城大小姐，被她的女僕帶往沙漠。",
  ui_story_5080_50800901_43_dialog_content = "女僕想帶她去自己的家鄉，遠離一切紛爭。",
  ui_story_5080_50800901_44_dialog_content = "「白夜城的紛爭」……是嗎。",
  ui_story_5080_50800901_45_dialog_content = "一個白夜城衛兵奉命來追捕她們，他認定，騎士的榮耀就是一切。",
  ui_story_5080_50800901_46_dialog_content = "有趣的是，一位啟光軍人也和他一樣來到沙漠，在村落搜查啟光逃兵。",
  ui_story_5080_50800901_47_dialog_content = "他所追逐的對象是個灰心喪志、失去守護信念的啟光工兵。",
  ui_story_5080_50800901_48_dialog_content = "失去意志的啟光士兵……",
  ui_story_5080_50800901_49_dialog_content = "在追逐的路上，啟光的處刑者陰錯陽差，誤以為白夜城衛兵和自己搶人。",
  ui_story_5080_50800901_50_dialog_content = "大小姐和女僕，偶遇上那位工兵，卻以為對方是賞金獵人。",
  ui_story_5080_50800901_51_dialog_content = "她們彼此恐懼、彼此追逐，卻又因為命運的無常被緊緊相連。",
  ui_story_5080_50800901_52_dialog_content = "在工兵的幫助下，大小姐和女僕順利逃離騎士。",
  ui_story_5080_50800901_53_dialog_content = "而在騎士的添亂裡，處刑者也沒能抓住逃兵，只能追向鹽石村。",
  ui_story_5080_50800901_54_dialog_content = "聽起來是一群笨蛋的傳說。",
  ui_story_5080_50800901_55_dialog_content = "不錯，正因為他們是「笨蛋」，這些人才始終沒有真正互相殘殺。",
  ui_story_5080_50800901_56_dialog_content = "那些人都秉持著自己的信念，明明手握良機，仍不想傷害對方。",
  ui_story_5080_50800901_57_dialog_content = "可是我很喜歡這樣的故事。",
  ui_story_5080_50800901_58_dialog_content = "最後的路程上，他們偶遇難得一見的沙塵暴，路上的一切都被狂暴的沙塵吞噬。",
  ui_story_5080_50800901_59_dialog_content = "危急關頭中，被追獵者向獵人伸出了援手，獵人也放下了自己的任務。",
  ui_story_5080_50800901_60_dialog_content = "歷經種種難關，獵人的任務早已超過期限，他們自己也即將被認定為「逃兵」。",
  ui_story_5080_50800901_61_dialog_content = "相似的處境、彼此扶持的情誼，終於讓他們互相理解，互相信任。",
  ui_story_5080_50800901_62_dialog_content = "他們最終約定，要一起前往鹽石村，在那個地方平靜生活。",
  ui_story_5080_50800901_63_dialog_content = "他們獲得幸福快樂的結局了嗎？",
  ui_story_5080_50800901_64_dialog_content = "不。當他們到達女僕的家鄉，那傳聞中的綠洲鹽石村後，才發現這裡已毀於火山爆發。",
  ui_story_5080_50800901_65_dialog_content = "倖存者還被外來的遊匪趁火打劫，處於水深火熱之中。",
  ui_story_5080_50800901_66_dialog_content = "綠洲根本不存在，他們注定無法得到安寧。",
  ui_story_5080_50800901_67_dialog_content = "外來者失去了希望，他們發現這裡和外界根本沒有差別。",
  ui_story_5080_50800901_68_dialog_content = "……",
  ui_story_5080_50800901_69_dialog_content = "倖存者在村中神女的帶領下逃向出口，正好與這些外來人相遇。",
  ui_story_5080_50800901_70_dialog_content = "想要尋求寄託的人，忽然成了別人的寄託。",
  ui_story_5080_50800901_71_dialog_content = "不管是一路意志堅定的騎士，還是說一不二的軍人，此時都還沒意識過來。",
  ui_story_5080_50800901_72_dialog_content = "千鈞一髮之際，誰也沒想到，那位工兵舉起了隨身扳手，向著遊匪們衝去。",
  ui_story_5080_50800901_73_dialog_content = "他的英勇舉動鼓舞了所有人，遊匪們終於被趕走。",
  ui_story_5080_50800901_74_dialog_content = "英雄的故事！澤塔知道，那把扳手就是「紅油扳手」對吧！",
  ui_story_5080_50800901_75_dialog_content = "呵呵，別著急，故事還沒講完。",
  ui_story_5080_50800901_76_dialog_content = "因為那位工兵，人們重新升起希望。於是他們再次出發，在沙漠中尋找新的綠洲。",
  ui_story_5080_50800901_77_dialog_content = "在路上，他們逐漸吸收更多遊民，不知不覺中就成了強大的勢力。",
  ui_story_5080_50800901_78_dialog_content = "最終，他們找到了一處盛產「紅油」的小型綠洲，從此安營紮寨。",
  ui_story_5080_50800901_79_dialog_content = "這就是阿塔爾……不，前代首領告訴我的傳說。",
  ui_story_5080_50800901_80_dialog_content = "這足以證明，很久以前這片沙漠就有光靈生存了呢。",
  ui_story_5080_50800901_81_dialog_content = "那些人和我們一樣，都在努力尋找著自己的生活。",
  ui_story_5080_50800901_82_dialog_content = "地下避難所，大概就是那些逃避追兵或遊匪的地方？",
  ui_story_5080_50800901_83_dialog_content = "但到底他們是被噴發的火山吞沒，還是因為在通道深處發現火山而離去……我就不知道了。",
  ui_story_5080_50800901_84_dialog_content = "嘖，還真是嫉妒……不公平！為什麼前當家的給你這麼多特殊待遇！她從來沒跟我們說過。",
  ui_story_5080_50800901_85_dialog_content = "那只是因為你們根本沒有這方面的興趣吧。",
  ui_story_5080_50800901_86_dialog_content = "我曾充滿求知慾，對她的故事非常有興趣，常常纏著她講故事。",
  ui_story_5080_50800901_87_dialog_content = "可是看看這一切，瞭解越多，越會被往事終將消逝的虛無感束縛……",
  ui_story_5080_50800901_88_dialog_content = "說起來，小醒山，當時你才剛加入不久，還忙著照顧妹妹吧。",
  ui_story_5080_50800901_89_dialog_content = "那時候日子還沒現在這麼舒服，每天光是想填飽肚子就有得忙了。",
  ui_story_5080_50800901_90_dialog_content = "你不也是，還要教青瞳開車什麼的！",
  ui_story_5080_50800901_91_dialog_content = "能夠活著就很好了……大叔我一直是這麼想。能夠活在當下就很好了。",
  ui_story_5080_50800901_92_dialog_content = "那時候的我們沒有條件去探索這一切。",
  ui_story_5080_50800901_93_dialog_content = "沒關係，現在不一樣了！",
  ui_story_5080_50800901_94_dialog_content = "現在紅油扳手的生活好得很，我有機會成為第一博學的人。",
  ui_story_5080_50800901_95_dialog_content = "醒山，你給我等著！回去以後我就認真學習，一定會成為比你更好的領袖！",
  ui_story_5080_50800901_96_dialog_content = "臭小子……現在日子過得好不是我的功勞嗎？",
  ui_story_5080_50800901_97_dialog_content = "你說……故事裡，那個人舉起隨身扳手，成為所謂的精神象徵。",
  ui_story_5080_50800901_98_dialog_content = "但啟光工程師的扳手並非武器，從來不會有那麼誇張的尺寸。",
  ui_story_5080_50800901_99_dialog_content = "現在紅油首領手中的扳手，那東西的重量恐怕要以噸來計算吧？",
  ui_story_5080_50800901_100_dialog_content = "不錯，現在除了我，沒幾個人能隨便揮動這東西了。",
  ui_story_5080_50800901_101_dialog_content = "什麼樣的工兵會隨身帶這種扳手？",
  ui_story_5080_50800901_102_dialog_content = "猛禽小姐，妳的意思是，這故事是假的嗎？",
  ui_story_5080_50800901_103_dialog_content = "那個「傳聞」，或許是你們首領為了美化紅油扳手的過往而編造出來的。",
  ui_story_5080_50800901_104_dialog_content = "啟光的資料中，這片沙漠一直遊匪橫行、為非作歹，煽動許多人成為逃兵。",
  ui_story_5080_50800901_105_dialog_content = "這些人自稱「紅油幫」，一直威脅著其他光靈。",
  ui_story_5080_50800901_106_dialog_content = "那個人……先是帶著我姑姑成為逃兵，逃到這裡後又加入紅油幫，隨後成為老大。",
  ui_story_5080_50800901_107_dialog_content = "她帶人強行讓遊民加入自己擴大力量，慢慢統治了這片沙漠，才會變成「紅油扳手」。",
  ui_story_5080_50800901_108_dialog_content = "這些故事，不過是她為了美化紅油扳手的歷史編造的。",
  ui_story_5080_50800901_109_dialog_content = "喂，啟光的，沒人教過妳不要對別人尊敬的對象胡說八道嗎？",
  ui_story_5080_50800901_110_dialog_content = "就算我們現在暫時結伴，也不代表妳能說這種話！",
  ui_story_5080_50800901_111_dialog_content = "等等，這樣的話又是為什麼呢，隊長？如果按妳所說，她已經統治了這裡，為什麼會想美化過去？",
  ui_story_5080_50800901_112_dialog_content = "我不認為醒山他們所相信的首領，會是那樣的人。",
  ui_story_5080_50800901_113_dialog_content = "她……難道真心想保護所有人嗎？",
  ui_story_5080_50800901_114_dialog_content = "所以……她才連你們的精神也想保護……",
  ui_story_5080_50800901_115_dialog_content = "……",
  ui_story_5080_50800901_116_dialog_content = "嘖，妳……明明什麼都明白嘛。",
  ui_story_5080_50800901_117_dialog_content = "等等，又地震了？",
  ui_story_5080_50800901_118_dialog_content = "不對，這是暗鬼群的動靜。",
  ui_story_5080_50800901_119_dialog_content = "看著吧，啟光的「軍蟻小姐」。我們紅油扳手的生存之道，我們紅油扳手守護家人的決心！",
  ui_story_5080_50800901_120_dialog_content = "現在就拿出全部的魄力，給妳看看！",
  ui_story_5080_50801000_1_dialog_content = "真是的，全是燙傷，哥哥太激動了啦。",
  ui_story_5080_50801000_2_dialog_content = "這等小傷，哥哥哪會放在眼裡！",
  ui_story_5080_50801000_3_dialog_content = "喂，羅伊，吃飯時間到了吧？大夥肚子該餓了！",
  ui_story_5080_50801000_4_dialog_content = "有什麼好吃的？",
  ui_story_5080_50801000_5_dialog_content = "也是呢——開飯啦開飯啦，孩子們，把鍋架起來！",
  ui_story_5080_50801000_6_dialog_content = "多恩，我們走！去抓點火山口的「野味」！",
  ui_story_5080_50801000_7_dialog_content = "你們在做什麼？",
  ui_story_5080_50801000_8_dialog_content = "當然是在好好休息啊，啟光的。",
  ui_story_5080_50801000_9_dialog_content = "別驚訝，他們向來都是這樣，吃飽了就什麼都好。",
  ui_story_5080_50801000_10_dialog_content = "如果妳不想吃他們的「奇怪料理」，我們也有自備食物。",
  ui_story_5080_50801000_11_dialog_content = "現在可是任務中！",
  ui_story_5080_50801000_12_dialog_content = "怎麼能說吃就吃……萬一被偷襲該怎麼辦？",
  ui_story_5080_50801000_13_dialog_content = "幼龍二號、空裔一號、白色槍兵，我們繼續任務。",
  ui_story_5080_50801000_14_dialog_content = "是，隊長！",
  ui_story_5080_50801000_15_dialog_content = "<color=#e8d9bb>咕——</color>",
  ui_story_5080_50801000_16_dialog_content = "這個……對不起……早上來不及吃飯……",
  ui_story_5080_50801000_17_dialog_content = "……",
  ui_story_5080_50801000_18_dialog_content = "隊長，我認識的一位啟光老兵曾經說過——「好好吃飯！吃飽飯，才有力氣打仗！」",
  ui_story_5080_50801000_19_dialog_content = "他認為這是他的至理名言，大家也都很信服。",
  ui_story_5080_50801000_20_dialog_content = "隊長，澤塔和薇絲她們都是從起床開始就忙著戰鬥和趕路……",
  ui_story_5080_50801000_21_dialog_content = "啟光的老兵應該都很清楚，那種餓著肚子還得連續戰鬥的感覺。",
  ui_story_5080_50801000_22_dialog_content = "就算沒吃飽，他們還是撐得下去。",
  ui_story_5080_50801000_23_dialog_content = "正因這樣，那些人才會希望後輩能好好吃飯。",
  ui_story_5080_50801000_24_dialog_content = "……不補充能量就無法上路，為了確保任務完成，我特許你們休息吃飯。",
  ui_story_5080_50801000_25_dialog_content = "我去放哨。不能每個人都鬆懈……",
  ui_story_5080_50801000_26_dialog_content = "隊長，至少妳也吃點壓縮軍糧啊，隊長！",
  ui_story_5080_50801000_27_dialog_content = "讓她去吧，她也只是想保證任務萬無一失。",
  ui_story_5080_50801000_28_dialog_content = "我們回來了——啊，你們怎麼先開動了！",
  ui_story_5080_50801000_29_dialog_content = "勇者澤塔做什麼都是效率第一！我要去幫忙放哨了！",
  ui_story_5080_50801000_30_dialog_content = "……妳的進食速度還真快。加以鍛鍊，可以成為很好的軍人。",
  ui_story_5080_50801000_31_dialog_content = "澤塔對變成啟光士兵沒有興趣，我可是注定要拯救世界的人！",
  ui_story_5080_50801000_32_dialog_content = "妳也吃一點吧！這個烤蟲乾很好吃，澤塔幫妳拿過來囉！",
  ui_story_5080_50801000_33_dialog_content = "謝謝……「棒棒糖少女」。",
  ui_story_5080_50801000_34_dialog_content = "澤塔是「救世主勇者」，才不是什麼路人角色一樣的「棒棒糖少女」！",
  ui_story_5080_50801000_35_dialog_content = "雖然妳很酷，但是品位還不夠！一定是因為從小被擄走當了「魔王軍」吧？",
  ui_story_5080_50801000_36_dialog_content = "真是辛苦妳了，「救世主失散的宿敵姐姐」！",
  ui_story_5080_50801000_37_dialog_content = "「姐姐」……？",
  ui_story_5080_50801000_38_dialog_content = "嗯！澤塔就是妳的「勇者妹妹」！放心吧，我一定會想辦法解除妳的精神束縛！",
  ui_story_5080_50801000_39_dialog_content = "咦？妳笑了？我第一次看到妳笑……果然是親情的力量嗎？！！",
  ui_story_5080_50801000_40_dialog_content = "別計較這孩子，她只是喜歡跟人玩，隨便設定……",
  ui_story_5080_50801000_41_dialog_content = "姐姐啊……呵……",
  ui_story_5080_50801000_42_dialog_content = "妳似乎聯想到什麼……妳有個妹妹，是嗎？",
  ui_story_5080_50801000_43_dialog_content = "是的……她非常聰慧，也比我更健壯，而且……很可愛。",
  ui_story_5080_50801000_44_dialog_content = "等她完成學業，就會成為一位模範軍人。",
  ui_story_5080_50801000_45_dialog_content = "我以她為榮。",
  ui_story_5080_50801000_46_dialog_content = "什麼嘛……唔……",
  ui_story_5080_50801000_47_dialog_content = "小澤塔，妳的表情很不服氣喔。",
  ui_story_5080_50801000_48_dialog_content = "讓人羡慕……澤塔是說！不是嫉妒！就是……",
  ui_story_5080_50801000_49_dialog_content = "有這樣的姐姐，妹妹一定很幸福。",
  ui_story_5080_50801000_50_dialog_content = "因為「飛鷹射手」比那個魔女要溫柔多了。",
  ui_story_5080_50801000_51_dialog_content = "不行，我還遠遠不夠。",
  ui_story_5080_50801000_52_dialog_content = "我還會繼續努力……繼續努力……不再給家人帶來麻煩。",
  ui_story_5080_50801000_53_dialog_content = "噢哇哇哇——",
  ui_story_5080_50801000_54_dialog_content = "幹嘛突然唱歌？吵死人了！",
  ui_story_5080_50801000_55_dialog_content = "這你就不知道了吧？芭芭拉說他的資質比你更好，所以他最近要拼命練習。",
  ui_story_5080_50801000_56_dialog_content = "什麼？！",
  ui_story_5080_50801000_57_dialog_content = "「比醒山更強的紅油第一男高音」——芭芭拉是這樣說的呢，哥哥。",
  ui_story_5080_50801000_58_dialog_content = "所以他要拼命練習才行，聽說他已經準備好用歌聲攏絡人心了。",
  ui_story_5080_50801000_59_dialog_content = "哎呀，那我也該練習了。我也答應了她們要加入樂團的。",
  ui_story_5080_50801000_60_dialog_content = "鼓棒在哪裡呢……這個不是……這個也不是……找到了！",
  ui_story_5080_50801000_61_dialog_content = "好，大叔我來打節奏！都練起來吧！",
  ui_story_5080_50801000_62_dialog_content = "這些傢伙……",
  ui_story_5080_50801000_63_dialog_content = "再激烈點！再激烈點！弗勞爾，你要把熱情都注入鼓棒！",
  ui_story_5080_50801000_64_dialog_content = "跟上我的聲音——呼應我吧！",
  ui_story_5080_50801000_65_dialog_content = "再吵就要呼應來暗鬼了。",
  ui_story_5080_50801000_66_dialog_content = "別敲牆壁，弗勞爾，小心把暗鬼引過來！",
  ui_story_5080_50801000_67_dialog_content = "還好醒山還有點常識，紅油扳手……",
  ui_story_5080_50801000_68_dialog_content = "扳手借你，要敲就在這上面敲，激情一點沒關係！",
  ui_story_5080_50801000_69_dialog_content = "你們不怕把暗鬼引出來？",
  ui_story_5080_50801000_70_dialog_content = "那也沒關係，反正我們正愁找不到牠們，不是嗎？調子再拉高一點！聲音大一點！",
  ui_story_5080_50801000_71_dialog_content = "哎……沒救了。",
  ui_story_5080_50801000_72_dialog_content = "生活在這樣廣袤的沙漠中，他們也不曾產生求知精神，就這樣每天胡鬧……",
  ui_story_5080_50801000_73_dialog_content = "可是，耶利亞，求知精神到底是什麼呢？",
  ui_story_5080_50801000_74_dialog_content = "空裔弟弟，你也開始迷茫了嗎？",
  ui_story_5080_50801000_75_dialog_content = "不是的，我只是覺得……生活在這樣惡劣的環境裡，醒山他們也從來沒抱怨過。",
  ui_story_5080_50801000_76_dialog_content = "一直以來，他們都在努力尋找快樂的生活方式，過得非常開心。",
  ui_story_5080_50801000_77_dialog_content = "我總覺得，他們已經充滿對自己人生的求知精神了。",
  ui_story_5080_50801000_78_dialog_content = "對呀，耶利亞小姐。您的知識這麼豐富，對生活卻總是有點消極……",
  ui_story_5080_50801000_79_dialog_content = "恕我直言，這樣真的就好嗎？",
  ui_story_5080_50801000_80_dialog_content = "被身在啟光的薇絲小姐這樣說，還真是讓人不知道怎麼回答。",
  ui_story_5080_50801000_81_dialog_content = "可能耶利亞小姐會覺得，啟光的人沒資格討論生活和自由。",
  ui_story_5080_50801000_82_dialog_content = "但我從小在那裡長大，我很清楚——啟光的宗旨是努力成為防線，守護身後之人。",
  ui_story_5080_50801000_83_dialog_content = "也許我們作出了犧牲，可是我知道，那些防線之後的人能夠幸福生活。",
  ui_story_5080_50801000_84_dialog_content = "像他們臉上的歡笑，就是我想守護的目標。",
  ui_story_5080_50801000_85_dialog_content = "我很高興，能看到他們在努力生活。能看到他們這樣自由，這就夠了。",
  ui_story_5080_50801000_86_dialog_content = "守護的……意義……？！！",
  ui_story_5080_50801000_87_dialog_content = "是嗎，你們對生活的看法也不一樣呢。",
  ui_story_5080_50801000_88_dialog_content = "為了他人而活嗎？在我看來，或許是有點不夠自由，但那也很了不起。",
  ui_story_5080_50801000_89_dialog_content = "嗯，該怎麼去想像呢？明明應該自己努力探索人生，卻和他人緊密相連……",
  ui_story_5080_50801000_90_dialog_content = "我果然還是覺得，人與人的連結是無法斬斷的。",
  ui_story_5080_50801000_91_dialog_content = "哪怕是耶利亞，就算不想成為快樂的笨蛋，現在也無法抹掉和大家的聯繫了吧？",
  ui_story_5080_50801000_92_dialog_content = "……是呢，現在家裡全是塗鴉，堆滿要給那些孩子的禮物和書籍。",
  ui_story_5080_50801000_93_dialog_content = "再神出鬼沒，還會被這幾個孩子埋伏個正著，連我的車也被她們亂開。",
  ui_story_5080_50801000_94_dialog_content = "雖然撞壞過，但澤塔有好好幫妳修好了！",
  ui_story_5080_50801000_95_dialog_content = "打滿了很特別的補丁喲。",
  ui_story_5080_50801000_96_dialog_content = "都到這個地步，耶利亞還覺得，自己和其他人毫無關聯嗎？",
  ui_story_5080_50801000_97_dialog_content = "怎麼，空裔弟弟這麼關心我的人際關係，是在擔心我嗎？",
  ui_story_5080_50801000_98_dialog_content = "就算融入這些人，我也不會減少徬徨。",
  ui_story_5080_50801000_99_dialog_content = "好，就是這個節奏！",
  ui_story_5080_50801000_100_dialog_content = "我感受到你們的熱情，感受到你們的心意了！快！一起唱！",
  ui_story_5080_50801000_101_dialog_content = "<color=#e8d9bb>在醒山的指揮下，紅油扳手們「拼命」放聲高歌。</color>",
  ui_story_5080_50801000_102_dialog_content = "<color=#e8d9bb>那真是毫不協調的歌聲，但每個人都用盡全力，不得不說也是一種默契。</color>",
  ui_story_5080_50801000_103_dialog_content = "他們的個性實在太過鮮明了，根本不是能融合在一起的人。",
  ui_story_5080_50801000_104_dialog_content = "偏偏這樣的一群傢伙，卻成為了「家人」。",
  ui_story_5080_50801000_105_dialog_content = "唱歸唱，小心別把湯鍋打翻呀！",
  ui_story_5080_50801000_106_dialog_content = "對了——耶利亞，我曾經去過龍洲，那裡有一種很神奇的食物，叫作「火鍋」。",
  ui_story_5080_50801000_107_dialog_content = "鍋裡煮著辣辣的湯，然後把各式各樣的食物扔進去，隨便撈起來吃。",
  ui_story_5080_50801000_108_dialog_content = "無論什麼樣的食材，下了那個辣鍋，味道都不會互相影響。",
  ui_story_5080_50801000_109_dialog_content = "現在生活在沙漠裡的大家，還真是像火鍋一樣。",
  ui_story_5080_50801000_110_dialog_content = "是紅油真是太好了。這沙漠那麼大，容得下每種人，讓他們自行去探索生命的寬度……",
  ui_story_5080_50801000_111_dialog_content = "火鍋……是嗎？",
  ui_story_5080_50801000_112_dialog_content = "耶利亞，妳聽……有聽見嗎？那隻鷹在歌唱。",
  ui_story_5080_50801000_113_dialog_content = "明明只是鳥類的長嘯而已。",
  ui_story_5080_50801000_114_dialog_content = "哈哈哈，耶利亞又怎麼知道，牠不是在為自己的旅途高歌呢？",
  ui_story_5080_50801000_115_dialog_content = "……為什麼，妳要對我說那個傳說？",
  ui_story_5080_50801000_116_dialog_content = "不覺得很厲害嗎？出生在紅油、白夜城、啟光的陌生人，身分全然不同，最後卻相逢相識。",
  ui_story_5080_50801000_117_dialog_content = "生活在這個多災多難的世界上，但孤獨的人們還願意付出感情。",
  ui_story_5080_50801000_118_dialog_content = "有人願意為了保護他人舉起扳手，成為領袖。有人則願意追隨這樣的人，一起付出努力。",
  ui_story_5080_50801000_119_dialog_content = "沙漠才變成了我們的家。",
  ui_story_5080_50801000_120_dialog_content = "明明只是在旅途中掠過天空，卻匯聚成鳥群，尋找自己的綠洲。",
  ui_story_5080_50801000_121_dialog_content = "耶利亞，努力去探索妳生命的寬度，用力地飛，拼命地唱吧！",
  ui_story_5080_50801000_122_dialog_content = "妳怎麼會永遠徬徨？這裡早就為妳留下了位置——",
  ui_story_5080_50801101_1_dialog_content = "<color=#e8d9bb>堪比烈陽的吉他聲響起，刺穿沙漠的熱氣，將地面震動都比了下去。</color>",
  ui_story_5080_50801101_2_dialog_content = "前進，前進！我的意志永不停！",
  ui_story_5080_50801101_3_dialog_content = "天氣這麼熱，真虧她能在這種地方排練新曲。",
  ui_story_5080_50801101_4_dialog_content = "芭芭拉也不能落後！小不點，我們上！",
  ui_story_5080_50801101_5_dialog_content = "「舞台」修好了，我還要忙，妳自己去吧。",
  ui_story_5080_50801101_6_dialog_content = "喂？這裡是紅油扳手……",
  ui_story_5080_50801101_7_dialog_content = "叭噗，約娜要我快點回去，是有什麼事情嗎？",
  ui_story_5080_50801101_8_dialog_content = "看過來～永遠閃耀的偶像！紅油甜心，芭芭拉喲！",
  ui_story_5080_50801101_9_dialog_content = "喂？這裡是紅油扳手……是青瞳嗎？妳是青瞳嗎？",
  ui_story_5080_50801101_10_dialog_content = "哎呀，那邊很熱鬧呢。",
  ui_story_5080_50801101_11_dialog_content = "烈陽在咆哮！烈陽在咆哮！！！",
  ui_story_5080_50801101_12_dialog_content = "喂？這裡是紅油扳手……",
  ui_story_5080_50801101_13_dialog_content = "喂喂？我完全聽不到，算了，等著姐姐回去吧。",
  ui_story_5080_50801101_14_dialog_content = "喂，瑪姬，妳有好好裝地雷嗎？",
  ui_story_5080_50801101_15_dialog_content = "太熱了……我知道啦知道啦，馬上裝就是了！",
  ui_story_5080_50801101_16_dialog_content = "動作快一點，在太陽下山前把營地四周全部佈滿！",
  ui_story_5080_50801101_17_dialog_content = "真的有必要設這麼多爆炸陷阱嗎？",
  ui_story_5080_50801101_18_dialog_content = "<color=#e8d9bb>沙漠的震動還在持續，遠處火山發出咆哮，持續釋放憤怒。</color>",
  ui_story_5080_50801101_19_dialog_content = "首領他們去好久了……",
  ui_story_5080_50801101_20_dialog_content = "通訊也都沒有回覆。",
  ui_story_5080_50801101_21_dialog_content = "小不點，弗勞爾不在，妳來幫我修理卡車。",
  ui_story_5080_50801101_22_dialog_content = "哼，想跟我比功夫？妳還不願意承認我比較強嗎？",
  ui_story_5080_50801101_23_dialog_content = "莫名其妙啊妳！",
  ui_story_5080_50801101_24_dialog_content = "我們是不是應該開著陸行者號行動起來呢？",
  ui_story_5080_50801101_25_dialog_content = "喂，小叭噗，剛剛的通訊是青瞳嗎？",
  ui_story_5080_50801101_26_dialog_content = "我不知道……",
  ui_story_5080_50801101_27_dialog_content = "妳接的妳怎麼會不知道？",
  ui_story_5080_50801101_28_dialog_content = "請妳回去巡邏，待會……",
  ui_story_5080_50801101_29_dialog_content = "算了，除了青瞳應該也不會有別人了。",
  ui_story_5080_50801101_30_dialog_content = "真是難得一約，事情了結後，一定要抓她去大喝一頓。",
  ui_story_5080_50801101_31_dialog_content = "……聽我說呀。",
  ui_story_5080_50801101_32_dialog_content = "到了，這裡是最接近火山口的邊緣。",
  ui_story_5080_50801101_33_dialog_content = "從這裡跳下去，就能到火山口內——",
  ui_story_5080_50801101_34_dialog_content = "這座火山的活躍度……獵鷹一號，開啟探測模式！",
  ui_story_5080_50801101_35_dialog_content = "……果然，這座火山處於極度活躍的狀態。",
  ui_story_5080_50801101_36_dialog_content = "為什麼還沒到達噴發的臨界點？",
  ui_story_5080_50801101_37_dialog_content = "這不是死火山甦醒的程度。它一直充滿著力量。",
  ui_story_5080_50801101_38_dialog_content = "這麼多年來，它也沒有噴發過。",
  ui_story_5080_50801101_39_dialog_content = "真奇怪……",
  ui_story_5080_50801101_40_dialog_content = "喂喂喂，不會吧！火山口裡都爬出暗鬼了啊！",
  ui_story_5080_50801101_41_dialog_content = "是那種暗鬼……看來牠們的岩漿能量就是從這裡來的。",
  ui_story_5080_50801101_42_dialog_content = "要上了，快跳！",
  ui_story_5080_50801101_43_dialog_content = "薇絲、卡蓮……等等我！好高啊！",
  ui_story_5080_50801102_1_dialog_content = "暗鬼再怎麼說，也應該是「生物」吧？",
  ui_story_5080_50801102_2_dialog_content = "怎麼會有暗鬼在火山口裡居住？牠們不只能利用岩漿的能量，甚至還不怕岩漿？",
  ui_story_5080_50801102_3_dialog_content = "弗勞爾，你來算算，怎樣才能炸毀這個火山口？",
  ui_story_5080_50801102_4_dialog_content = "如果暗鬼連岩漿都不怕，只有這個辦法能讓牠們不再出來。",
  ui_story_5080_50801102_5_dialog_content = "不行，那位小姐說的對，這是活火山。貿然引爆，可能反而會誘使火山噴發。",
  ui_story_5080_50801102_6_dialog_content = "震動還在持續，暗鬼又不停從深處跑出來……",
  ui_story_5080_50801102_7_dialog_content = "不知道外面怎麼樣了，我們得速戰速決才行。",
  ui_story_5080_50801102_8_dialog_content = "為什麼火山一直這麼活躍，卻又長期處於假沉眠狀態？",
  ui_story_5080_50801102_9_dialog_content = "到底是什麼原因？",
  ui_story_5080_50801102_10_dialog_content = "火山的怒火，很可能是因為地脈能量不穩定。",
  ui_story_5080_50801102_11_dialog_content = "如果能找到原因，或許我們能解決危機。",
  ui_story_5080_50801102_12_dialog_content = "不管怎麼樣，我們得快點行動。",
  ui_story_5080_50801102_13_dialog_content = "再這樣震下去，暗鬼都會被嚇到地表上。",
  ui_story_5080_50801102_14_dialog_content = "紅油的大家還好說，那些村落裡的平民怎麼辦？",
  ui_story_5080_50801102_15_dialog_content = "的確是這樣沒錯。醒山，你有什麼想法？",
  ui_story_5080_50801102_16_dialog_content = "沒辦法，既然這些傢伙從裡面進來，那我就進裡面看看。",
  ui_story_5080_50801102_17_dialog_content = "<size=45>什麼？！</size>",
  ui_story_5080_50801102_18_dialog_content = "醒山，你清醒一點，這可是火山。",
  ui_story_5080_50801102_19_dialog_content = "我很清醒啊，就是這樣才不能放著它不管。",
  ui_story_5080_50801102_20_dialog_content = "整天叫叫叫，煩死人了。新仇也好，舊怨也好，我要跟它一次算清楚。",
  ui_story_5080_50801102_21_dialog_content = "你……為什麼這樣拼命？",
  ui_story_5080_50801102_22_dialog_content = "哈，讓妳來說這句話還真奇怪。",
  ui_story_5080_50801102_23_dialog_content = "明明紅油扳手是「逃兵」，你也是出身於這樣的組織。",
  ui_story_5080_50801102_24_dialog_content = "一直以來，你們都靠掠奪他人為生對吧？隨遇而安，得過且過。",
  ui_story_5080_50801102_25_dialog_content = "為什麼會想要付出生命？",
  ui_story_5080_50801102_26_dialog_content = "那好，我問妳。妳在啟光的時候都在做些什麼呢？為什麼會跑這麼老遠來火山裡。",
  ui_story_5080_50801102_27_dialog_content = "我是「鷹眼小隊」的隊長！我是率隊完成過四十多次高難度特種行動的人。",
  ui_story_5080_50801102_28_dialog_content = "不是我的話，其他人來只會更加危險。",
  ui_story_5080_50801102_29_dialog_content = "我是為了榮耀而來，和你們絕對不一樣。",
  ui_story_5080_50801102_30_dialog_content = "妳知道嗎？這邊的弗勞爾，還有這個大叔，他們全都是迦南城出身的喔。",
  ui_story_5080_50801102_31_dialog_content = "他們在那裡沒有感受到什麼榮光，反而因為喘不過氣，才不得不逃到沙漠裡。",
  ui_story_5080_50801102_32_dialog_content = "榮光到底是什麼？",
  ui_story_5080_50801102_33_dialog_content = "榮光就是——",
  ui_story_5080_50801102_34_dialog_content = "啟光的小姐，請妳告訴我，妳真的明白「犧牲」的意義嗎？",
  ui_story_5080_50801102_35_dialog_content = "為了啟明之光，為了解放所有光靈的覺悟！不惜生命，不計代價！",
  ui_story_5080_50801102_36_dialog_content = "我隨時都可以為了那些偉業犧牲！",
  ui_story_5080_50801102_37_dialog_content = "……",
  ui_story_5080_50801102_38_dialog_content = "為什麼要擺出那樣的表情？",
  ui_story_5080_50801102_39_dialog_content = "妳就是這麼騙自己的？",
  ui_story_5080_50801102_40_dialog_content = "算了，看来现在跟妳说这些没用。",
  ui_story_5080_50801102_41_dialog_content = "羅伊，她還沒從夢裡醒過來。",
  ui_story_5080_50801102_42_dialog_content = "你……！",
  ui_story_5080_50801102_43_dialog_content = "借過，我要打掃家裡的蟲子窩了，請不要多管閒事。",
  ui_story_5080_50801102_44_dialog_content = "喂喂，小醒山，誰說你可以一個人去打掃，別把我們給忘了啊。",
  ui_story_5080_50801102_45_dialog_content = "你們這些傢伙，不要一起站上來啊，很危險的。",
  ui_story_5080_50801102_46_dialog_content = "你還不是一樣，笨蛋！",
  ui_story_5080_50801102_47_dialog_content = "一起跳火山嗎？總覺得很不明智。",
  ui_story_5080_50801102_48_dialog_content = "準備了，大家——嗚哇！",
  ui_story_5080_50801102_49_dialog_content = "是地震，小心！",
  ui_story_5080_50801102_50_dialog_content = "<color=#e8d9bb>突如其來的地震，讓站在火山口邊緣的眾人摔入其中。</color>",
  ui_story_5080_50801102_51_dialog_content = "哥哥——！",
  ui_story_5080_50801102_52_dialog_content = "伊芙！！！大家！！！我馬上來！！！",
  ui_story_5080_50801102_53_dialog_content = "別想在我面前——再帶走任何人！",
  ui_story_5080_50801102_54_dialog_content = "<color=#e8d9bb>醒山就像一顆砲彈那樣飛了下來，用自己的怪力強行把所有人都拋向安全地點。</color>",
  ui_story_5080_50801102_55_dialog_content = "<color=#e8d9bb>他飛得越來越近——不知為何，PlayerName突然感到一陣安心。</color>",
  ui_story_5080_50801102_56_dialog_content = "PlayerName，抓住我的手——！",
  ui_story_5080_50801102_57_dialog_content = "等等，醒山！下面就是岩漿，你怎麼辦！",
  ui_story_5080_50801102_58_dialog_content = "哪管那麼多！給我上去！",
  ui_story_5080_50801102_59_dialog_content = "你小子——可別掛了啊。",
  ui_story_5080_50801102_60_dialog_content = "<size=50>醒山！！！</size>",
  ui_story_5080_50801201_1_dialog_content = "任務順利完成，「鷹眼」做出了巨大貢獻！",
  ui_story_5080_50801201_2_dialog_content = "辛苦妳了，蕾切爾，啟光會銘記你們所付出的犧牲。",
  ui_story_5080_50801201_3_dialog_content = "上前一步，士兵。大元帥要親自頒布榮譽勳章給妳！",
  ui_story_5080_50801201_4_dialog_content = "我們已經盡力救援了——對不起，蕾切爾，我只能親手交給妳這個，感謝你們的付出。",
  ui_story_5080_50801201_5_dialog_content = "啊……！！！",
  ui_story_5080_50801201_6_dialog_content = "好重……",
  ui_story_5080_50801201_7_dialog_content = "嗯？",
  ui_story_5080_50801201_8_dialog_content = "他們就在這裡……在我的手上……好重……",
  ui_story_5080_50801201_9_dialog_content = "為了我一個人……我的隊員全都……全都犧牲了……",
  ui_story_5080_50801201_10_dialog_content = "來人，快來人！她要昏過去了！",
  ui_story_5080_50801201_11_dialog_content = "胸口好痛，明明我沒有受傷，可是痛苦停不下來……姑姑……",
  ui_story_5080_50801201_12_dialog_content = "謝謝妳，隊長……謝謝妳拼盡全力完成了任務。",
  ui_story_5080_50801201_13_dialog_content = "這樣一來，我們的孩子終於不是「失敗者」了。",
  ui_story_5080_50801201_14_dialog_content = "他們終於以英雄的身分安息了。",
  ui_story_5080_50801201_15_dialog_content = "不對——",
  ui_story_5080_50801201_16_dialog_content = "我好難過，姑姑……明明我完成了任務，但我真的好難受，好難受……",
  ui_story_5080_50801201_17_dialog_content = "蕾切爾，我的孩子，別哭……別哭……",
  ui_story_5080_50801201_18_dialog_content = "是我的錯，明明是我的錯，為什麼叔叔阿姨們還要感謝我……",
  ui_story_5080_50801201_19_dialog_content = "妳拯救了她們最後的尊嚴。",
  ui_story_5080_50801201_20_dialog_content = "可是……他們應該好好回來，和父母團聚的啊……",
  ui_story_5080_50801201_21_dialog_content = "蕾切爾，看著我。妳能背負那樣的責任嗎？讓所有人變成逃兵，只為了讓他們平安回家？",
  ui_story_5080_50801201_22_dialog_content = "我……我……我不知道……我不知道……",
  ui_story_5080_50801201_23_dialog_content = "怎麼回事，蕾切爾，這已經是妳第六次任務失敗了。",
  ui_story_5080_50801201_24_dialog_content = "妳明明已經休息過了，怎麼會這樣？",
  ui_story_5080_50801201_25_dialog_content = "對不起，這全都是我的責任，請不要怪罪其他隊員。",
  ui_story_5080_50801201_26_dialog_content = "她們全都投訴了妳。妳連她們的名字、樣子都記不住，妳到底怎麼了？",
  ui_story_5080_50801201_27_dialog_content = "我……對不起……對不起……",
  ui_story_5080_50801201_28_dialog_content = "妳暫時先不要出任務了。我會幫妳安排休假。",
  ui_story_5080_50801201_29_dialog_content = "對不起……軍團長……",
  ui_story_5080_50801201_30_dialog_content = "灰翼的名字叫「路易」，他出生在北方，所以一直想去沙漠裡玩。",
  ui_story_5080_50801201_31_dialog_content = "他說過，想要去北境削一節白樹的木頭做成笛子，送給白雁。",
  ui_story_5080_50801201_32_dialog_content = "白雁的名字叫「梅麗」，她雖然一直想學樂器，但都是嘴上說說，一直沒有真的去學。",
  ui_story_5080_50801201_33_dialog_content = "她說要在我生日那天演奏曲子給我聽，但已經拖了好幾年了。",
  ui_story_5080_50801201_34_dialog_content = "對了，還有紅隼和青梟，她們……",
  ui_story_5080_50801201_35_dialog_content = "她們已經變成這串項鍊，永永遠遠掛在我的脖子上了。",
  ui_story_5080_50801201_36_dialog_content = "「妳能背負那樣的責任嗎？讓所有人變成逃兵，只為了讓他們平安回家？」",
  ui_story_5080_50801201_37_dialog_content = "PlayerName！",
  ui_story_5080_50801201_38_dialog_content = "……！",
  ui_story_5080_50801201_39_dialog_content = "薇絲，我在這！隊長、弗勞爾、澤塔，你們沒事吧？",
  ui_story_5080_50801201_40_dialog_content = "我沒事。",
  ui_story_5080_50801201_41_dialog_content = "太好了，PlayerName也沒事。",
  ui_story_5080_50801201_42_dialog_content = "看來火山口塌了，其他人呢？",
  ui_story_5080_50801201_43_dialog_content = "似乎跟我們不在同一層呢。哼哼，這就是魔王城之前的經典劇情！",
  ui_story_5080_50801201_44_dialog_content = "那個紅油首領，居然為了我們跳進岩漿……",
  ui_story_5080_50801201_45_dialog_content = "往下走，我們得去找醒山。",
  ui_story_5080_50801201_46_dialog_content = "全是岩漿……沒辦法，努力繞開這些地方吧。",
  ui_story_5080_50801201_47_dialog_content = "任務優先，我們應該避開不必要的危險區域。",
  ui_story_5080_50801201_48_dialog_content = "是醒山救了我們，我得去找他們。跟著我，我應該能感應到他們。",
  ui_story_5080_50801201_49_dialog_content = "空之末裔，你的台詞未免太帥了，怎麼可以搶我的戲！我也要去！",
  ui_story_5080_50801201_50_dialog_content = "隊長，我也想去救援他們。",
  ui_story_5080_50801201_51_dialog_content = "……妳的手臂受傷了，是剛剛摔落時擦破的嗎？",
  ui_story_5080_50801201_52_dialog_content = "咦？真的……流血了。",
  ui_story_5080_50801201_53_dialog_content = "這個拿去，自己包紮止血。妳現在不適合在前線擔任護衛，走的時候跟在我後面。",
  ui_story_5080_50801201_54_dialog_content = "走？",
  ui_story_5080_50801201_55_dialog_content = "下去，也許「目標」就在下面。",
  ui_story_5080_50801201_56_dialog_content = "是！",
  ui_story_5080_50801201_57_dialog_content = "這裡全是暗鬼……牠們怎麼會住在這種活火山裡？",
  ui_story_5080_50801201_58_dialog_content = "暗鬼也是生物，本來應該會避開這種危險區域。",
  ui_story_5080_50801201_59_dialog_content = "和我在軍校學到的完全不一樣。",
  ui_story_5080_50801201_60_dialog_content = "……這種暗鬼，啟光很久以前就發現了。",
  ui_story_5080_50801201_61_dialog_content = "什麼？為什麼我從來沒聽過？",
  ui_story_5080_50801201_62_dialog_content = "那個時候，委員會指派我姑姑所在的隊伍，執行了和我們一樣的調查任務。",
  ui_story_5080_50801201_63_dialog_content = "她的隊長，就是正式成立了「紅油扳手」的人。",
  ui_story_5080_50801201_64_dialog_content = "妳應該知道吧？妳的姑姑曾在「自由鳥」中服役。",
  ui_story_5080_50801201_65_dialog_content = "她最後一次任務，是委員會直接指派的重要任務。但她不僅失敗而歸，隊長還在事後叛逃啟光。",
  ui_story_5080_50801201_66_dialog_content = "很多人這麼議論：「自由鳥小隊為了苟活，擅自放棄任務。」妳對這件事又怎麼想？",
  ui_story_5080_50801201_67_dialog_content = "我很慚愧！大元帥。對於我姑姑的失敗，我非常的……愧疚。",
  ui_story_5080_50801201_68_dialog_content = "但她本人非常忠誠，只是被那位隊長連累了而已！",
  ui_story_5080_50801201_69_dialog_content = "請您給我一次機會，讓我重振家族的榮光。",
  ui_story_5080_50801201_70_dialog_content = "可是，如果沒有發生這種「醜事」，妳的姑姑很可能會死為英雄。",
  ui_story_5080_50801201_71_dialog_content = "對妳而言，這難道是更好接受的事情嗎？",
  ui_story_5080_50801201_72_dialog_content = "這個……我……我……",
  ui_story_5080_50801201_73_dialog_content = "哈哈哈——我只是問問而已。",
  ui_story_5080_50801201_74_dialog_content = "現在，我就告訴妳，我找妳來的原因吧——我要給妳一個任務。",
  ui_story_5080_50801201_75_dialog_content = "妳姑姑最後一次任務，就是我想指派給妳的任務內容。",
  ui_story_5080_50801201_76_dialog_content = "大元帥？",
  ui_story_5080_50801201_77_dialog_content = "當年委員會要求自由鳥，必須把那隻觀測到的暗鬼活抓回來。",
  ui_story_5080_50801201_78_dialog_content = "他們想要活體，以供實驗。",
  ui_story_5080_50801201_79_dialog_content = "我對那種研究是好是壞還抱持懷疑態度，所以我不會強制要求妳怎麼做。",
  ui_story_5080_50801201_80_dialog_content = "我……",
  ui_story_5080_50801201_81_dialog_content = "當然，活抓到那種暗鬼的話，也許能彌補妳姑姑的遺憾。",
  ui_story_5080_50801201_82_dialog_content = "不過，蕾切爾，妳可以自己決定怎麼做。",
  ui_story_5080_50801201_83_dialog_content = "我為妳的任務挑選了很特別的隊友，妳應該也聽過「薇絲」這個名字吧？",
  ui_story_5080_50801201_84_dialog_content = "傳聞中……和空裔組成搭檔的那位年輕隊長？但她不是長時間跟著空裔——",
  ui_story_5080_50801201_85_dialog_content = "不錯。只要她加入，身為她搭檔的那位空裔也一定會加入。",
  ui_story_5080_50801201_86_dialog_content = "他們是很不可思議的人，妳一定會在這次的任務中，得到某些答案。",
  ui_story_5080_50801201_87_dialog_content = "這也是緋向我仔細提出的要求。妳有個很好的長官，蕾切爾。",
  ui_story_5080_50801201_88_dialog_content = "非常感謝您，還有緋長官。謝謝你們還願意相信我，給我這次機會！",
  ui_story_5080_50801201_89_dialog_content = "我現在就去準備出發！",
  ui_story_5080_50801201_90_dialog_content = "等一等，蕾切爾。",
  ui_story_5080_50801201_91_dialog_content = "請您放心，我一定會完成任務！",
  ui_story_5080_50801201_92_dialog_content = "我只是想問妳一句話——",
  ui_story_5080_50801201_93_dialog_content = "現在的妳，還能找到自己心中的啟明之光嗎？",
  ui_story_5080_50801201_94_dialog_content = "我……我知道大元帥在擔憂什麼。",
  ui_story_5080_50801201_95_dialog_content = "我確實指揮失誤，導致隊伍覆滅。現在還和其他隊員處不來……",
  ui_story_5080_50801201_96_dialog_content = "但請您放心，我絕對不會再犯錯。",
  ui_story_5080_50801201_97_dialog_content = "不是說那個啦……不過算了，妳去吧。",
  ui_story_5080_50801201_98_dialog_content = "有她們在，一定能改變妳的想法。",
  ui_story_5080_50801201_99_dialog_content = "她們是傳說中的搭檔，是擁有力量的人。她們的話，一定沒問題。",
  ui_story_5080_50801201_100_dialog_content = "我會加倍注意，繼續保持……不再和任何隊友扯上關係，不再連累任何人……",
  ui_story_5080_50801201_101_dialog_content = "姑姑，告訴您一個好消息。",
  ui_story_5080_50801201_102_dialog_content = "我又接到任務了。",
  ui_story_5080_50801201_103_dialog_content = "是嗎？那真是太好了。不過妳沒關係嗎？不要逞強喔。",
  ui_story_5080_50801201_104_dialog_content = "我沒事的，姑姑。而且這一次，我或許會有機會去調查當年的事情。",
  ui_story_5080_50801201_105_dialog_content = "我一定會幫妳洗清冤屈。",
  ui_story_5080_50801201_106_dialog_content = "不是那樣的，蕾切爾。",
  ui_story_5080_50801201_107_dialog_content = "對於當年的事情，姑姑我一次也沒有後悔過。能夠倖存下來，我深深感謝著隊長。",
  ui_story_5080_50801201_108_dialog_content = "如果不是她，我就無法見到妳了。",
  ui_story_5080_50801201_109_dialog_content = "妳為什麼還在幫她說話……她可是逃離了啟光的人。",
  ui_story_5080_50801201_110_dialog_content = "隊長她絕對不是逃兵，更不是叛徒！",
  ui_story_5080_50801201_111_dialog_content = "這其中一定有什麼我們不知道的原因，但我絕對相信她！",
  ui_story_5080_50801201_112_dialog_content = "她害你們都變成了「背叛者」！這麼多年也從沒想過要回來，為什麼妳還相信她！",
  ui_story_5080_50801201_113_dialog_content = "我的生命、夥伴們的生命，都是隊長一個人從那個「熔岩地獄」裡背回來的！",
  ui_story_5080_50801201_114_dialog_content = "她才是真正的英雄！",
  ui_story_5080_50801201_115_dialog_content = "我只是想幫姑姑洗清冤屈……",
  ui_story_5080_50801201_116_dialog_content = "我們一家沒有任何錯……",
  ui_story_5080_50801201_117_dialog_content = "蕾切爾？妳要去哪？",
  ui_story_5080_50801201_118_dialog_content = "回來，蕾切爾！妳絕對不能去那個地方！",
  ui_story_5080_50801201_119_dialog_content = "蕾切爾——",
  ui_story_5080_50801201_120_dialog_content = "雖然自由鳥的任務失敗了，但還是調查出不少情報。",
  ui_story_5080_50801201_121_dialog_content = "她們留下的資料提到，當年的「那隻暗鬼」是汲取地脈能量維生的變異種。",
  ui_story_5080_50801201_122_dialog_content = "而這座火山充斥著那樣的暗鬼，常年活躍卻始終沒有到達爆發的臨界值。",
  ui_story_5080_50801201_123_dialog_content = "很有可能是因為，這些暗鬼在汲取著火山的能量。",
  ui_story_5080_50801201_124_dialog_content = "紅油沙漠火山不穩定，是因為地脈能量不穩定。",
  ui_story_5080_50801201_125_dialog_content = "那種暗鬼的活躍導致地脈能量失衡，牠們的「吸食」卻又抑制著火山沒有爆發。",
  ui_story_5080_50801201_126_dialog_content = "從這樣來看，那些暗鬼很可能一直在地底「繁衍」。",
  ui_story_5080_50801201_127_dialog_content = "從當年被觀測到的一隻，變成了現在的一群。",
  ui_story_5080_50801201_128_dialog_content = "而且牠甚至把這種可怕的特性給遺傳下來。",
  ui_story_5080_50801201_129_dialog_content = "不對，照這麼說，我們還得感謝那些傢伙嗎？",
  ui_story_5080_50801201_130_dialog_content = "「多虧了牠們，火山才沒有爆發」？這也太氣人了。",
  ui_story_5080_50801201_131_dialog_content = "但要不是這些暗鬼，地脈能量也不會變得如此不穩定，環境就不會這麼惡劣。",
  ui_story_5080_50801201_132_dialog_content = "開車時也不會常遇上可惡的地震了！",
  ui_story_5080_50801201_133_dialog_content = "進一步想想，沙漠的荒蕪，到底和這些傢伙有沒有關係呢？",
  ui_story_5080_50801201_134_dialog_content = "不管怎麼說，暗鬼居然能<color=#FFB400>吸食</color>火山的力量，這種事情還是太誇張了。",
  ui_story_5080_50801201_135_dialog_content = "如果當年<color=#FFB400>那隻暗鬼</color>還存在，牠存活了這麼久，力量到底該多強大？",
  ui_story_5080_50801201_136_dialog_content = "不能讓牠再活下去……",
  ui_story_5080_50801201_137_dialog_content = "絕對不能讓牠再延續下去……",
  ui_story_5080_50801201_138_dialog_content = "那我們就繼續衝吧！向著深處！向著醒山！",
  ui_story_5080_50801202_1_dialog_content = "糟糕，這裡地方太小了。",
  ui_story_5080_50801202_2_dialog_content = "而且旁邊都是岩漿，小心！",
  ui_story_5080_50801202_3_dialog_content = "幼龍二號、棒棒糖少女，躲在我後面！",
  ui_story_5080_50801202_4_dialog_content = "獵鷹一二三號，火力全開！",
  ui_story_5080_50801202_5_dialog_content = "隊長，別逞強，這些暗鬼的防禦力太高了！",
  ui_story_5080_50801202_6_dialog_content = "別說話，專心攻擊！",
  ui_story_5080_50801202_7_dialog_content = "別害怕，交給澤塔的甜蜜炸彈，馬上就結束了。",
  ui_story_5080_50801202_8_dialog_content = "吼——！",
  ui_story_5080_50801202_9_dialog_content = "隊長！",
  ui_story_5080_50801202_10_dialog_content = "一點小傷而已，在後面躲好。",
  ui_story_5080_50801202_11_dialog_content = "牠要繼續攻擊了！",
  ui_story_5080_50801202_12_dialog_content = "獵鷹一號，回來防守！",
  ui_story_5080_50801202_13_dialog_content = "糟糕，來不及……",
  ui_story_5080_50801202_14_dialog_content = "勇者突襲！",
  ui_story_5080_50801202_15_dialog_content = "吼——！",
  ui_story_5080_50801202_16_dialog_content = "澤塔？！！！",
  ui_story_5080_50801202_17_dialog_content = "棒棒糖少女！！！",
  ui_story_5080_50801202_18_dialog_content = "弗勞爾，我用強制感應控制住牠了，就是現在！",
  ui_story_5080_50801202_19_dialog_content = "給我——消失！",
  ui_story_5080_50801202_20_dialog_content = "打進岩漿了？",
  ui_story_5080_50801202_21_dialog_content = "呱嗚！！！",
  ui_story_5080_50801202_22_dialog_content = "牠被岩漿吞沒了……這種暗鬼不是不怕岩漿嗎……？",
  ui_story_5080_50801202_23_dialog_content = "棒棒糖少女，妳沒事吧？！！",
  ui_story_5080_50801202_24_dialog_content = "嘿嘿，怎麼樣呀，飛鷹射手？紅油扳手的人，其實也不賴吧……",
  ui_story_5080_50801202_25_dialog_content = "為什麼，為了我……",
  ui_story_5080_50801202_26_dialog_content = "因為妳是澤塔「失散多年誤入歧途的姐姐」……",
  ui_story_5080_50801202_27_dialog_content = "棒棒糖少女？棒棒糖少女！",
  ui_story_5080_50801202_28_dialog_content = "（糟糕，我們沒有醫療包，澤塔的傷勢該怎麼辦……嗯？）",
  ui_story_5080_50801202_29_dialog_content = "我又指揮出錯了嗎？又一次，讓別人為了我……",
  ui_story_5080_50801202_30_dialog_content = "明明我想保護她們才對……",
  ui_story_5080_50801202_31_dialog_content = "為什麼我又犯了這種錯，是我太自我中心了嗎？",
  ui_story_5080_50801202_32_dialog_content = "別太自責，澤塔還有救！快，把她抱到我背上，我們趕快離開。",
  ui_story_5080_50801202_33_dialog_content = "澤塔，醒醒！我一定會帶妳回去，撐住啊！",
  ui_story_5080_50801202_34_dialog_content = "「改邪歸正的魔人技師」，澤塔的旅途恐怕就到此為止了，以後你們就把我忘了吧……",
  ui_story_5080_50801202_35_dialog_content = "開什麼玩笑？！！",
  ui_story_5080_50801202_36_dialog_content = "給我醒醒，妳忘了還跟我訂了新氣閥嗎？",
  ui_story_5080_50801202_37_dialog_content = "再給我點時間，我就能琢磨出更先進的雙八缸引擎，妳不想開開看嗎？",
  ui_story_5080_50801202_38_dialog_content = "嗯？！",
  ui_story_5080_50801202_39_dialog_content = "只要妳撐過去，我以後只幫妳改造車子，不幫青瞳了，怎麼樣？",
  ui_story_5080_50801202_40_dialog_content = "還有，妳不是一直都想知道青瞳車子的規格嗎？我幫妳打聽！",
  ui_story_5080_50801202_41_dialog_content = "我們一起去找羅伊，要他也加入我們……澤塔，醒醒。",
  ui_story_5080_50801202_42_dialog_content = "我會和大叔去對青瞳惡作劇，妳就等著看吧！",
  ui_story_5080_50801202_43_dialog_content = "對、對了。棒棒糖少女，我也可以幫忙。我在軍校學的是機械工程。",
  ui_story_5080_50801202_44_dialog_content = "可是妳連人家的名字都不叫……",
  ui_story_5080_50801202_45_dialog_content = "我也可以幫妳改造車子，妳應該知道我們啟光的技術有多先進。",
  ui_story_5080_50801202_46_dialog_content = "妳想開啟光樣式的公主車嗎？",
  ui_story_5080_50801202_47_dialog_content = "什麼？！太好了，我現在就想看！有設計圖嗎？",
  ui_story_5080_50801202_48_dialog_content = "澤塔？妳……妳沒事？",
  ui_story_5080_50801202_49_dialog_content = "呃……嘿嘿，好像是背上的甜蜜追獵者幫我擋下攻擊，果然澤塔我是天選的主角。",
  ui_story_5080_50801202_50_dialog_content = "澤塔大人，完全復活！",
  ui_story_5080_50801202_51_dialog_content = "妳……",
  ui_story_5080_50801202_52_dialog_content = "這就是荒野之子，勇者澤塔的故事！不會輕易倒下……呃……",
  ui_story_5080_50801202_53_dialog_content = "我不是想騙你們，人家只是想讓弗勞爾背一下嘛。",
  ui_story_5080_50801202_54_dialog_content = "嚇死我了，這個時候怎麼還在胡鬧。真是的……沒事就好。",
  ui_story_5080_50801202_55_dialog_content = "（剛剛發現的時候，也不知道該怎麼說出來，幸好這個玩笑沒持續多久。）",
  ui_story_5080_50801202_56_dialog_content = "澤塔的背確實好痛喔。",
  ui_story_5080_50801202_57_dialog_content = "飛鷹射手，妳的臉好臭，妳不會怪我吧……",
  ui_story_5080_50801202_58_dialog_content = "欸？！妳的臉好黑，一副要黑化的樣子，妳好黑暗，是從恐怖故事裡出來的角色嗎？！",
  ui_story_5080_50801202_59_dialog_content = "不要——",
  ui_story_5080_50801202_60_dialog_content = "嗯？！",
  ui_story_5080_50801202_61_dialog_content = "澤塔……妳沒事……真是太好了。",
  ui_story_5080_50801202_62_dialog_content = "不要隨便摸勇者的頭！嘛，既然向我撒嬌，我也可以滿足妳……咦？",
  ui_story_5080_50801202_63_dialog_content = "妳、妳叫了澤塔的名字？！",
  ui_story_5080_50801202_64_dialog_content = "不要再隨便開玩笑嚇人了……",
  ui_story_5080_50801202_65_dialog_content = "隊長……",
  ui_story_5080_50801202_66_dialog_content = "身為勇者主角，當然不會耍同樣的花招了，嘿嘿。",
  ui_story_5080_50801202_67_dialog_content = "好，既然人沒事，就別在岩漿地帶逗留，繼續走！",
  ui_story_5080_50801202_68_dialog_content = "空裔一號、幼龍二號，不要脫隊！",
  ui_story_5080_50801202_69_dialog_content = "什麼嘛，怎麼還是喊人家的代號……",
  ui_story_5080_50801202_70_dialog_content = "現在就先別計較這個啦，走吧。",
  ui_story_5080_50801202_71_dialog_content = "任務還要繼續，快點！",
  ui_story_5080_50801202_72_dialog_content = "（馬上就換上了冷漠的面具，但現在看起來實在是太違和啦，蕾切爾小姐……）",
  ui_story_5080_50801202_73_dialog_content = "走吧，薇絲，我感覺事情快結束了。",
  ui_story_5080_50801202_74_dialog_content = "快行動！遠離危險地區，唔……",
  ui_story_5080_50801202_75_dialog_content = "怎麼了嗎？",
  ui_story_5080_50801202_76_dialog_content = "什麼也沒有，快走！",
  ui_story_5080_50801202_77_dialog_content = "獵鷹一號，偵察模式帶隊。其他人跟上獵鷹一號！",
  ui_story_5080_50801202_78_dialog_content = "他們的命還在我手裡……我不能……倒下……",
  ui_story_5080_50801301_1_dialog_content = "嘎嗚——！！！",
  ui_story_5080_50801301_2_dialog_content = "牠們，越來越多。",
  ui_story_5080_50801301_3_dialog_content = "充滿惡意，滿心仇恨。",
  ui_story_5080_50801301_4_dialog_content = "耶利亞，快走，我沒問題。",
  ui_story_5080_50801301_5_dialog_content = "那怎麼行，妳眼睛不方便，我不能丟下妳。",
  ui_story_5080_50801301_6_dialog_content = "妳的能力……不適合在這裡戰鬥。",
  ui_story_5080_50801301_7_dialog_content = "再怎麼說，我好歹也是長老。",
  ui_story_5080_50801301_8_dialog_content = "地面，在下沉……我要掉入岩漿了。",
  ui_story_5080_50801301_9_dialog_content = "多恩！往左邊一點，拉住我的手！",
  ui_story_5080_50801301_10_dialog_content = "妳快走，耶利亞。",
  ui_story_5080_50801301_11_dialog_content = "我抓到妳的手了，別放開，多恩。",
  ui_story_5080_50801301_12_dialog_content = "暗鬼，要來了。",
  ui_story_5080_50801301_13_dialog_content = "現在沒時間去考慮這些了。",
  ui_story_5080_50801301_14_dialog_content = "為什麼？耶利亞，妳要好好活著。",
  ui_story_5080_50801301_15_dialog_content = "妳要是死了的話，大家都會傷心的。",
  ui_story_5080_50801301_16_dialog_content = "妳能想像伊芙小妹妹的哭臉嗎？",
  ui_story_5080_50801301_17_dialog_content = "她會湊到妳臉上抱著妳哭的！",
  ui_story_5080_50801301_18_dialog_content = "……",
  ui_story_5080_50801301_19_dialog_content = "那根「風箏線」的力量還真強，這樣就把妳束縛住了。",
  ui_story_5080_50801301_20_dialog_content = "既然人與人的聯繫已經產生，我就不會任由它被輕易斬斷！",
  ui_story_5080_50801301_21_dialog_content = "耶利亞……危險！",
  ui_story_5080_50801301_22_dialog_content = "阿塔爾，我努力過了……",
  ui_story_5080_50801301_23_dialog_content = "<color=#FFB400>速射！</color>",
  ui_story_5080_50801301_24_dialog_content = "趕上了，澤塔，用炸彈擋住牠們！",
  ui_story_5080_50801301_25_dialog_content = "嘿，甜蜜的終極爆彈來囉！",
  ui_story_5080_50801301_26_dialog_content = "耶利亞，我來幫妳！弗勞爾，請幫忙拉起多恩……",
  ui_story_5080_50801301_27_dialog_content = "<color=#FFB400>冰花綻放！</color>",
  ui_story_5080_50801301_28_dialog_content = "「橋」建好了，快上來！",
  ui_story_5080_50801301_29_dialog_content = "卡蓮？還有伊芙？",
  ui_story_5080_50801301_30_dialog_content = "多恩，我來幫忙了！",
  ui_story_5080_50801301_31_dialog_content = "白夜城的小公主，真是幫大忙了呢。",
  ui_story_5080_50801301_32_dialog_content = "不客氣，妳不也是在努力保護自己的牽絆嗎？",
  ui_story_5080_50801301_33_dialog_content = "跟我來，多恩，別放開我的手！",
  ui_story_5080_50801301_34_dialog_content = "耶利亞……手……",
  ui_story_5080_50801301_35_dialog_content = "終於會合了。卡蓮，你們沒事吧？",
  ui_story_5080_50801301_36_dialog_content = "沒事，但這裡的岩漿太危險了，我們不能在這裡長時間戰鬥。",
  ui_story_5080_50801301_37_dialog_content = "猛禽小姐、小公主，你們快點帶著澤塔離開吧。",
  ui_story_5080_50801301_38_dialog_content = "空裔弟弟，就麻煩你用感應能力帶我們去找醒山了。",
  ui_story_5080_50801301_39_dialog_content = "妳不走？",
  ui_story_5080_50801301_40_dialog_content = "呵呵，事已至此，怎麼可能會拋下他呢？",
  ui_story_5080_50801301_41_dialog_content = "澤塔不走！澤塔也要去救狂戰士！",
  ui_story_5080_50801301_42_dialog_content = "我也不能一走了之。",
  ui_story_5080_50801301_43_dialog_content = "你們啊，怎麼這時候也頑固起來了。",
  ui_story_5080_50801301_44_dialog_content = "那就繼續深入吧。",
  ui_story_5080_50801301_45_dialog_content = "隊長？",
  ui_story_5080_50801301_46_dialog_content = "任務還要繼續，我們必須收集更多資訊……也順便救出那個紅油首領。",
  ui_story_5080_50801301_47_dialog_content = "「紅油技師」，妳的工具借一下。幼龍二號，把妳的武器給我。",
  ui_story_5080_50801301_48_dialog_content = "咦？我嗎？",
  ui_story_5080_50801301_49_dialog_content = "好了，我改進了妳的武器。雖然可能還不太習慣，但現在妳受了傷，應該比較適合這個。",
  ui_story_5080_50801301_50_dialog_content = "獵鷹一二三號，回來！",
  ui_story_5080_50801301_51_dialog_content = "……獵鷹一號和三號受損了，接下來換獵鷹二號打頭陣。",
  ui_story_5080_50801301_52_dialog_content = "準備好，繼續任務。",
  ui_story_5080_50801301_53_dialog_content = "手感變好了，弓弦感覺更輕盈了……",
  ui_story_5080_50801301_54_dialog_content = "隊長她有觀察到我的使用習慣。她明明有這份溫柔，為什麼還是刻意疏遠我們。",
  ui_story_5080_50801301_55_dialog_content = "身為隊長，既要完成任務，又要保住隊友的生命。",
  ui_story_5080_50801301_56_dialog_content = "減少隊員對自身的好感，以免他人因自己受傷，這可能是她最後想出來的辦法了。",
  ui_story_5080_50801301_57_dialog_content = "我能理解，她身上背負著怎樣的重量。",
  ui_story_5080_50801301_58_dialog_content = "醒山——",
  ui_story_5080_50801301_59_dialog_content = "你這笨蛋——聽得到嗎？",
  ui_story_5080_50801301_60_dialog_content = "小醒山？！快回答我們！",
  ui_story_5080_50801301_61_dialog_content = "羅伊，妳看底下！岩漿旁邊那點空地，是不是醒山的紅頭髮？",
  ui_story_5080_50801301_62_dialog_content = "不管是不是，我要下去看看！",
  ui_story_5080_50801301_63_dialog_content = "喂！那可是岩漿，你怎麼就這樣跳下去！喂！",
  ui_story_5080_50801301_64_dialog_content = "不管了，本大爺可是要超越醒山的人，怎麼可能在這個時候退縮！",
  ui_story_5080_50801301_65_dialog_content = "我跳！",
  ui_story_5080_50801301_66_dialog_content = "嗚哇啊啊啊啊啊啊啊——",
  ui_story_5080_50801301_67_dialog_content = "到處都是岩漿！！！",
  ui_story_5080_50801301_68_dialog_content = "快閃開，快閃開！",
  ui_story_5080_50801301_69_dialog_content = "<color=#e8d9bb>咚碰！</color>",
  ui_story_5080_50801301_70_dialog_content = "大叔我要被你砸死了……",
  ui_story_5080_50801301_71_dialog_content = "你看，是醒山！真的是醒山！他還活著！",
  ui_story_5080_50801301_72_dialog_content = "小醒山，你——",
  ui_story_5080_50801301_73_dialog_content = "這裡……全都是暗鬼屍體，這都是他一個人幹掉的嗎？",
  ui_story_5080_50801301_74_dialog_content = "從上面摔下來，受了那麼重的傷，居然還幹掉這麼多暗鬼。",
  ui_story_5080_50801301_75_dialog_content = "喲，你們來了……我剛剛掐死這隻大塊頭……",
  ui_story_5080_50801301_76_dialog_content = "醒山？！",
  ui_story_5080_50801301_77_dialog_content = "醒山，清醒點。牠已經死了，你快放手，跟我們走！",
  ui_story_5080_50801301_78_dialog_content = "喂？醒山？？？",
  ui_story_5080_50801301_79_dialog_content = "剛剛的那餐沒吃飽……我又餓了……",
  ui_story_5080_50801301_80_dialog_content = "好想回去和大家一起吃飯，吃起來比較香……",
  ui_story_5080_50801301_81_dialog_content = "羅伊呀，我好疲倦……一定是這兩天操心太多了……",
  ui_story_5080_50801301_82_dialog_content = "我們快回去吃慶功宴吧，別讓他們等太久……",
  ui_story_5080_50801301_83_dialog_content = "他這是怎麼了？你快看看，別讓他就這樣出事！",
  ui_story_5080_50801301_84_dialog_content = "……他沒事，只是一時太賣力，累到睡著了而已。",
  ui_story_5080_50801301_85_dialog_content = "昨晚他顧著出去找人，回來也沒怎麼吃，真是辛苦他了。",
  ui_story_5080_50801301_86_dialog_content = "哼，我就知道這傢伙沒那麼脆弱。",
  ui_story_5080_50801301_87_dialog_content = "他可是還要被本大爺打倒的！",
  ui_story_5080_50801301_88_dialog_content = "來，把他放到本大爺背上。",
  ui_story_5080_50801301_89_dialog_content = "等他醒過來，發現自己還得依靠我，一定會非常羞愧！",
  ui_story_5080_50801301_90_dialog_content = "那就拜託你了。大叔我來帶路，我們快點回到上面去——",
  ui_story_5080_50801301_91_dialog_content = "他的扳手呢？",
  ui_story_5080_50801301_92_dialog_content = "或許是摔下來的時候不知道掉去哪了……我得找找……",
  ui_story_5080_50801301_93_dialog_content = "<color=#e8d9bb>咚！</color>",
  ui_story_5080_50801301_94_dialog_content = "你有聽到嗎？",
  ui_story_5080_50801301_95_dialog_content = "那是岩漿的聲音嗎？",
  ui_story_5080_50801301_96_dialog_content = "<color=#e8d9bb>咚咚！</color>",
  ui_story_5080_50801301_97_dialog_content = "又來了！",
  ui_story_5080_50801301_98_dialog_content = "……那是腳步聲！黑潮，快跑！",
  ui_story_5080_50801301_99_dialog_content = "<color=#e8d9bb>咚咚咚！</color>",
  ui_story_5080_50801301_100_dialog_content = "快跑！！！",
  ui_story_5080_50801302_1_dialog_content = "救命啊嗷嗷嗷嗷——！！！",
  ui_story_5080_50801302_2_dialog_content = "誰？",
  ui_story_5080_50801302_3_dialog_content = "是誰？",
  ui_story_5080_50801302_4_dialog_content = "哇！是啟光的那個隊長！羅伊，快來這邊！！！",
  ui_story_5080_50801302_5_dialog_content = "這是發生了什麼事？",
  ui_story_5080_50801302_6_dialog_content = "<size=45><color=#e8d9bb>咚咚咚咚咚咚咚咚咚咚咚咚咚咚！</color></size>",
  ui_story_5080_50801302_7_dialog_content = "<color=#e8d9bb>吼——</color>",
  ui_story_5080_50801302_8_dialog_content = "暗鬼？！不……是<color=#FFB400>目標</color>！",
  ui_story_5080_50801302_9_dialog_content = "啟光的小姑娘，多謝幫忙了。",
  ui_story_5080_50801302_10_dialog_content = "火力壓制交給我，你們快跑，其他人就在後面！",
  ui_story_5080_50801302_11_dialog_content = "快，羅伊，我們——",
  ui_story_5080_50801302_12_dialog_content = "小心！",
  ui_story_5080_50801302_13_dialog_content = "吼——",
  ui_story_5080_50801302_14_dialog_content = "真是個狡猾的傢伙，寧願被不停射擊也要來把路給堵住。",
  ui_story_5080_50801302_15_dialog_content = "那是什麼？那隻暗鬼把路給堵住了啊。",
  ui_story_5080_50801302_16_dialog_content = "那傢伙……就是牠嗎？就是牠殺了阿塔爾……",
  ui_story_5080_50801302_17_dialog_content = "讓伊芙來！",
  ui_story_5080_50801302_18_dialog_content = "<color=#FFB400>龍捲！</color>",
  ui_story_5080_50801302_19_dialog_content = "<color=#e8d9bb>天花板被雷電炸開，砸倒了那隻暗鬼；但狂暴的力量也引起火山咆哮，地震再起。</color>",
  ui_story_5080_50801302_20_dialog_content = "這個力量感……糟糕，火山就要噴發了！",
  ui_story_5080_50801302_21_dialog_content = "「紅油的小姑娘」，繼續攻擊！",
  ui_story_5080_50801302_22_dialog_content = "但那樣的話，火山可能就會爆發。",
  ui_story_5080_50801302_23_dialog_content = "牠已經被喚醒了，要是讓牠離開這裡，危害更大！",
  ui_story_5080_50801302_24_dialog_content = "明明打中牠了，卻好像完全沒有造成傷害，牠的弱點在哪？",
  ui_story_5080_50801302_25_dialog_content = "「獵鷹」都探測過了，牠的外殼部分並沒有達到岩漿的溫度。",
  ui_story_5080_50801302_26_dialog_content = "而且，任何生命進食之時，往往是最沒有防備的姿態。",
  ui_story_5080_50801302_27_dialog_content = "如果能把牠外殼撲滅，牠或許就得去吸取力量。那個時候，牠就會暴露弱點！",
  ui_story_5080_50801302_28_dialog_content = "當年的牠明明更大隻……躲在這下面安逸十幾年，怎麼變小了……",
  ui_story_5080_50801302_29_dialog_content = "<color=#FFB400>死亡測繪！</color>",
  ui_story_5080_50801302_30_dialog_content = "<color=#FFB400>龍捲！</color>",
  ui_story_5080_50801302_31_dialog_content = "<color=#FFB400>速射！</color>",
  ui_story_5080_50801302_32_dialog_content = "<color=#FFB400>冰花綻放！</color>",
  ui_story_5080_50801302_33_dialog_content = "吼——！！！",
  ui_story_5080_50801302_34_dialog_content = "牠受傷了，我們的攻擊有效！",
  ui_story_5080_50801302_35_dialog_content = "<color=#e8d9bb>碰！！！</color>",
  ui_story_5080_50801302_36_dialog_content = "糟糕，牆壁破了，岩漿跑進來了！",
  ui_story_5080_50801302_37_dialog_content = "小心，牠可能會吸取岩漿能量！",
  ui_story_5080_50801302_38_dialog_content = "黑潮，背著醒山往上跑。伊芙，妳也小心！",
  ui_story_5080_50801302_39_dialog_content = "哇啊啊啊啊——我的機器人著火了！",
  ui_story_5080_50801302_40_dialog_content = "澤塔，我們會妨礙他們的，跟我先撤！",
  ui_story_5080_50801302_41_dialog_content = "可是，救世主勇者不能在這個時候退場啊！",
  ui_story_5080_50801302_42_dialog_content = "聽話，澤塔，妳也不想讓大叔我為妳擔心吧？",
  ui_story_5080_50801302_43_dialog_content = "嘎嗚——",
  ui_story_5080_50801302_44_dialog_content = "暗鬼都從巢裡跑出來了！",
  ui_story_5080_50801302_45_dialog_content = "既然大叔都這麼說……多恩，我掩護妳出去，我們去集結新的夥伴！",
  ui_story_5080_50801302_46_dialog_content = "別想傷害我哥哥！",
  ui_story_5080_50801302_47_dialog_content = "伊芙後退，耶利亞，你們也……",
  ui_story_5080_50801302_48_dialog_content = "我來牽制牠，你們快帶醒山離開！",
  ui_story_5080_50801302_49_dialog_content = "耶利亞？",
  ui_story_5080_50801302_50_dialog_content = "如果牠真的是殺害阿塔爾的傢伙……我怎麼可能放過牠！",
  ui_story_5080_50801302_51_dialog_content = "明明岩漿湧進來了，牠卻沒有吸取岩漿……為什麼？",
  ui_story_5080_50801302_52_dialog_content = "牠甚至……在躲避那些岩漿？",
  ui_story_5080_50801302_53_dialog_content = "等等，薇絲，妳的位置太危險了，靠近我！",
  ui_story_5080_50801302_54_dialog_content = "卡蓮，用妳的力量，製造落腳點到牠頭上去！",
  ui_story_5080_50801302_55_dialog_content = "我來掩護妳，快上！",
  ui_story_5080_50801302_56_dialog_content = "<color=#FFB400>眾言靈啊！</color>",
  ui_story_5080_50801302_57_dialog_content = "吼——！！！",
  ui_story_5080_50801302_58_dialog_content = "牠的動作變慢了？我也來幫忙！",
  ui_story_5080_50801302_59_option_content = "強制感應！",
  ui_story_5080_50801302_60_dialog_content = "膽敢摧折飛鳥之翼的狂徒，付出代價吧！",
  ui_story_5080_50801302_61_dialog_content = "就是現在，妳還行嗎？小公主？！",
  ui_story_5080_50801302_62_dialog_content = "<color=#FFB400>冰花綻放！</color>",
  ui_story_5080_50801302_63_dialog_content = "牠的岩漿外殼溫度太高了，傷害還不夠……",
  ui_story_5080_50801302_64_dialog_content = "有效果了，必須趁現在繼續攻擊……",
  ui_story_5080_50801302_65_dialog_content = "獵鷹一號、獵鷹三號，對不起了——",
  ui_story_5080_50801302_66_dialog_content = "<color=#FFB400>自爆攻擊！</color>",
  ui_story_5080_50801302_67_dialog_content = "吼——！！！",
  ui_story_5080_50801302_68_dialog_content = "（糟了，牠現在身上的岩漿能量太強，不管什麼攻擊都會被抵消。）",
  ui_story_5080_50801302_69_dialog_content = "牠掙脫我的控制了……你們小心！",
  ui_story_5080_50801302_70_dialog_content = "（腦袋……好痛……）",
  ui_story_5080_50801302_71_dialog_content = "喂，洞窟要塌了，你們幾個快點上來啊！",
  ui_story_5080_50801302_72_dialog_content = "<color=#e8d9bb>碰！！！</color>",
  ui_story_5080_50801302_73_dialog_content = "越來越熱了，這樣下去——",
  ui_story_5080_50801302_74_dialog_content = "我接住小公主了，快帶她走！",
  ui_story_5080_50801302_75_dialog_content = "糟糕，卡蓮和耶利亞被困住了！",
  ui_story_5080_50801302_76_dialog_content = "雖然有點慢，但我會製造一條路，你們自己小心！",
  ui_story_5080_50801302_77_dialog_content = "怎麼會這樣？明明都偵測過了……牠的能量為什麼還是這麼磅礴？",
  ui_story_5080_50801302_78_dialog_content = "難道我誤判了？",
  ui_story_5080_50801302_79_dialog_content = "在戰鬥之中，牠依然能不斷補充力量嗎？",
  ui_story_5080_50801302_80_dialog_content = "岩漿過來了，隊長快走！",
  ui_story_5080_50801302_81_dialog_content = "你們走！我要承擔責任，掩護你們撤退！",
  ui_story_5080_50801302_82_dialog_content = "來吧！",
  ui_story_5080_50801302_83_dialog_content = "<color=#FFB400>速射！</color>",
  ui_story_5080_50801302_84_dialog_content = "來我這邊才對！",
  ui_story_5080_50801302_85_dialog_content = "吼——！！！",
  ui_story_5080_50801302_86_dialog_content = "幼龍二號！",
  ui_story_5080_50801302_87_dialog_content = "別想再傷害薇絲！！！",
  ui_story_5080_50801302_88_option_content = "強制感應！",
  ui_story_5080_50801302_89_dialog_content = "幼龍二號，妳沒事吧？快醒醒！",
  ui_story_5080_50801302_90_dialog_content = "（最講效率的那個人，為了薇絲放棄了攻擊機會……）",
  ui_story_5080_50801302_91_dialog_content = "可是……為什麼到這個時候我卻很開心……雖然頭好痛……",
  ui_story_5080_50801302_92_dialog_content = "管不了那麼多了，伊芙，你們走吧！",
  ui_story_5080_50801302_93_dialog_content = "我來了！",
  ui_story_5080_50801302_94_dialog_content = "<color=#FFB400>艾倫拳！</color>",
  ui_story_5080_50801302_95_dialog_content = "小公主，橋的平穩就交給妳了！",
  ui_story_5080_50801302_96_dialog_content = "<color=#FFB400>龍捲！</color>",
  ui_story_5080_50801302_97_dialog_content = "成功了！我從這麼遠的地方打中牠了。",
  ui_story_5080_50801302_98_dialog_content = "太熱了，從這個高度大叔我完全看不到牠怎麼樣了。",
  ui_story_5080_50801302_99_dialog_content = "吼——！！！",
  ui_story_5080_50801302_100_dialog_content = "牠要逃了。",
  ui_story_5080_50801302_101_dialog_content = "別想逃！",
  ui_story_5080_50801302_102_dialog_content = "別追，耶利亞！我們腳下要被岩漿吞沒了！",
  ui_story_5080_50801302_103_dialog_content = "……大家……別害怕，我來了。",
  ui_story_5080_50801302_104_dialog_content = "言靈們找到脆弱的牆壁了，走這邊。",
  ui_story_5080_50801302_105_dialog_content = "呼……呼……「冰之橋」，展開吧……",
  ui_story_5080_50801302_106_dialog_content = "我現在只能維持這樣的力量了。",
  ui_story_5080_50801302_107_dialog_content = "我背上幼龍二號了……大家，快離開這裡。",
  ui_story_5080_50801401_1_dialog_content = "<color=#FFB400>冰花綻放！</color>",
  ui_story_5080_50801401_2_dialog_content = "竟然沒有被炸開？",
  ui_story_5080_50801401_3_dialog_content = "這牆體的溫度太高了，妳是很難強行突破的。",
  ui_story_5080_50801401_4_dialog_content = "都怪我……獵鷹一號和三號都白白炸毀了。",
  ui_story_5080_50801401_5_dialog_content = "這裡溫度太高，我也不敢隨便攜帶爆炸物……",
  ui_story_5080_50801401_6_dialog_content = "給我點時間，我來計算精準爆破。",
  ui_story_5080_50801401_7_dialog_content = "喂，羅伊，你看到沒有，他們被困在那個通道裡了。",
  ui_story_5080_50801401_8_dialog_content = "從我這個角度，沒辦法打到……",
  ui_story_5080_50801401_9_dialog_content = "住手，小伊芙，妳的力量範圍太大了！",
  ui_story_5080_50801401_10_dialog_content = "咱們只有醒山能夠做到——我要把他弄醒！",
  ui_story_5080_50801401_11_dialog_content = "羅伊，把乾糧都拿出來！",
  ui_story_5080_50801401_12_dialog_content = "欸？你想對哥哥做什麼……？",
  ui_story_5080_50801401_13_dialog_content = "哇哇哇——那還用說，當然是把食物全給他塞進去。",
  ui_story_5080_50801401_14_dialog_content = "咕咕咕咕咕咕嗚——",
  ui_story_5080_50801401_15_dialog_content = "住手，你想噎死醒山嗎？",
  ui_story_5080_50801401_16_dialog_content = "<size=45>快住手啊！！！</size>",
  ui_story_5080_50801401_17_dialog_content = "薇絲……薇絲……別嚇我……",
  ui_story_5080_50801401_18_dialog_content = "幼龍二號、幼龍二號，快醒醒。",
  ui_story_5080_50801401_19_dialog_content = "獵鷹二號，馬上開啟急救模式，電擊等級二，準備充能！",
  ui_story_5080_50801401_20_dialog_content = "<color=#FFB400>電擊！</color>",
  ui_story_5080_50801401_21_dialog_content = "唔——",
  ui_story_5080_50801401_22_dialog_content = "太好了，妳沒事……",
  ui_story_5080_50801401_23_dialog_content = "幼龍二號！妳有聽到我的聲音嗎？別擔心，我會帶妳出去……",
  ui_story_5080_50801401_24_dialog_content = "隊長……",
  ui_story_5080_50801401_25_dialog_content = "幼龍二號？幼龍二號？",
  ui_story_5080_50801401_26_dialog_content = "……夠了，蕾切爾！",
  ui_story_5080_50801401_27_dialog_content = "想要「喚醒」一個人的心，至少請妳喊她的名字！",
  ui_story_5080_50801401_28_dialog_content = "請妳喊她的名字啊！她才不是什麼幼龍二號，她有名字，她就叫薇絲！",
  ui_story_5080_50801401_29_dialog_content = "空裔一號……",
  ui_story_5080_50801401_30_dialog_content = "我怎麼樣都無所謂，但是薇絲不一樣……",
  ui_story_5080_50801401_31_dialog_content = "她是那麼崇拜妳，尊敬妳，一聽到能和妳組隊，她就開心得不得了。",
  ui_story_5080_50801401_32_dialog_content = "但直到現在，妳連她的名字都沒有喊過！",
  ui_story_5080_50801401_33_dialog_content = "……",
  ui_story_5080_50801401_34_dialog_content = "她叫薇絲！她會為了妳，一個人熬夜寫任務結報，明明累到不行，眼神卻還是那麼興奮……",
  ui_story_5080_50801401_35_dialog_content = "明明妳都沒喊過她的名字，但對她來說，能跟前輩說上話就很開心了！",
  ui_story_5080_50801401_36_dialog_content = "薇絲是那麼喜歡長官，期待得到表揚。她什麼也沒做錯，只是名字而已，妳到底在害怕什麼……",
  ui_story_5080_50801401_37_dialog_content = "求求妳，至少……至少在這個時候請喊她的名字吧……",
  ui_story_5080_50801401_38_dialog_content = "我……絕不能再和人產生多餘的感情……",
  ui_story_5080_50801401_39_dialog_content = "猛禽小姐……",
  ui_story_5080_50801401_40_dialog_content = "現在我們已經偏離任務了……我不能……不能再連累別人了……",
  ui_story_5080_50801401_41_dialog_content = "……對不起，她已經做得很好了。這一切是我的錯……",
  ui_story_5080_50801401_42_dialog_content = "我害怕再成為累贅……我不想再有人因為我死去了……",
  ui_story_5080_50801401_43_dialog_content = "如果又產生了新的牽絆……又會有夥伴因為我的指揮而死……我……不能接受……",
  ui_story_5080_50801401_44_dialog_content = "不對！現在我不是在追究責任！",
  ui_story_5080_50801401_45_dialog_content = "明明妳一直藏著自己的溫柔，明明妳也很關心每個人，為什麼非要藏起來？",
  ui_story_5080_50801401_46_dialog_content = "因為妳對別人付出了真心，才會有人不惜生命也想保護妳。",
  ui_story_5080_50801401_47_dialog_content = "這怎麼會是多餘的感情……",
  ui_story_5080_50801401_48_dialog_content = "空裔一號，你是不會明白的……",
  ui_story_5080_50801401_49_dialog_content = "我怎麼會不明白？！眼睜睜看著他人為我犧牲，而我卻無能為力，我怎麼會不明白？！",
  ui_story_5080_50801401_50_dialog_content = "我失去了所有的族人，好不容易找到的朋友，也因為我才……",
  ui_story_5080_50801401_51_dialog_content = "那種失去他人的痛苦，那種孤獨的自責，我明白的啊……蕾切爾。",
  ui_story_5080_50801401_52_dialog_content = "我由衷感謝幫助過我的每個人。因為他們的支撐，我和薇絲、和夥伴們才能走下去。",
  ui_story_5080_50801401_53_dialog_content = "我不認為這是多餘的聯繫。",
  ui_story_5080_50801401_54_dialog_content = "能夠和大家相見，真是太好了……如果可以的話，我還想呼喚他們的名字，和他們再說說話。",
  ui_story_5080_50801401_55_dialog_content = "PlayerName……",
  ui_story_5080_50801401_56_dialog_content = "別說了……空裔一號……",
  ui_story_5080_50801401_57_dialog_content = "人是因為懷抱著深深的「愛」，才會為他人犧牲。",
  ui_story_5080_50801401_58_dialog_content = "那些掩護妳的夥伴們，還有薇絲，才不是為了任務！",
  ui_story_5080_50801401_59_dialog_content = "他們只是想保護妳……而蕾切爾好好活了下來，這一定比什麼都讓他們開心。",
  ui_story_5080_50801401_60_dialog_content = "就像那位自由鳥的隊長一樣……她一定也是心懷著對隊員的愛，才會不惜聲名狼藉，也要帶她們回來。",
  ui_story_5080_50801401_61_dialog_content = "付出犧牲，只是想保護身後的人……",
  ui_story_5080_50801401_62_dialog_content = "對於好不容易能夠互相理解的大家來說，這樣的理由不就夠了嗎……",
  ui_story_5080_50801401_63_dialog_content = "不要再說下去了……我……",
  ui_story_5080_50801401_64_dialog_content = "蕾切爾心裡也明白才對……明明妳也常為了我們奮不顧身……",
  ui_story_5080_50801401_65_dialog_content = "難道真的是因為，這樣更有效率嗎？",
  ui_story_5080_50801401_66_dialog_content = "妳只是害怕有人受傷……所以妳才努力想保護所有人……",
  ui_story_5080_50801401_67_dialog_content = "那樣的話……為什麼還要抗拒和他人產生聯繫……",
  ui_story_5080_50801401_68_dialog_content = "PlayerName……別哭……你已經力量透支了……",
  ui_story_5080_50801401_69_dialog_content = "……要準備爆破了，稍微再等等。",
  ui_story_5080_50801401_70_dialog_content = "猛禽小姐……不，蕾切爾。",
  ui_story_5080_50801401_71_dialog_content = "沙漠上時常會有旅鳥飛過……但牠們哪怕落單，總有一天也會回到鳥群。",
  ui_story_5080_50801401_72_dialog_content = "我……過去時並不理解。但現在我能明白，即使成為猛禽，也還是會有夥伴。",
  ui_story_5080_50801401_73_dialog_content = "我……我……我不需要夥伴……",
  ui_story_5080_50801401_74_dialog_content = "妳這……頑固的……",
  ui_story_5080_50801401_75_dialog_content = "<color=#e8d9bb>碰！！！</color>",
  ui_story_5080_50801401_76_dialog_content = "怎麼回事？哪裡爆炸了嗎？",
  ui_story_5080_50801401_77_dialog_content = "吼——！！！",
  ui_story_5080_50801401_78_dialog_content = "危險！",
  ui_story_5080_50801401_79_dialog_content = "蕾切爾！我來幫妳！",
  ui_story_5080_50801401_80_dialog_content = "吼——！！！",
  ui_story_5080_50801401_81_dialog_content = "糟糕，牠在攻擊地板。",
  ui_story_5080_50801401_82_dialog_content = "言靈們，把小公主送上去！",
  ui_story_5080_50801401_83_dialog_content = "<color=#e8d9bb>碰！！！</color>",
  ui_story_5080_50801401_84_dialog_content = "牆炸開了！跟我來！",
  ui_story_5080_50801401_85_dialog_content = "PlayerName他們還在下面！",
  ui_story_5080_50801401_86_dialog_content = "吼——！！！",
  ui_story_5080_50801401_87_dialog_content = "休想……再傷害我的夥伴！",
  ui_story_5080_50801401_88_dialog_content = "PlayerName！和卡蓮她們離開這裡！",
  ui_story_5080_50801401_89_dialog_content = "蕾切爾……妳……終於坦率了……",
  ui_story_5080_50801401_90_dialog_content = "或許真的是身體更誠實吧……PlayerName，在幫你擋下攻擊的瞬間……",
  ui_story_5080_50801401_91_dialog_content = "我不知道該怎麼嘴硬了。",
  ui_story_5080_50801401_92_dialog_content = "所以……快走。",
  ui_story_5080_50801401_93_dialog_content = "岩漿要來了，空裔弟弟，快抓住我的手！",
  ui_story_5080_50801401_94_dialog_content = "梅麗、路易、莉娜、塔爾斯……夥伴們，再賜予我一些力量。",
  ui_story_5080_50801401_95_dialog_content = "讓我的朋友逃離吧！",
  ui_story_5080_50801401_96_dialog_content = "不……我不會逃走的……",
  ui_story_5080_50801401_97_dialog_content = "PlayerName？！",
  ui_story_5080_50801401_98_dialog_content = "我說過，我感謝所有幫助過我的人……我無比珍惜這些聯繫……",
  ui_story_5080_50801401_99_dialog_content = "所以我不會放棄任何夥伴，蕾切爾。",
  ui_story_5080_50801401_100_dialog_content = "……你，真是個完全不聽指揮的士兵。",
  ui_story_5080_50801401_101_dialog_content = "但是，PlayerName，我很高興……",
  ui_story_5080_50801401_102_dialog_content = "我很榮幸能和你們組隊。",
  ui_story_5080_50801401_103_dialog_content = "一起上吧。",
  ui_story_5080_50801401_104_dialog_content = "卡蓮，請妳用最後的力量，加強我們腳下的地面！",
  ui_story_5080_50801401_105_dialog_content = "耶利亞，言靈們應該能撐住正在崩塌的牆面吧？",
  ui_story_5080_50801401_106_dialog_content = "弗勞爾，對牠的直接攻擊就有勞你了。",
  ui_story_5080_50801401_107_dialog_content = "讓我們並肩作戰吧。",
  ui_story_5080_50801402_1_dialog_content = "岩漿越來越洶湧了，<color=#FFB400>冰之路</color>要……要斷裂了！",
  ui_story_5080_50801402_2_dialog_content = "就差一點點，牠身上的「盔甲」快沒能量了！",
  ui_story_5080_50801402_3_dialog_content = "糟糕！PlayerName，蕾切爾！",
  ui_story_5080_50801402_4_dialog_content = "（糟了……岩漿把路都衝斷了，大家被隔開了……）",
  ui_story_5080_50801402_5_dialog_content = "別管我們……我消耗過度了……你們快從弗勞爾打出來的洞離開……",
  ui_story_5080_50801402_6_dialog_content = "說什麼傻話？撐住，我們現在就過去。",
  ui_story_5080_50801402_7_dialog_content = "偏偏是在這種地方，想再次製造冰橋……太難了……",
  ui_story_5080_50801402_8_dialog_content = "<size=40>吼！！！</size>",
  ui_story_5080_50801402_9_dialog_content = "我不會讓開的，怪物……就算只剩這把手槍……",
  ui_story_5080_50801402_10_dialog_content = "<color=#e8d9bb>砰——砰——砰——</color>",
  ui_story_5080_50801402_11_dialog_content = "<color=#e8d9bb>蕾切爾的子彈一顆顆打在暗鬼身上，但都被對方那最後的熱量擋下。</color>",
  ui_story_5080_50801402_12_dialog_content = "<color=#e8d9bb>咔——</color>",
  ui_story_5080_50801402_13_dialog_content = "子彈……空了……",
  ui_story_5080_50801402_14_dialog_content = "武器沒了，我還有拳頭。",
  ui_story_5080_50801402_15_dialog_content = "PlayerName，躲在我身後，一點也別動！",
  ui_story_5080_50801402_16_dialog_content = "蕾切爾……妳快走……我動不了了……",
  ui_story_5080_50801402_17_dialog_content = "我……絕對不會放棄！",
  ui_story_5080_50801402_18_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_5080_50801402_19_dialog_content = "又是岩漿爆發，這座火山看起來就快……等等，那是什麼？！",
  ui_story_5080_50801402_20_dialog_content = "扳手……醒山的扳手？！怎麼會在這個地方？",
  ui_story_5080_50801402_21_dialog_content = "來得正好。",
  ui_story_5080_50801402_22_dialog_content = "住手，蕾切爾，那把扳手太重了，別勉強！",
  ui_story_5080_50801402_23_dialog_content = "呼——呼——我們回來了……啊！",
  ui_story_5080_50801402_24_dialog_content = "等等，那傢伙在舉醒山的扳手，太逞強了啊！",
  ui_story_5080_50801402_25_dialog_content = "我……哈……最不喜歡隊員逞強……",
  ui_story_5080_50801402_26_dialog_content = "也最喜歡自己逞強了。",
  ui_story_5080_50801402_27_dialog_content = "吼！！！",
  ui_story_5080_50801402_28_dialog_content = "休想傷害我的隊員！",
  ui_story_5080_50801402_29_dialog_content = "嗷嗚——！！！",
  ui_story_5080_50801402_30_dialog_content = "怎麼可能？除了醒山之外，居然還有人揮得動那扳手……",
  ui_story_5080_50801402_31_dialog_content = "嗚……嗚……吼！！！",
  ui_story_5080_50801402_32_dialog_content = "牠還沒死？！",
  ui_story_5080_50801402_33_dialog_content = "那就……再來一次……",
  ui_story_5080_50801402_34_dialog_content = "（不行……我能感應到，蕾切爾的身體已經到極限了……太勉強了……明明就差一點點……）",
  ui_story_5080_50801402_35_dialog_content = "我……絕對不會放棄……再來！",
  ui_story_5080_50801402_36_dialog_content = "吼！！！",
  ui_story_5080_50801402_37_dialog_content = "冰橋……快一點！",
  ui_story_5080_50801402_38_dialog_content = "她沒有力氣了……這樣下去……她們兩個都會……",
  ui_story_5080_50801402_39_dialog_content = "嗷嗷嗷地吵死人了！完全不讓人休息嗎？",
  ui_story_5080_50801402_40_dialog_content = "你……醒山？！",
  ui_story_5080_50801402_41_dialog_content = "喲，小姑娘，妳的精神還真亮眼。",
  ui_story_5080_50801402_42_dialog_content = "能夠舉起這把扳手，表示妳有「力量」。",
  ui_story_5080_50801402_43_dialog_content = "能為了守護他人使用這「力量」，代表妳有更閃亮的「意志」。",
  ui_story_5080_50801402_44_dialog_content = "來吧！為了妳心中的<color=#FFB400>大義</color>，揮動<color=#FFB400>無上力量</color>！",
  ui_story_5080_50801402_45_dialog_content = "<size=45>喝啊啊啊——！！！</size>",
  ui_story_5080_50801402_46_dialog_content = "<color=#e8d9bb>砰！</color>",
  ui_story_5080_50801402_47_dialog_content = "來自截然不同世界的人，為了守護的心舉起那扳手……",
  ui_story_5080_50801402_48_dialog_content = "那兩道背影……",
  ui_story_5080_50801402_49_dialog_content = "別想傷害她們！",
  ui_story_5080_50801402_50_dialog_content = "你休想越過我！",
  ui_story_5080_50801402_51_dialog_content = "哪怕是一開始無法理解妳的那個人，此時此刻，也舉起了那把扳手——",
  ui_story_5080_50801402_52_dialog_content = "呵……你們的意志延續至此……阿塔爾……",
  ui_story_5080_50801402_53_dialog_content = "那就是……<color=#FFB400>「紅油扳手」</color>。",
  ui_story_5080_50801402_54_dialog_content = "終於解決了……岩漿要來了喔，快走。",
  ui_story_5080_50801402_55_dialog_content = "最後的冰橋搭上了，走。",
  ui_story_5080_50801402_56_dialog_content = "喂——！這裡這裡！",
  ui_story_5080_50801402_57_dialog_content = "來這裡，我用鉤索連到上面了，我們可以爬出去！",
  ui_story_5080_50801402_58_dialog_content = "PlayerName……我們走……唔！",
  ui_story_5080_50801402_59_dialog_content = "喂喂，妳沒事吧？帶著一身傷逞強過頭，妳完全脫力了！",
  ui_story_5080_50801402_60_dialog_content = "沒辦法，「紅油賊頭」的手，妳要搭一把嗎？",
  ui_story_5080_50801402_61_dialog_content = "……",
  ui_story_5080_50801402_62_dialog_content = "啊喂！",
  ui_story_5080_50801402_63_dialog_content = "<color=#e8d9bb>一顆石頭擦著兩人墜落，掉入岩漿裡。</color>",
  ui_story_5080_50801402_64_dialog_content = "……誰說我……站不起來了。「啟光軍蟻」的手，你想搭一把嗎？",
  ui_story_5080_50801402_65_dialog_content = "哈哈哈哈哈——妳比裝出來的樣子可愛多了嘛。",
  ui_story_5080_50801402_66_dialog_content = "這點程度的石頭奈何不了我……不過，能不被伊芙擔心傷口也好。",
  ui_story_5080_50801402_67_dialog_content = "多謝了啊。",
  ui_story_5080_50801402_68_dialog_content = "對不起……但是誰能拉我一把？我感應能力使用過頭，真的完全沒力氣了……",
  ui_story_5080_50801402_69_dialog_content = "……",
  ui_story_5080_50801402_70_dialog_content = "呵……",
  ui_story_5080_50801402_71_dialog_content = "哈哈哈哈——",
  ui_story_5080_50801402_72_dialog_content = "別顧著笑了，快走快走！",
  ui_story_5080_50801402_73_dialog_content = "<color=#e8d9bb>嘭隆隆——</color>",
  ui_story_5080_50801402_74_dialog_content = "噢呼！終於出來了！新鮮的空氣，怡人的氣溫！",
  ui_story_5080_50801402_75_dialog_content = "啊！你們怎麼這麼快？！",
  ui_story_5080_50801402_76_dialog_content = "看來讓你們兩個先跑是對的，這找路能力還真是……",
  ui_story_5080_50801402_77_dialog_content = "是澤塔帶路的。",
  ui_story_5080_50801402_78_dialog_content = "幹、幹什麼，我是拉力賽的傳奇，爬洞有一點點不足也沒什麼吧！",
  ui_story_5080_50801402_79_dialog_content = "哈哈哈哈哈——",
  ui_story_5080_50801402_80_dialog_content = "喂！狂戰士，不許笑！",
  ui_story_5080_50801402_81_dialog_content = "那當然要笑了，小澤塔。",
  ui_story_5080_50801402_82_dialog_content = "你？！連你也要霸淩本勇者……！",
  ui_story_5080_50801402_83_dialog_content = "我們可以回去趕上宴會啦，真是的！",
  ui_story_5080_50801402_84_dialog_content = "怎麼還在這拖拖拉拉，他們可能先開飯了啊！",
  ui_story_5080_50801402_85_dialog_content = "還有這種事？澤塔在這裡，絕對帶你們快速回去！",
  ui_story_5080_50801402_86_dialog_content = "快上車！",
  ui_story_5080_50801402_87_dialog_content = "喂——約娜——",
  ui_story_5080_50801402_88_dialog_content = "青瞳？",
  ui_story_5080_50801402_89_dialog_content = "哎呀，我難得回來一趟，怎麼這邊怪安靜的。",
  ui_story_5080_50801402_90_dialog_content = "等等！那邊是——",
  ui_story_5080_50801402_91_dialog_content = "<color=#e8d9bb>砰！！！砰砰砰砰砰——！！！</color>",
  ui_story_5080_50801402_92_dialog_content = "<color=#e8d9bb>一個陷阱的爆炸，引發了所有地雷的連鎖反應。才一眨眼，整個營地便面目全非。</color>",
  ui_story_5080_50801402_93_dialog_content = "那邊是地雷區……",
  ui_story_5080_50801402_94_dialog_content = "怎麼了怎麼了？",
  ui_story_5080_50801402_95_dialog_content = "營地怎麼變成這個鬼樣子？呃……晚上的宴會還能舉行嗎？",
  ui_story_5080_50801402_96_dialog_content = "啊啊啊啊啊！！！",
  ui_story_5080_50801402_97_dialog_content = "你們這些笨蛋！！！都幹了什麼好事啊！！！",
  ui_story_5080_50801402_98_dialog_content = "只是小小的計算失誤，老大——！",
  ui_story_5080_50801402_99_dialog_content = "別跑！給我站住，我要好好教訓你們！",
  ui_story_5080_50801402_100_dialog_content = "好啦好啦，先不要顧著打孩子了，咱們還是看看還有什麼能用的菜吧？",
  ui_story_5080_50801402_101_dialog_content = "嗚哇——嗚哇——芭芭拉的、芭芭拉的舞台——",
  ui_story_5080_50801402_102_dialog_content = "別哭別哭！我來看看還能不能修……",
  ui_story_5080_50801402_103_dialog_content = "哼哼，沒想到妳也會有這麼狼狽的一天啊，「魔女」！",
  ui_story_5080_50801402_104_dialog_content = "妳一定不知道，本澤塔大人到底實現了怎樣的壯舉吧？！",
  ui_story_5080_50801402_105_dialog_content = "……哎，算了……能見到妳，大姐姐我很高興。",
  ui_story_5080_50801402_106_dialog_content = "這算什麼啊……",
  ui_story_5080_50801402_107_dialog_content = "真是——",
  ui_story_5080_50801402_108_dialog_content = "喂？蕾切爾！蕾切爾！",
  ui_story_5080_50801402_109_dialog_content = "怎麼了怎麼了？讓大叔看看……",
  ui_story_5080_50801402_110_dialog_content = "喔，沒事，她只是一時太放鬆，昏過去罷了。",
  ui_story_5080_50801402_111_dialog_content = "她的無人機怎麼又壞了？歐緹，看好了，讓妳見識我精湛的維修技術！",
  ui_story_5080_50801402_112_dialog_content = "有我在，怎麼可能輪得到妳——",
  ui_story_5080_50801402_113_dialog_content = "這是……迦南城？",
  ui_story_5080_50801402_114_dialog_content = "我什麼時候回家了……",
  ui_story_5080_50801402_115_dialog_content = "隊長！隊長——",
  ui_story_5080_50801402_116_dialog_content = "是……是你們？",
  ui_story_5080_50801402_117_dialog_content = "白雁……不，梅麗，你們……",
  ui_story_5080_50801402_118_dialog_content = "呀，真是好久不見了……咦？！",
  ui_story_5080_50801402_119_dialog_content = "隊長，妳……妳怎麼哭了？",
  ui_story_5080_50801402_120_dialog_content = "對不起……對不起……我一直都想親口對你們說……",
  ui_story_5080_50801402_121_dialog_content = "我不是個好隊長，我讓你們……讓你們……",
  ui_story_5080_50801402_122_dialog_content = "哈哈哈，沒想到隊長哭起來是這樣啊。",
  ui_story_5080_50801402_123_dialog_content = "還是第一次見到……再也不想見到了。",
  ui_story_5080_50801402_124_dialog_content = "活下來的是隊長妳，真是太好了。",
  ui_story_5080_50801402_125_dialog_content = "我們能夠拯救隊長，真的很高興。",
  ui_story_5080_50801402_126_dialog_content = "而且啊，現在的隊長比以前更厲害了，不是嗎？您保護了所有人呢。",
  ui_story_5080_50801402_127_dialog_content = "果然隊長是最棒的隊長了。",
  ui_story_5080_50801402_128_dialog_content = "大家……",
  ui_story_5080_50801402_129_dialog_content = "能夠遇上隊長真是太好了。",
  ui_story_5080_50801402_130_dialog_content = "在那～麼多的小隊裡，能被隊長挑中，真是太幸福了。",
  ui_story_5080_50801402_131_dialog_content = "所以妳也要幸福才行啊，隊長。",
  ui_story_5080_50801402_132_dialog_content = "你們這是要去哪？回來！聽我說……",
  ui_story_5080_50801402_133_dialog_content = "回去吧，隊長。現在妳要留住的已經不是我們了。",
  ui_story_5080_50801402_134_dialog_content = "請您好好活下去，多笑一笑，那就再好不過了！",
  ui_story_5080_50801402_135_dialog_content = "等等，大家，別走！",
  ui_story_5080_50801402_136_dialog_content = "隊長——",
  ui_story_5080_50801402_137_dialog_content = "等等我！",
  ui_story_5080_50801402_138_dialog_content = "隊長——！",
  ui_story_5080_50801402_139_dialog_content = "妳……",
  ui_story_5080_50801402_140_dialog_content = "薇絲？",
  ui_story_5080_50801402_141_dialog_content = "隊長……？",
  ui_story_5080_50801402_142_dialog_content = "妳沒事……真是太好了。",
  ui_story_5080_50801402_143_dialog_content = "等等！您剛剛……叫了我的名字嗎？",
  ui_story_5080_50801402_144_dialog_content = "嗚哇——隊長！隊長！！！",
  ui_story_5080_50801402_145_dialog_content = "<color=#e8d9bb>喜極而泣的薇絲一把抱住蕾切爾，完全不管對方僵住的反應。</color>",
  ui_story_5080_50801402_146_dialog_content = "（但是……那顆真心，絕對不會得不到回應。）",
  ui_story_5080_50801402_147_dialog_content = "沒事了……都沒事了……",
  ui_story_5080_50801402_148_dialog_content = "謝謝妳，薇絲。",
  ui_story_5080_50801402_149_dialog_content = "謝謝你們。",
  ui_story_5080_50801500_1_dialog_content = "我們為求自保，將那隻暗鬼殺死，但現在地震平息了，火山還是沒有噴發。",
  ui_story_5080_50801500_2_dialog_content = "妳的意思是……還是有某種東西在抑制火山的能量？",
  ui_story_5080_50801500_3_dialog_content = "我也只是猜測。在離開前，言靈們發現……",
  ui_story_5080_50801500_4_dialog_content = "你們將那隻暗鬼砸扁的地方被打穿了，下面還有一層道路。",
  ui_story_5080_50801500_5_dialog_content = "火山內核之中，還有迴廊？",
  ui_story_5080_50801500_6_dialog_content = "但現在下面被岩漿覆蓋，我們可能無法調查了。",
  ui_story_5080_50801500_7_dialog_content = "……羅伊他覺得，那隻暗鬼不是當年的暗鬼。",
  ui_story_5080_50801500_8_dialog_content = "是呢，如果不是地形問題，牠並不算棘手。如果當年真的是牠，阿塔爾不應該會死……",
  ui_story_5080_50801500_9_dialog_content = "看來一切與真正的深層息息相關。",
  ui_story_5080_50801500_10_dialog_content = "我們真正的<color=#FFB400>仇人</color>……很可能藏在那裡。",
  ui_story_5080_50801500_11_dialog_content = "等岩漿冷卻，大家的傷勢恢復，我們再一起去調查吧。",
  ui_story_5080_50801500_12_dialog_content = "紅油扳手睡在這樣的活火山上，應該也不安穩吧？",
  ui_story_5080_50801500_13_dialog_content = "誰知道呢……我們都是一群活在當下的笨蛋，哪會操心那麼多。",
  ui_story_5080_50801500_14_dialog_content = "舞台修好了……忙到現在，真是累死人了啊！！！",
  ui_story_5080_50801500_15_dialog_content = "沒關係，交給我吧！就讓我的熱情，將夜空燃盡——！",
  ui_story_5080_50801500_16_dialog_content = "蛤？妳是澤塔？！妳、妳……",
  ui_story_5080_50801500_17_dialog_content = "妳怎麼化妝畫成這個鬼樣子？",
  ui_story_5080_50801500_18_dialog_content = "欸？這可是魔女說要幫澤塔變成成熟大人的啊？！",
  ui_story_5080_50801500_19_dialog_content = "難道說……可惡的魔女！！！",
  ui_story_5080_50801500_20_dialog_content = "別跑，不是說好要幫我伴舞嗎？我們就要上去和那傢伙打擂台了啊！",
  ui_story_5080_50801500_21_dialog_content = "黑潮，你也看到了吧？大家都餓著呢。",
  ui_story_5080_50801500_22_dialog_content = "現在洗菜第一快的人，無疑是解決混亂的大功臣，大家一定會非常～非常～尊敬他的！",
  ui_story_5080_50801500_23_dialog_content = "噢噢噢！還用你說，本大爺早就練過了，你就等著看吧！",
  ui_story_5080_50801500_24_dialog_content = "真的假的，這麼好騙……喂！我這裡還有洗菜機，你要不要啊？",
  ui_story_5080_50801500_25_dialog_content = "營地亂糟糟的，伊芙也想幫忙。",
  ui_story_5080_50801500_26_dialog_content = "我也來。",
  ui_story_5080_50801500_27_dialog_content = "都走開都走開，別想搶本大爺的風頭！",
  ui_story_5080_50801500_28_dialog_content = "你們就讓他去弄吧，免得又鬧起來。",
  ui_story_5080_50801500_29_dialog_content = "青瞳——青瞳——妳在哪？",
  ui_story_5080_50801500_30_dialog_content = "我快把人家庫房搬空了，今晚妳可得和我一醉方休！",
  ui_story_5080_50801500_31_dialog_content = "真是的，一群胡鬧的傢伙……",
  ui_story_5080_50801500_32_dialog_content = "我啊，不是什麼真正的老東西，只不過是半途來到這裡的臭小子罷了。",
  ui_story_5080_50801500_33_dialog_content = "艾斯特拉這麼大……只有這裡收容了無家可歸的伊芙和我。",
  ui_story_5080_50801500_34_dialog_content = "好不容易走到今天，我們終於可以憑靠自己的努力自給自足，與家人生活在一塊。",
  ui_story_5080_50801500_35_dialog_content = "我們終於不用看人臉色，不用害怕被拒絕。",
  ui_story_5080_50801500_36_dialog_content = "我還是……第一次從你嘴裡聽到這些話呢。",
  ui_story_5080_50801500_37_dialog_content = "我們這些古怪的刺頭，就像沙子一樣拼命磨合。說是鮮血淋漓也好，那證明我們早就血水相融了。",
  ui_story_5080_50801500_38_dialog_content = "所以，我很高興能和這些傢伙一起度過每一天。",
  ui_story_5080_50801500_39_dialog_content = "不管遇上什麼困難，都要一起努力追尋痛快生活。這就是我們的自由！",
  ui_story_5080_50801500_40_dialog_content = "所以，為了能每天都這樣胡鬧。我會一次次舉起扳手，擋在所有想打擾我們的傢伙面前！",
  ui_story_5080_50801500_41_dialog_content = "你是個了不起的領袖……醒山。",
  ui_story_5080_50801500_42_dialog_content = "那麼，我想拜託你。雖然我已經完成自身的任務，但我仍不滿足。",
  ui_story_5080_50801500_43_dialog_content = "如果有危險隱藏在這裡，我想和各位一起解決。",
  ui_story_5080_50801500_44_dialog_content = "況且那位前首領拯救過我姑姑，我無論如何也想彌補她的遺憾。",
  ui_story_5080_50801500_45_dialog_content = "那麼，我問妳——現在的妳，瞭解「犧牲」的意義了嗎？",
  ui_story_5080_50801500_46_dialog_content = "呵……",
  ui_story_5080_50801500_47_dialog_content = "咦？為什麼看著我們？",
  ui_story_5080_50801500_48_dialog_content = "我已經下定決心，為了不讓隊員擔心，我還是不要輕言犧牲了。",
  ui_story_5080_50801500_49_dialog_content = "但是……如果我們仍然陷入險境，我會為身邊的他們付出生命。",
  ui_story_5080_50801500_50_dialog_content = "無論如何，我也想保護和我攜手同行的人們。",
  ui_story_5080_50801500_51_dialog_content = "對——身為啟光軍人的我們，並非為了任務或是榮譽才會如此。",
  ui_story_5080_50801500_52_dialog_content = "而是因為我們想要「守護」眼前的一切。",
  ui_story_5080_50801500_53_dialog_content = "蕾切爾……",
  ui_story_5080_50801500_54_dialog_content = "即使讓身體化為烈火，照亮道路，延續他人的未來——這就是啟光的大義！",
  ui_story_5080_50801500_55_dialog_content = "我的祖祖輩輩都曾得到他人幫助，又為他人犧牲，我也不會例外！",
  ui_story_5080_50801500_56_dialog_content = "今後，我還會為了想要守護的心意而戰，成為啟光連綿不絕的防線——！",
  ui_story_5080_50801500_57_dialog_content = "雖然話好像還是差不多，眼神卻有模有樣了嘛。",
  ui_story_5080_50801500_58_dialog_content = "現在的妳，確定是自己在做出選擇了嗎？",
  ui_story_5080_50801500_59_dialog_content = "啟光的信念，是「一即是眾，眾既是一」。",
  ui_story_5080_50801500_60_dialog_content = "哪怕如此，我們仍能以自身意志，決定為什麼而戰，決定為什麼而犧牲。",
  ui_story_5080_50801500_61_dialog_content = "這份心意，永遠不會虛假……啊！",
  ui_story_5080_50801500_62_dialog_content = "現在的妳，還能找到自己心中的啟明之光嗎？",
  ui_story_5080_50801500_63_dialog_content = "怎麼了？蕾切爾隊長？身體還有哪裡不舒服嗎？",
  ui_story_5080_50801500_64_dialog_content = "……不，別擔心，薇絲。",
  ui_story_5080_50801500_65_dialog_content = "我只是……終於知道如何回答那個問題了。",
  ui_story_5080_50801500_66_dialog_content = "問題……？",
  ui_story_5080_50801500_67_dialog_content = "哼……看來，妳也總算明白自己在追尋什麼。",
  ui_story_5080_50801500_68_dialog_content = "好吧，我同意妳來參一腳調查了。",
  ui_story_5080_50801500_69_dialog_content = "不過妳這一身傷的， 也別太著急了。",
  ui_story_5080_50801500_70_dialog_content = "今晚留下來好好吃一頓，睡上一覺，把身體養好再說吧。",
  ui_story_5080_50801500_71_dialog_content = "嗯……不過……",
  ui_story_5080_50801500_72_dialog_content = "不過？",
  ui_story_5080_50801500_73_dialog_content = "就算我們是合作關係，但要是紅油扳手再作惡，我一樣會追究到底！",
  ui_story_5080_50801500_74_dialog_content = "如果你們玷污了那把扳手所代表的意志，我就會要你交出扳手。",
  ui_story_5080_50801500_75_dialog_content = "呃……",
  ui_story_5080_50801500_76_dialog_content = "想要的話，就自己過來拿啊。",
  ui_story_5080_50801500_77_dialog_content = "真是夠了，妳的啟光腦袋還是不夠正常啊。",
  ui_story_5080_50801500_78_dialog_content = "哈哈哈哈哈——",
  ui_story_5080_50801500_79_dialog_content = "笑什麼啦。",
  ui_story_5080_50801500_80_dialog_content = "我還是第一次看到醒山這麼無奈的樣子，哈、哈哈哈——",
  ui_story_5080_50801500_81_dialog_content = "真是的——",
  ui_story_5080_50801500_82_dialog_content = "老大！老大！你看這個！",
  ui_story_5080_50801500_83_dialog_content = "這是我們在收拾營地殘骸時找到的，好像是前代首領遺留的日記。",
  ui_story_5080_50801500_84_dialog_content = "是在一個被炸開的小盒子裡找到的……看來一直被藏著。",
  ui_story_5080_50801500_85_dialog_content = "……我知道了。總之，先把這個收起來吧。",
  ui_story_5080_50801500_86_dialog_content = "現在可是派對時間，別的事情就放到明天去煩惱吧——我們走！",
  ui_story_5080_50801500_87_dialog_content = "知道啦知道啦，不要推嘛……好痛！",
  ui_story_5080_50801500_88_dialog_content = "現在輪到我笑了！哈哈哈哈哈——",
  ui_story_5080_50801500_89_dialog_content = "猛禽小姐，請等一下。",
  ui_story_5080_50801500_90_dialog_content = "怎麼了嗎？",
  ui_story_5080_50801500_91_dialog_content = "我想告訴妳，阿塔爾跟我講的故事最後部分。",
  ui_story_5080_50801500_92_dialog_content = "當年她拯救隊友而放棄任務後，就離開了啟光。失去目標，她曾漫無目的地流浪了一段時間。",
  ui_story_5080_50801500_93_dialog_content = "不知不覺，她來到這片讓自己任務失敗、且宿敵仍存的沙漠。",
  ui_story_5080_50801500_94_dialog_content = "她說，自己出生在這片沙漠上。她知道，這片沙漠無法無天，卻又自由自在，只是她從未在這裡生活。",
  ui_story_5080_50801500_95_dialog_content = "所以她很想來這裡看看。至少，她想為自己犧牲的隊員們尋找一片安息之地。",
  ui_story_5080_50801500_96_dialog_content = "……",
  ui_story_5080_50801500_97_dialog_content = "結果她在流浪中遇上遊匪，又陰錯陽差帶領他們去對抗暗鬼，並撿到那把傳說中的扳手。",
  ui_story_5080_50801500_98_dialog_content = "為了那些人，她舉起扳手，統合沙漠裡的遊匪，終結了這片沙漠的混亂。",
  ui_story_5080_50801500_99_dialog_content = "她帶領那些人在綠洲定居，也得知了扳手上的傳說故事。",
  ui_story_5080_50801500_100_dialog_content = "正因此，她為那扳手染上綠洲開採的紅油，正式成立了——「紅油扳手」。",
  ui_story_5080_50801500_101_dialog_content = "她過得很好，不僅尋得真正的自由，到最後也是守護一切而死。",
  ui_story_5080_50801500_102_dialog_content = "為什麼……想告訴我？",
  ui_story_5080_50801500_103_dialog_content = "請妳回去告訴妳的姑姑吧。",
  ui_story_5080_50801500_104_dialog_content = "她的隊長並非漫無目的地叛逃，由始至終，她都為了他人的自由高舉武器。",
  ui_story_5080_50801500_105_dialog_content = "希望能讓妳的姑姑獲得一絲安慰。",
  ui_story_5080_50801500_106_dialog_content = "謝謝……除此之外，我不知道該如何表達感激。",
  ui_story_5080_50801500_107_dialog_content = "唱吧，猛禽小姐，妳難道沒有聽到歌聲嗎？",
  ui_story_5080_50801500_108_dialog_content = "歌聲……？",
  ui_story_5080_50801500_109_dialog_content = "熊熊燃燒吧，心愛的樂園，我們的家——",
  ui_story_5080_50801500_110_dialog_content = "唱吧，唱吧，哪怕明天的世界仍然千瘡百孔——",
  ui_story_5080_50801500_111_dialog_content = "也要放聲歌唱……那就是……生命的力量。",
  ui_story_5080_50801500_112_dialog_content = "蕾切爾隊長～這裡～！宴會要開始了——",
  ui_story_5080_50801500_113_dialog_content = "呵……我現在就來！",
  ui_story_5080_50801500_114_dialog_content = "……我也是時候……",
  ui_story_5080_50801500_115_dialog_content = "妳想去哪？拿去。",
  ui_story_5080_50801500_116_dialog_content = "這是……",
  ui_story_5080_50801500_117_dialog_content = "仙人掌烤晶蠍肝。很好吃喔，妳一定沒有嚐過。",
  ui_story_5080_50801500_118_dialog_content = "……在我不知道的地方，你們也努力探索了許多呢。",
  ui_story_5080_50801500_119_dialog_content = "哼，那還用說。",
  ui_story_5080_50801500_120_dialog_content = "我說……耶利亞，偶爾也回家來，一起吃頓飯吧。",
  ui_story_5080_50801500_121_dialog_content = "……看來，這頓宴會是避不開了，對吧？",
  ui_story_5080_50801500_122_dialog_content = "那還用說？快來！",
  ui_story_5080_50801500_123_dialog_content = "蕾切爾，這裡這裡，我留了位置給妳。",
  ui_story_5080_50801500_124_dialog_content = "等肉烤好了一定要快點下手喔，他們真的是完全不講情面的！",
  ui_story_5080_50801500_125_dialog_content = "謝謝你……謝謝你們。",
  ui_story_5080_50801500_126_dialog_content = "什麼？這只是小事啦。",
  ui_story_5080_50801500_127_dialog_content = "不……是謝謝你們對我一直以來的包容。",
  ui_story_5080_50801500_128_dialog_content = "握個手吧，這也是啟光的禮儀。",
  ui_story_5080_50801500_129_dialog_content = "……嗯！",
  ui_story_5080_50801500_130_dialog_content = "真奇怪，明明你是個罕見的空裔，為什麼會給我一種親切的感覺呢？",
  ui_story_5080_50801500_131_dialog_content = "對我也沒什麼意見，妳似乎見慣了啟光人。",
  ui_story_5080_50801500_132_dialog_content = "（該從何說起呢？我們的旅途……和克、雷文頓、萊因哈特、巴頓，還有大家……）",
  ui_story_5080_50801500_133_dialog_content = "PlayerName，我剛剛說過的，一起吧。",
  ui_story_5080_50801500_134_dialog_content = "嗯！",
  ui_story_5080_50801500_135_dialog_content = "為了啟明之光！向您致敬！",
  ui_story_5080_50801500_136_dialog_content = "謝謝妳救了我，還有薇絲！",
  ui_story_5080_50801500_137_dialog_content = "何等標準的軍禮……呵呵，看來你們一定經歷了許多，所以才會是傳奇搭檔。",
  ui_story_5080_50801500_138_dialog_content = "我明白了，為什麼大元帥大人會說你們很特別。",
  ui_story_5080_50801500_139_dialog_content = "但是眼下，你們是我的夥伴……",
  ui_story_5080_50801500_140_dialog_content = "一起痛快地享受晚餐吧，大家！",
  ui_story_5080_50801500_141_dialog_content = "<color=#e8d9bb>紅油扳手的歌聲粗糲，卻透露出無比的灑脫，自由又浪蕩。那熱情點燃沙漠，天空響徹不夜狂歌。</color>",
  ui_story_5080_50801500_142_dialog_content = "梅麗……路易……塔爾斯……莉娜，你們還聽得到嗎？",
  ui_story_5080_50801500_143_dialog_content = "他們說，這片沙漠是可以包容所有靈魂的土地……所以……",
  ui_story_5080_50801500_144_dialog_content = "也一定容得下你們。",
  ui_story_5080_50801500_145_dialog_content = "飛吧……在自由的夜裡。",
  ui_story_5080_50801500_146_dialog_content = "直到你們的靈魂得以安息。"
}
return config
